const val GALLERY_TIER = "Free"

val blockRegistry: List<Block> = listOf(
    Block(slug = "particle-dispersion", name = "Particle Dispersion", category = "Animations", spec = "A full-screen camera captures a photo, isolates its foreground subject on device, and disperses the background into colored GPU particles over a warm brown canvas. The cutout lifts forward with a soft shadow and warm scan, then settles into a clean result. Replay reuses the photo; cancel discards it and returns to the live camera.") { ParticleDispersionDemo() },
    Block(slug = "pixel-wing-flight", name = "Pixel Wing Flight", category = "Animations", spec = "A white eagle made of a square dot grid flaps through a grainy cobalt sky and soft passing clouds. Hairline tracking bounds follow its wings beside the rotated caption Grow wings and fly. Quiet flight-session copy and a pause control frame the scene; dragging scrubs the same wingbeat.") { PixelWingFlightDemo() },
    Block(slug = "orb-ring-morph", name = "Orb to Ring Morph", category = "Animations", spec = "A full-screen splash sequence on a near-black screen. A split blue orb pulses, spins and grows into a dark glass sphere inside a soft halo; a ring of four gradient arcs draws around it, flattens into a glowing vertical pill, and the pill opens into a rounded card with a ring icon before the orb returns. Tap to play it once; hold to freeze it.") { OrbRingMorphDemo() },
    Block(slug = "gem-orb-collect", name = "Gem Orb Collect", category = "Animations", spec = "A reward screen where twenty floating lights collect into a seven-sided royal-blue crystal with a luminous pink-white star, glossy violet facets and an iridescent cyan rim. A smoked-glass balance capsule and cut-crystal Collect bar complete the dark indigo composition. A Skia runtime shader traces refraction, internal star reflections and RGB dispersion with an adaptive optical budget.") { GemOrbCollectDemo() },
    Block(slug = "prism-sphere-generating", name = "Prism Sphere Generating", category = "Animations", spec = "A waiting screen for something being generated: a two-line headline, a caption that comes and goes, and between them one luminous ball on a near-black page with a soft violet glow under it. The ball is a pleated, frosted, translucent shell that fills it to the rim: a fan of soft lavender leaves hinged on one axis, half open as a thick-walled bowl whose hollow is smoky and dark, spreading until the pleats radiate from the hinge all the way round. Press the ball and light gathers in it, let go and a burst runs out through the pleats; drag it and the shell turns under your finger. Nothing is a 3D model or an image: one fragment shader traces the shell's walls and composites them as sheets of frost on every frame.") { PrismSphereGeneratingDemo() },
    Block(slug = "shatter-glass-transition", name = "Shatter Glass Transition", category = "Animations", spec = "A full-screen photo behind glass, with \"Behind Glass\" and \"Tap to break · swipe back to mend\" in small type along the top and, at the bottom, the photo's number (\"02 / 04\"), title and a one-line caption over a soft shade. Tapping the glass cracks it from the touch point: white cracks race out like a spider's web and a frosted bruise marks the impact, then the pane breaks into shards, small near the impact and large towards the edges, that fall and spin away with light glinting on their edges, revealing the next photo underneath as it settles from slightly larger and darker. Swiping back does it in reverse: the previous photo's shards rise from below, follow the finger and fit back together, and the cracks close up into the point they came from. The photos are a star-forming nebula, two jellyfish and a liquid-chrome study.") { ShatterGlassTransitionDemo() },
    Block(slug = "supercharge-card", name = "Supercharge Card", category = "Animations", spec = "A glass card standing in a paper sleeve on a near-black page, with a bolt-shaped lamp in front of the glass and a ring light on the sleeve's notch; at rest it is dark, smoked glass with an ember in the lamp. Press and hold the card: thin arcs jump from the lamp across the glass and to your finger, gold light rises in the glass like a liquid, the ring fills as a gauge and the card shakes harder. Let go when it is full and lightning comes down the whole screen through the card: one white frame, a Lichtenberg figure burned into the glass, sparks, and the title gains its last letter, \"Supercharged\". Let go early and the light drains back; tap the charged card to let it go. The object (glass, lamp, paper, ring, their bloom and the light they throw on each other) is one fragment shader, and every bolt is generated, branching and different each time.") { SuperchargeCardDemo() },
    Block(slug = "depth-field-gallery", name = "Depth Field Gallery", category = "Animations", spec = "Cards floating in space on a white screen, scattered in depth so the near ones are large and the far ones tiny, and in each view one card fills most of the width just off the middle while a dozen smaller ones float around it out to the edges. The cards make up an invented identity: some forty portraits, profiles, fashion shots and busts printed in black and white or black on lime, lime cards with a cluster of black dots of many sizes, near-black cards with icons drawn in white dots (a magnifier, a cross of arrows, a figure, a basket), dark cards with two glassy rows each led by a lime dot, framed posters with two lines of type over a portrait (\"Where depth meets focus\", \"Light finds its level\", \"Still air, clear sight\"), and an \"aloft\" wordmark with a square of lime dots. Each card is turned a little in space. Tiny tracked capitals sit along the top (\"Aloft Studio\", \"Depth Field\" and the card's number, \"07 / 49\"); at the bottom the card in view is named, a small note in capitals over its title, beside a small switch with a lime knob. The switch turns the scene to near black, the dark cards keeping a faint edge.") { DepthFieldGalleryDemo() },
    Block(slug = "ember-charge-widget", name = "Ember Charge Widget", category = "Animations", spec = "A dark glass activity widget with a Walk header, three metrics, a striped light-filled bar and a step count beside a pulsing heart. Hold the card to raise and heat its ember light while the count advances toward the daily goal; reaching it ignites the glass, and releasing early lets it cool.") { EmberChargeWidgetDemo() },
    Block(slug = "flare-notifications", name = "Flare Notifications", category = "Animations", spec = "Three notification pills, each with a small fire burning at its trailing cap. A notification arrives and ignites; tap to read it and the fire cools to an ember, tap again to relight it, hold to stoke it. Each flame is 32 soft color blobs fitted against a reference clip and drawn by one fragment shader, so it flows without flicker.") { FlareNotificationsDemo() },
    Block(slug = "word-drum", name = "Word Drum", category = "Animations", spec = "A column of bold blue words on a black screen, set like the spokes of a large wheel whose hub lies off the right edge. The word in front sits just below the middle in a bright sky blue, a little larger than the rest, with an arrow pointing at it from the left; the words above it rise to the right and the words below fall away, each a step further round, dimmer, more blurred and slightly further left. A small \"What we bring\" sits above and \"Swipe to turn · Tap to choose\" below. Choosing the word in front sweeps four blue stripes across the screen, from deep to pale, and leaves the word alone over the line \"built into everything we ship.\" and \"Tap to turn again\".") { WordDrumDemo() },
    Block(slug = "expressive-orb", name = "Expressive Orb", category = "Animations", spec = "A white orb with two eyes that changes mood, modeled on the animated Orb from x.ai/bot. A grid of 12 expression thumbnails sits below it; tapping one switches the face.") { ExpressiveOrbDemo() },
    Block(slug = "particle-sign-in-ring", name = "Particle Sign-In Ring", category = "Animations", spec = "A signing-in screen modeled on Apple's iCloud sign-in. The user's avatar sits inside four concentric rings of colored dots while app icons take turns popping out of the ring, with the name and a \"Signing in…\" label below.") { ParticleSignInRingDemo() },
    Block(slug = "heart-like-burst", name = "Heart Like Burst", category = "Animations", spec = "A like button in the style of X. A grey outlined heart sits on a black screen; tapping it fills it red behind an expanding ring and a burst of coloured dots, and tapping again clears it.") { HeartLikeBurstDemo() },
    Block(slug = "cashback-confetti", name = "Cashback Confetti", category = "Buttons", spec = "A rewards screen on a black-to-plum field with a tilted paper banknote and a fine violet cashback capsule. Claiming the reward rolls its payout to \$45, flicks curled magenta confetti sideways and sends two thin oval waves around the capsule. A lifetime balance and a pale lilac claim button complete the screen.") { CashbackConfettiDemo() },
    Block(slug = "apply-check-button", name = "Apply Check Button", category = "Buttons", spec = "A lime green pill button labelled \"Apply\" in dark text on a light grey screen. Tapping it lights a lime glow and a pale ring around the pill, then turns the pill charcoal with a white check mark before it returns to lime.") { ApplyCheckButtonDemo() },
    Block(slug = "arrow-expand-button", name = "Arrow Expand Button", category = "Buttons", spec = "A text button reading \"LEARN MORE\" in bold dark ink with a dark circle holding a white chevron at its left, on a pale blue screen. While pressed, the circle stretches across the whole button into a dark pill, the chevron becomes an arrow and the label turns white.") { ArrowExpandButtonDemo() },
    Block(slug = "avatar-call-button", name = "Avatar Call Button", category = "Buttons", spec = "A black pill button, 164 by 52 pt, labelled \"BOOK A CALL\" in white with a soft light along its inner edge, on a light grey screen. While pressed, the label gives way to two round avatars, a coral one with the initials \"JD\" and a white one reading \"YOU\", joined by a plus sign, which then slide together beside the message \"Let's talk!\".") { AvatarCallButtonDemo() },
    Block(slug = "day-night-toggle", name = "Day Night Toggle", category = "Buttons", spec = "A 116 by 54 pt switch that shows a landscape instead of a plain track. Off is night: a dark blue track with eight stars, a crescent moon and three blue ridges, the round off-white knob on the left; on is day: a yellow track with a glowing white sun and golden dunes, the knob on the right. The screen behind it changes from pale blue to cream.") { DayNightToggleDemo() },
    Block(slug = "depth-button", name = "Depth Button", category = "Buttons", spec = "A group of four chunky push buttons in a two-by-two grid on a cream screen: Share and Follow in blue, Like in orange-red and Play in red, each with a white icon and label. Every button is a flat 46 pt face with 5 pt corners sitting on a darker side wall 9 pt deep; pressing sinks the face into the wall.") { DepthButtonDemo() },
    Block(slug = "galaxy-button", name = "Galaxy Button", category = "Buttons", spec = "A near-black pill button labelled \"JOIN TODAY!\" in spaced light grey letters with a thin dim border, on a deep navy screen. When lit, a cyan light travels around the border, brightening the stretch of edge near it and tinting the glass from inside, surrounded by a soft blue haze and a scatter of pale blue dust.") { GalaxyButtonDemo() },
    Block(slug = "generate-button", name = "Generate Button", category = "Buttons", spec = "A pill button labelled \"Generate Site\" with an icon of three four-point sparkles, on a near-black screen. At rest it is dark grey with a grey label and icon; lit, it turns violet with a white label and icon, a lighter glow along its bottom edge, a translucent violet ring, a blurred violet aura and 34 small lavender stars scattered around it.") { GenerateButtonDemo() },
    Block(slug = "generate-fill-button", name = "Generate Fill Button", category = "Buttons", spec = "A black pill button, 168 by 58 pt, with a white four-point sparkle and the bold white label \"Generate\", on a white screen. Tapping it fills the pill from the left with a violet-to-blue-to-cyan gradient whose colours keep shifting while the label reads \"Generating\", then it fades back to black.") { GenerateFillButtonDemo() },
    Block(slug = "glass-loading-button", name = "Glass Loading Button", category = "Buttons", spec = "A dark glass capsule, 172 by 118 pt with 54 pt corners, showing a large percentage number over the caption \"LOADING\" on a near-black screen. Blurred blue, magenta, red and green light sits just inside its rim while the centre stays dark, with a thin light border and a soft shadow underneath.") { GlassLoadingButtonDemo() },
    Block(slug = "glow-border-button", name = "Glow Border Button", category = "Buttons", spec = "A black pill button labelled \"Let me glow\" in white on a near-black screen. A white highlight lies along the top of its border, fading to violet and blue at both ends; while pressed, the highlight runs around the border led by a blue and magenta streak.") { GlowBorderButtonDemo() },
    Block(slug = "gradient-subscribe-button", name = "Gradient Subscribe Button", category = "Buttons", spec = "A pill button labelled \"SUBSCRIBE\" in spaced white capitals on a black screen. Its fill is a horizontal gradient of magenta, crimson and orange four button-widths long, of which the magenta end shows at rest; while pressed the colours slide through the button and a blurred glow of the same colours spreads around it.") { GradientSubscribeButtonDemo() },
    Block(slug = "iridescent-home-button", name = "Iridescent Home Button", category = "Buttons", spec = "A dark glass pill button, 64 pt tall, labelled \"Home\" in white, with a round well at its left end holding a silver house icon, on a black screen. The rim of the well carries patches of rainbow colour like an oil film and a white flare with a blue tail and an orange head, which casts a warm glow onto the pill.") { IridescentHomeButtonDemo() },
    Block(slug = "letter-wave-button", name = "Letter Wave Button", category = "Buttons", spec = "A black rectangular button with 2 pt corners labelled \"SWAGGER\" in small spaced white capitals, on an off-white screen. While pressed, orange and then navy sweep across it from the left with a round leading edge and the letters hop one after another; on release the colours pull back and the letters ripple the other way.") { LetterWaveButtonDemo() },
    Block(slug = "like-burst-button", name = "Like Burst Button", category = "Buttons", spec = "A round white like button, 64 pt across, with a red heart outline and a soft pink shadow, on a pale pink screen. Tapping it fills the heart red behind an expanding red ring and a burst of seven coloured dots; tapping again returns it to the outline.") { LikeBurstButtonDemo() },
    Block(slug = "liquid-split-button", name = "Liquid Split Button", category = "Buttons", spec = "A light grey glass pill labelled \"Select\" on a grey screen. Tapping it splits it like a drop of liquid into three pieces: two round buttons showing a circle outline and a triangle outline, and a pill labelled \"Done\" that merges them back into one.") { LiquidSplitButtonDemo() },
    Block(slug = "liquid-upload-button", name = "Liquid Upload Button", category = "Buttons", spec = "An upload button shown in four variants on a pale blue screen: a blue pill and a dark pill labelled \"Upload\" with an up arrow in a round well at the right end, and a dark and a light round button with the arrow alone. Tapping one fills the well with liquid while the label reads \"Uploading\", then draws a check mark and reads \"Uploaded\"; a second tap resets it.") { LiquidUploadButtonDemo() },
    Block(slug = "neon-download-button", name = "Neon Download Button", category = "Buttons", spec = "A dark pill button, 220 by 52 pt, with a glowing cyan outline, a round cyan knob holding a white down arrow at its left end and the thin white label \"download\", on a dark grey screen. Tapping it shrinks the pill to a circle that shows progress as a white dot circling the outline, then reopens it with a green outline and the word \"done!\" before it returns to its first state.") { NeonDownloadButtonDemo() },
    Block(slug = "order-truck-button", name = "Order Truck Button", category = "Buttons", spec = "An order button that plays out a delivery inside itself. A dark navy pill labelled \"Complete Order\" sits on a pale blue screen; tapping it shows a parcel being loaded into a white and blue truck seen from above, which drives off along a dashed road before the pill reads \"Order Placed\" with a green check.") { OrderTruckButtonDemo() },
    Block(slug = "pay-scan-button", name = "Pay Scan Button", category = "Buttons", spec = "A payment button that turns into a face scan. A lavender pill on a pale cyan screen shows a card icon and \"PAY\" in near-white; tapping it shrinks the pill to a circle where the card becomes a scan frame around a small face, then widens it again to read \"COMPLETE\" before returning to PAY.") { PayScanButtonDemo() },
    Block(slug = "pricing-segmented-button", name = "Pricing Segmented Button", category = "Buttons", spec = "A two-level pricing switch. A near-white pill-shaped track with a thin grey border and a soft shadow, on a white screen, is split into Free and Premium with a black pill behind the selected half; choosing Premium opens the black pill into a second switch, Monthly and Annual, with its own white pill.") { PricingSegmentedButtonDemo() },
    Block(slug = "pulse-fab-button", name = "Pulse Fab Button", category = "Buttons", spec = "A round floating action button: a yellow disc with a white plus on a very pale blue screen. A translucent yellow halo keeps pulsing outward from its edge, and a tap sends out one larger halo.") { PulseFabButtonDemo() },
    Block(slug = "record-button", name = "Record Button", category = "Buttons", spec = "A voice recording button. A grey glass sphere with a white microphone sits on a black screen with a faint reflection below it; tapping it opens a dark pill behind the sphere, turns the sphere red with a pulsing record dot and shows a running timer in MIN. and SEC. columns on either side, and tapping again flashes it green and closes it.") { RecordButtonDemo() },
    Block(slug = "reload-button", name = "Reload Button", category = "Buttons", spec = "A reload button with a working state. A pale blue rounded rectangle on a light grey screen shows a two-arrow refresh icon and \"Reload\" in blue; tapping it collapses it to a square around the icon, the icon spins, and the button turns green and opens again before going back to blue.") { ReloadButtonDemo() },
    Block(slug = "share-reveal-button", name = "Share Reveal Button", category = "Buttons", spec = "A share button with a sliding cover. An indigo pill-shaped tray on a dark navy screen is filled by a white cover labelled \"SHARE\"; tapping it slides the cover away to the left, leaving a narrow tab, and reveals four white line icons for message, mail, copy link and more.") { ShareRevealButtonDemo() },
    Block(slug = "slide-to-book-button", name = "Slide To Book Button", category = "Buttons", spec = "A slide-to-confirm button. A black pill on an off-white screen holds a lime green knob with a dotted arrow and the grey label \"Book a call\"; tapping it or sliding the knob to the right stretches the knob across the whole pill, swaps the arrow for a phone icon and pops a small pale green \"Call booked\" tag above.") { SlideToBookButtonDemo() },
    Block(slug = "smoke-button", name = "Smoke Button", category = "Buttons", spec = "A call-to-action button filled with drifting smoke. A black pill on a black screen carries a glowing white \"Get Started\" label; pale smoke and a few twinkling dust motes gather toward its right end, where the rim is lit, with a faint white halo behind.") { SmokeButtonDemo() },
    Block(slug = "squish-toggle", name = "Squish Toggle", category = "Buttons", spec = "A soft, physical-looking on/off switch. A recessed pill-shaped track on a light grey screen is grey when off and green when on, with a bevelled off-white round thumb that stretches as it slides.") { SquishToggleDemo() },
    Block(slug = "submit-confetti-button", name = "Submit Confetti Button", category = "Buttons", spec = "A submit button with loading and success states. A navy pill on a pale blue screen shows a blue down arrow and \"Submit\" in white; tapping it narrows the pill around three blue loading dots, then it springs open with a burst of blue and violet confetti and reads \"Success\" with a green check.") { SubmitConfettiButtonDemo() },
    Block(slug = "tally-counter-button", name = "Tally Counter Button", category = "Buttons", spec = "A counter from 0 to 99 on a dark grey screen: a slightly darker pill with a minus on the left, a plus on the right and a lighter round knob in the middle showing the count in white. The count changes by tapping either sign or the knob or by dragging the knob sideways, and resets when the knob is pulled down.") { TallyCounterButtonDemo() },
    Block(slug = "thinking-button", name = "Thinking Button", category = "Buttons", spec = "A status pill for an assistant at work. A glass-rimmed pill on a charcoal screen shows a white label that steps through \"Thinking...\", \"Searching...\" and \"Planning...\", each over its own moving fill: a rainbow wave above pale fog, slanted silver and black bands behind six fluted glass strips, and blue meeting red along a wavering pink seam.") { ThinkingButtonDemo() },
    Block(slug = "ticket-button", name = "Ticket Button", category = "Buttons", spec = "A ticket button with a colour sweep. A white square-cornered slab on a dark plum screen reads \"GET TICKET\" in bold dark monospace capitals; while it is held, teal rises to fill it and the label rolls over to white.") { TicketButtonDemo() },
    Block(slug = "tilt-button", name = "Tilt Button", category = "Buttons", spec = "A button that tilts in 3D toward the finger. A pill with a violet-to-blue diagonal gradient on a black screen carries a white bold \"BUTTON\" label that appears to float above its surface.") { TiltButtonDemo() },
    Block(slug = "touch-glow-button", name = "Touch Glow Button", category = "Buttons", spec = "A button lit by touch. A dark indigo rounded rectangle on a near-black navy screen has a thin violet border and a white \"Button\" label; a soft glow inside it and a bright stretch of the border follow the finger, the glow violet toward the left and blue toward the right.") { TouchGlowButtonDemo() },
    Block(slug = "city-event-hero", name = "City Event Hero", category = "Cards", spec = "An event hero over a full-bleed city photo that is really a spatial scene: the photo is split into depth layers (sky, city, the tower, the near towers) that part as the camera moves. One evening plays over it: the sun swings round the tower like a sundial while the hour floats in the sky behind the tower, night falls floor by floor, and View event turns the tower into a giant LED screen that says SEE YOU THERE, counts the date down to 17 JAN and carries the viewer's portrait up the spire until it ignites into fireworks that relight the city, the title, the guests' rings and the glass. Drag the sky to scrub the hour, tap View event for the show, tilt the phone to look around the tower.") { CityEventHeroDemo() },
    Block(slug = "grass-timer-carousel", name = "Grass Timer Carousel", category = "Cards", spec = "A dark focus screen pairs nature cards with circular soundscape controls and sleep stories. Hold a duration chip and the same photograph becomes a circular focus timer; release early to settle back, or stop the active timer to return to its card.") { GrassTimerCarouselDemo() },
    Block(slug = "paddock-widget-bento", name = "Paddock Widget Bento", category = "Cards", spec = "A bold racing dashboard laid out as a bento of colour stickers, under an iOS 26 Liquid Glass dock. Pull the feed down and a pit crew rebuilds it, drag the corner of the \"exclusive widgets\" sticker to peel it, and hold a quick card to rearrange the three with gooey neighbours. Race notes, a searchable glossary, short lessons and a widget studio make every tile useful.") { PaddockWidgetBentoDemo() },
    Block(slug = "colour-orbit-cards", name = "Colour Orbit Cards", category = "Cards", spec = "Three portrait debit cards orbit on a clean off-white page: a silver bear print, a bright geometric print and a pale typographic print. Foreshortened edges, soft rear-card focus and moving highlights establish depth above a short headline and down chevron. The block recreates the opening carousel of the reference with original artwork and the invented Heirlo card identity.") { ColourOrbitCardsDemo() },
    Block(slug = "lenticular-edition-pass", name = "Lenticular Edition Pass", category = "Cards", spec = "A lightly bowed landscape art card reveals two original geometric prints through persistent vertical lenticules. Tilt the laminated card to move the narrow interleaved transition across its surface, choose a view, or add the invented edition to a local confirmation state.") { LenticularEditionPassDemo() },
    Block(slug = "dreambook-hinge-journal", name = "Dreambook Hinge Journal", category = "Cards", spec = "A gray clothbound dream journal swings diagonally as its cover parts and two silver paper panels unfold across a horizontal crease. Measured perspective corners, a cloth reverse and a waisted page silhouette give the opening a physical presence before the paper expands into a full-screen composer. A serif date, a two-action footer and a calendar frame Night Atlas.") { DreambookHingeJournalDemo() },
    Block(slug = "wallet-first-deposit", name = "Wallet First Deposit", category = "Cards", spec = "A wallet moves from verification to its first deposit. A blue debit card lifts out of the verification banner and docks in the header while the balance, transactions, payees and spending chart reveal the funded state.") { WalletFirstDepositDemo() },
    Block(slug = "swipe-down-deck", name = "Swipe Down Card Deck", category = "Cards", spec = "A dark card browser with a deck tray at the bottom. Swipe sideways to browse the cards, or pull one down: it shrinks and tilts after the finger while the tray lifts and glows in the card's colour, then drops into the tray as the front of a stack while the next card springs in from the right. Filter chips, an add button on each card and a deck counter complete the screen.") { SwipeDownDeckDemo() },
    Block(slug = "bento-expand-grid", name = "Bento Expand Grid", category = "Cards", spec = "A bento of seven field notes on warm paper under a serif \"Slow crafts\" title: a tall photo of a desk, a near-black tile with \"1,284 pages\" read this season, a photo of tea being poured, a little map of a riverside walk drawn in thin lines with a dashed route and an orange pin, a wide quote tile (\"The hands remember what the mind forgets.\"), a tall photo of clay-covered hands and a wide photo of a reading room. Tapping a tile grows it in place into its own page while the other tiles are pushed away and fade, nearest first: the photo, map or number becomes the page's header and a paper sheet slides up over it with a kicker, a serif title, a byline, a lead, a pull quote with an orange rule and two photos side by side. Scrolling slides the sheet over the header, which drifts up more slowly; dragging the page down from the top shrinks it into a floating card under the finger, and letting go puts it back in its tile.") { BentoExpandGridDemo() },
    Block(slug = "mood-card-shuffle", name = "Mood Card Shuffle", category = "Cards", spec = "A mood-based place finder over a full-screen, softly blurred and muted copy of the front card's photo, with \"Where do you feel like going?\" set large and centred at the top. In the middle sits a deck of four landscape photo cards arranged like a drum: the front one upright and the next and previous ones peeking out on either side, smaller, darker and turned away in 3D. The front card carries a white \"Curated\" chip, a round bookmark button, a small-caps region line (\"Yên Bái · Vietnam\"), the place's name and a two-line blurb. A frosted \"Search places…\" pill sits under the deck, and a white sheet at the bottom holds the mood chips (Quiet, Nature, Artisanal Food, Wild) with a sliding black pill on the chosen one, and a \"Go Unexpected\" row with a round shuffle button. Swiping turns the deck: the front card swings out to the side and tucks in behind while the next one slides in over it and straightens up, and picking a mood riffles the deck into a pile and deals out a new set of places.") { MoodCardShuffleDemo() },
    Block(slug = "pet-rock-carousel", name = "Pet Rock Carousel", category = "Cards", spec = "A carousel of painted pet rocks on warm off-white paper. It opens on the title \"PET ROCK\" with a tiny stone sitting in the gap between the words and a black Enter pill at the bottom; Enter grows that stone into the carousel while the letters slide apart and fade. Each rock is an irregular pebble drawn on a canvas, its surface a river-stone photo in soft light over a base tone, with grain, flecks, a rim shadow and a soft contact shadow, and it wears a face: googly eyes whose pupils roll with the motion, a grumpy yellow emoji, a red LOVE heart, a teal graffiti tag, a purple grin or a sleepy face. The rock in front is large, the ones above and below smaller and tilted; dragging scrolls the column and a release snaps to a rock, which then blurs its paint into a new expression while its eyes jiggle. Tapping the front rock squashes it and makes it wobble; the caption shows the rock's name, mood and number.") { PetRockCarouselDemo() },
    Block(slug = "aura-wallet-widget", name = "Aura Wallet Widget", category = "Cards", spec = "A square wallet widget of smoked glass: a cushion of violet light holding the balance, five friends hanging on its lower lip, the last transaction on a pane of glass, and four pillow buttons. Sending is letting a drop fall: tap a friend and the pool wraps them in a drop; pull it down and its neck stretches while the amount climbs ten dollars a step and the balance rolls with the finger; let go and the neck snaps, the drop lands on the pane, and the ripple it sends writes the new transaction. One runtime shader draws the glass, the cushion, the drop and the pillows; type, faces and touch are views over it.") { AuraWalletWidgetDemo() },
    Block(slug = "boarding-pass-stack", name = "Boarding Pass Stack", category = "Cards", spec = "A dark navy panel with a destination header and a wallet of boarding passes. The header shows the city in large thin type (\"Lisbon\"), \"DESTINATION\" in small capitals, and a row of three items between dashed rules: \"19:30 Arrival time\", \"Book a ride\" and \"18:30 Local time\". Below it three passes are stacked in amber, coral and mint, the two behind showing only their strip with the airline, gate and seat; the front one is complete, with the route in large thin letters (\"BER\", a small plane, \"LIS\"), the flight, date, boarding time and class, the passenger, and a stub with a drawn QR code under a perforated tear line with a half-round notch at each end.") { BoardingPassStackDemo() },
    Block(slug = "cutout-window-card", name = "Cut-Out Window Card", category = "Cards", spec = "A tall rounded panel filled by a travel photo, with a cream card standing in its middle. The top of the card is a window onto the same photo, lined up with the one behind, so the card looks cut out; below it are a heavy dark green title (\"Winter Breaks\"), four tiny lines (\"DATE 11 Apr 2024\", \"FROM London Gatwick\", \"FOR 14 Nights\", \"BOARD Half Board\") and a row of four small line pictograms. Three trips share the panel, each with its own photo, title, details and pictograms.") { CutoutWindowCardDemo() },
    Block(slug = "departure-board-ticket", name = "Departure Board Ticket", category = "Cards", spec = "A tall boarding pass on a near-white screen. Its black top carries a row of five small fields (gate, seat, boarding, departure, date) and two airport codes, \"HKG\" and \"LHR\", drawn in square white dots like a departure board with the airport names under them; lower down the black runs into an aurora of cyan, royal blue and violet. A perforated line between two half-circle notches separates a pale blue stub with the route in small dots, the date and a barcode. The codes and fields flap through other glyphs before they land, and the stub can be torn off and snaps back.") { DepartureBoardTicketDemo() },
    Block(slug = "destination-swipe-stack", name = "Destination Swipe Stack", category = "Cards", spec = "A deck of dark destination cards on an off-white screen with a soft coloured glow behind it. The front card shows a small line icon, a round arrow button, a two-line title in thin capitals (\"AMA DABLAM\" over a grey \"HIMALAYA\"), an inset photo with a small pill (\"12 days · \$2,490\") and two lines of grey caption. Two more cards wait behind it as tilted, translucent grey ghosts, and the card swiped last lies below the stack, blurred and dim, fading out at the bottom edge.") { DestinationSwipeStackDemo() },
    Block(slug = "expanding-trip-card", name = "Expanding Trip Card", category = "Cards", spec = "A white panel headed \"TRIPS\", with a mint search button, a row of tall photo cards that snaps card by card and a three-icon tab bar. Each card carries its trip in white capitals (\"SEILAND NORWAY\", \"3 AUG - 9 AUG\") and two round badges, a blue one with a boot and a pink one with the number of days; the next card shows at the right edge. Under the row a hairline with a small notch points up at the current card, above its arrival details (\"ARRIVAL\", \"OSLO LUFTHAVN\", \"3 Aug, 12:00 PM\"). Tapping the current card grows it from its place until the photo fills the panel, with the title at the top left, a round back button and a row of white day cards (\"DAY 1\", \"3 Aug.\", \"Hiking\", a small map, \"8 hours\", \"22 km\").") { ExpandingTripCardDemo() },
    Block(slug = "fanned-guide-cards", name = "Fanned Guide Cards", category = "Cards", spec = "Three white photo cards fanned out on a pale screen with a faint diagonal grid: one on the left tilted back, one on the right tilted forward, and a larger one in front of both. Each card frames a travel photo with a dark \"Top rated\" tag, a round black arrow badge that the photo's corner curves around, the place's name and its location; the front card carries a black \"Book Now\" pill, the side cards a grey one. Tapping a side card brings it to the front, and the front card can be dragged aside.") { FannedGuideCardsDemo() },
    Block(slug = "flight-status-card", name = "Flight Status Card", category = "Cards", spec = "A square photo card on a light grey screen: the view over a plane's wing above the clouds, with a white panel across its lower half. The panel shows the departure and the arrival (a time, a bold airport code and the city), the flight number over a dashed line that a round black badge with a white plane travels along, the time left under it, and a pale outlined box with three small fields: airline, flight code and class. A dark status chip on the photo reads \"Boarding\", \"In flight\" or \"Landed\".") { FlightStatusCardDemo() },
    Block(slug = "frosted-destination-carousel", name = "Frosted Destination Carousel", category = "Cards", spec = "A row of tall photo cards on a pale rounded panel, on a light grey-blue screen; the row runs off both sides of the panel. Each card is a full photo whose lower half melts into a frosted tint of the photo's main colour, with the country's name in bold white beside a small flag-coloured dot, a line of small text (\"2,345 Hotels • 54 Packages\") and a darker bar reading \"Explore Now\" with a chevron. The selected card sits 20 pt higher than the others over a larger shadow of its own colour, and the panel behind it is washed in that colour.") { FrostedDestinationCarouselDemo() },
    Block(slug = "perspective-rolodex", name = "Perspective Rolodex", category = "Cards", spec = "An editorial rolodex of twenty-two photo cards on a black screen, seen from in front and a little below. The card in front stands upright a little above the middle, about half the width of the screen. Behind it the cards still to come climb away towards the top of the screen in a tall, tight stack, each one a step higher and further back, so only the rounded top edge of each shows as a thin coloured sliver above the next, a little darker the further back it is. Below it the cards already seen lie back face up towards the viewer, overlapping like cards dealt on a table: the last one just under the front card, each earlier one nearer, wider and a little darker, until they sink into the black at the bottom edge. Small light labels sit in the corners: \"Selected\", \"Content\" and \"For You\" along the top, with \"Content\" behind the stack, and \"Because\", the front card's category and \"Matters\" along the bottom, so it reads \"Because Ocean Matters\". Tapping the front card stands it up to nearly the full width and shows its number, title and a line about it underneath.") { PerspectiveRolodexDemo() },
    Block(slug = "postage-stamp-reveal", name = "Postage Stamp Reveal", category = "Cards", spec = "A place shown as a postage stamp on a panel of flat, grainy coloured paper: a cream stamp with a perforated edge and a soft shadow, its illustration drawn in flat shapes (a snowy hill with a purple hut, pink rock towers at sunset, sea stacks), with \"ITALIA\", a boxed \"B\" and the region printed on it. The place's name stands behind the stamp in huge capitals, split above and below it (\"MONTE\" / \"TOMBA\"), small stamps of the neighbouring places peek in from two corners, a dotted yellow trail wanders in from the left, and tiny labels run along the top with a line of coordinates along the bottom. Swiping moves to the next place; tapping opens it, the stamp growing until its illustration fills the panel with the name over the scene and a small \"CLOSE\" pill.") { PostageStampRevealDemo() },
    Block(slug = "referral-reward-card", name = "Referral Reward Card", category = "Cards", spec = "A \"Refer friends\" card of clear glass over colored light. A row of friends runs under a fixed lens, with the points they have earned above it, three reward marks in the corner and one button. Press it and the button becomes a comet that the lens ring catches and slings into a rolling counter; tap the friend under the lens and it opens into a capsule with their name and an Invite action.") { ReferralRewardCardDemo() },
    Block(slug = "resort-weather-card", name = "Resort Weather Card", category = "Cards", spec = "A ski resort inside a near-black panel: a header with a back arrow, \"Austria\" and a \"Map\" pill, a strip of four rounded photo thumbnails with the selected one larger and outlined, and a light grey card. The card's photo has a black pill at the top showing \"-8°C\" on a seven-segment display next to \"Temperature Currently\", three round badges with initials and small orange hearts at the bottom left, a translucent pill reading \"198 frosties\" at the bottom right, and light snow falling over it. Under the photo are four page dots, the name \"Obertauern Ski Resort\", \"Austria, Salzburg\" and a grey pill with three facts and their icons: \"26 ski runs\", \"112 km\", \"8 types\". Tapping a thumbnail shows that resort.") { ResortWeatherCardDemo() },
    Block(slug = "rising-tour-stack", name = "Rising Tour Stack", category = "Cards", spec = "A dark slate panel with a small bar (back arrow, \"Your Destination\", search), the city in huge condensed serif capitals (\"PARIS\") and, in its lower half, a stack of three tour cards. The front card is white, with a photo, a translucent chip holding a yellow star and \"4.5\", the bold title \"Eiffel Tower 2nd Floor or Summit Guided Tour\", a grey price pill (\"€ 99\") and two lines of description; the two cards behind it are plain grey, each narrower than the one in front, the last one leaning. Under the stack sit a green \"Available\" pill, a \"See on Map\" pill with a map icon and a round heart button. Swiping the front card up sends it away and brings the next destination forward (Rome, Venice); after the last one the deck is dealt again.") { RisingTourStackDemo() },
    Block(slug = "route-progress-card", name = "Route Progress Card", category = "Cards", spec = "A route planner that unfolds from two small dark pills on a light grey screen, \"From Alder Park\" and \"To Coral Bay\", with a violet \"Go\" button between them. Go merges the pills into a near-black card with a coloured glow across its top: a header with the leg's icon and name, a small progress ring and an outlined \"Next Step\" pill, the distance and the time in large light figures, a drawing of the leg (a thick track with a glowing knob for Walking, a road in perspective for Driving, an arc with a travelling dot for Flight) and the next two stops beside two small photos. The other legs wait as pills above and below the card, each in its own colour, and after the last one the card folds back into the two pills around a \"Done\" button.") { RouteProgressCardDemo() },
    Block(slug = "stamped-ticket-pile", name = "Stamped Ticket Pile", category = "Cards", spec = "A loose pile of four ticket-shaped cards on a pale pink backdrop, peach, off-white, lavender and yellow, each turned a different way and overlapping the others, with a half circle notched out of its bottom edge. A ticket carries a small date chip (\"Jul 11 – Sep 6\"), the trip's name on two black label strips with white text (\"Surfing and beaches\", \"Ancient Egypt adventure\"), a place with a pin, and a passport stamp printed in black, indigo or red ink: a triangle, a ring with lettering round it, a framed plate or an oval. The tickets are dealt from below and stamped one by one, and a tap sends the top one under the pile.") { StampedTicketPileDemo() },
    Block(slug = "stay-booking-card", name = "Stay Booking Card", category = "Cards", spec = "A large portrait photo card on a light grey screen. The photo fills the card and its lower part sinks, blurred, into a deep tint (dark green for the first stay) that carries three page dots, the name in white semibold (\"The Hill Guest House\"), an address line with a map icon, three facts with icons between thin rules (\"Bed: 2\", \"Baths: 1\", \"Sqft: 1150\"), a translucent pill with the price (\"\$620\") and a wide white \"Reserve Now\" button. Three stays share the card, each with its own photo and tint.") { StayBookingCardDemo() },
    Block(slug = "trail-photo-fan-card", name = "Trail Photo Fan Card", category = "Cards", spec = "A white trail card floating among soft clouds on a sky-blue screen. Its heavy two-line title \"Mountain Hike\" ends in an arrow, a tight deck of three framed mountain photos sits under it, and a row of three small facts (\"~8 Hours\", \"8 km\", \"Medium Level\") and three lines of grey text close the card. While the card is pressed the title turns olive and the deck opens into a rising fan of three tilted photos.") { TrailPhotoFanCardDemo() },
    Block(slug = "trail-route-card", name = "Trail Route Card", category = "Cards", spec = "A white trail card on light grey. Its upper two thirds are a mountain photo at sunset that darkens to near black at the bottom, where the trail's name (\"Embercrest Ridge\", \"Silverpine Mountains\") and a frosted grey \"Directions\" pill sit. Below are the difficulty (\"Hard\") with three small bars, three figures (\"12.4km Distance\", \"870m Elevation\", \"4h 45m Duration\") and a light grey rounded square with a line drawing of the route and a dot on it. Tapping the pill walks the trail: the route draws itself, the figures count up and a flag is planted at the end.") { TrailRouteCardDemo() },
    Block(slug = "travel-pass-stack", name = "Travel Pass Stack", category = "Cards", spec = "A tall dusk-violet panel holding a wallet of six travel passes seen in perspective: wide dark grey cards, each with a small line glyph, a name in white (\"Kestrel Heli Transfer\", \"First Light Lounge\", \"Northwind Charter\", …) and a wide photo, every card covering the lower part of the one above. Four cards sit at full size and the next peeks over the bottom edge; dragging scrolls the stack, and cards pushed past the top shrink, dim and blur as if they moved away.") { TravelPassStackDemo() },
    Block(slug = "travel-stat-story-card", name = "Travel Stat Story Card", category = "Cards", spec = "A dark statistics card on a warm grey screen that tells one travel fact at a time, like a story. An orange glow spreads from its top left corner behind a round category icon (\"Backpacking\"), an outlined \"Budget Travel\" pill and a round arrow button; below them a large thin \"35%\" stands over a bold line, two grey lines, two pill-shaped photos and a three-segment bar whose lit segment fills while the story is on screen. A tap moves to the next of three stories, each with its own glow colour (orange, teal, violet), labels, figure and photos.") { TravelStatStoryCardDemo() },
    Block(slug = "trip-album-folder", name = "Trip Album Folder", category = "Cards", spec = "A photo album shown as a folder on a very light grey screen: four white-bordered photos stick out behind a frosted pale grey front that has a tab on its upper left, two embossed lines near its bottom and two stickers, a perforated postage stamp with a red disc and a red shrine gate with a thick white outline. Under it are the album's name, \"Japan 2024\", and a grey pill reading \"83 photos\". Pressing makes the folder grow while the photos rise and fan out, and a tap drops them into the folder and brings up the next album, \"Iceland 2023\" with 124 photos, a flag stamp of its own and a mountain sticker.") { TripAlbumFolderDemo() },
    Block(slug = "typed-destination-card", name = "Typed Destination Card", category = "Cards", spec = "A destination picker from an onboarding screen on off-white: a portrait photo of a city crossed in the middle by a white search pill, wider than the photo, that holds a black map pin, the city's name (\"Paris\", \"Tokyo\", \"New York\") and a text caret. Under it sits a black pill button, \"Current location\", with a target icon. The name is typed and deleted letter by letter, and the photo changes to the city once its name is complete.") { TypedDestinationCardDemo() },
    Block(slug = "vitals-chip-morph", name = "Vitals Chip Morph", category = "Charts", spec = "Three screens of a health app — Readiness, Fitness and Heart — switched by a row of metric chips. The hero is one shape that becomes the next metric, and while it travels it turns to liquid glass: the gauge melts, its caps neck together into the activity rings, the rings flood into a jelly heart, and each heartbeat sends ripples through the heart. Tap a chip or drag the hero sideways; the chip selection travels as an iOS 26 Liquid Glass capsule.") { VitalsChipMorphDemo() },
    Block(slug = "night-sleep-score", name = "Night Sleep Score", category = "Charts", spec = "A pale sleep dashboard pairs a segmented score ring with an overnight stage timeline under a Liquid Glass tab bar. Replay the night or scrub the graph and the card turns into the night it describes: a sky that darkens from the top, an aurora hypnogram and a ring that fills in the stage colours, then dawn returns it to the light card.") { NightSleepScoreDemo() },
    Block(slug = "pulse-heart-card", name = "Pulse Heart Card", category = "Charts", spec = "A heart-rate summary built around a living heart: an ECG trace sweeps across it, and each R-peak makes the heart beat with weight, gloss and a pressure ripple through its halo. Scrub the range chart and the heart beats at that half hour's rate.") { PulseHeartCardDemo() },
    Block(slug = "sky-screen-time", name = "Sky Screen Time", category = "Charts", spec = "A cheerful screen-time dashboard connects an hourly stacked chart to a reactive sky. Scrub an hour to see its productive, neutral and distracted minutes; the clouds follow the selected quality. A local twenty-five minute focus timer keeps elapsed time across the background.") { SkyScreenTimeDemo() },
    Block(slug = "retirement-gap-dial", name = "Retirement Gap Dial", category = "Charts", spec = "A retirement goal screen built around an oversized cropped dial on pale grey. A white arrow marker catches a glowing red goal stop as the shortfall arc closes, while the current amount and off-track summary follow the same progress. Drag the marker or press Resolve to try the catch.") { RetirementGapDialDemo() },
    Block(slug = "bars-to-lines-morph", name = "Bars To Lines Morph", category = "Charts", spec = "A dark vitals screen: six tiles (heart rate, SpO2, fever, blood pressure, blood glucose, respiratory rate) and a card with the selected one's last 24 hours. Heart rate and glucose are range bars, one per hour, with the part above the limit broken off in red; the others are lines with a dot per hour, red past their limits, and the peak and the low are labelled. Choosing another tile folds the chart into dots, flies the dots to the new readings and unfolds them into bars or lines.") { BarsToLinesMorphDemo() },
    Block(slug = "candle-pattern-walkthrough", name = "Candle Pattern Walkthrough", category = "Charts", spec = "A full-screen trading lesson on a black candlestick chart with neon green and red candles that glow. It steps through a trend line breakout in seven chapters: the swing highs are circled and labelled, a trend line is drawn through them, price breaks it, re-tests it and confirms, a risk-to-reward box slides in and the rally runs to the target in a burst of neon confetti. Tap for the next chapter, swipe across the chart to scrub, and a segmented bar under the chart shows where the lesson is.") { CandlePatternWalkthroughDemo() },
    Block(slug = "dot-matrix-revenue", name = "Dot Matrix Revenue", category = "Charts", spec = "A light revenue card whose histogram is a matrix of small dots: \"REVENUE\" and \"+326 %\" over DAILY, WEEKLY and MONTHLY tabs, the earlier period's columns in light grey and the later one's dark, each captioned with its total in a monospace face. Touching the chart moves the highlight to the group under the finger as a wave that lifts the dots it passes; the tabs re-flow the dots column by column, surplus dots rising away and new ones dropping in, while the headline and the captions count to the new values.") { DotMatrixRevenueDemo() },
    Block(slug = "dual-line-redraw-ranges", name = "Dual Line Redraw Ranges", category = "Charts", spec = "A dark chart screen of two noisy series, the average high and low move of a price in percent, with a Day, Week and Year control, a legend and the two averages underneath. Switching range wipes the old lines out from the left and races the new ones in from the left edge, the gold high line a beat ahead of the violet low one, each with a glowing dot riding its tip, and the last values fade in at the right edge.") { DualLineRedrawRangesDemo() },
    Block(slug = "energy-scrub-area-card", name = "Energy Scrub Area Card", category = "Charts", spec = "A light home-energy card with this week's draw as a smooth orange area chart. A finger on the chart brings up a dashed cursor whose dot follows the curve exactly, with a bubble beside it whose value rolls on digit reels; the big reading and the hourly cost follow the finger. An Eco mode switch under the chart morphs the line into a flatter week.") { EnergyScrubAreaCardDemo() },
    Block(slug = "glass-peak-chart", name = "Glass Peak Chart", category = "Charts", spec = "An edge-lit glass slab holds a chart drawn as a lit glass tube, with an orb on its peak and a pool of liquid light whose level follows the value. A period chip cycles Monthly, Weekly and Yearly, a refresh control redraws the chart, and a large number shows the percentage.") { GlassPeakChartDemo() },
    Block(slug = "glow-tip-scrubber", name = "Glow Tip Scrubber", category = "Charts", spec = "A dark coin price screen with a jagged week-long line. Press and drag on the chart: a thin cursor follows the finger and where it meets the line the line lights up like a fuse, with a bloom and a halo riding exactly on the curve while the rest of the line steps back. The price rolls on digit reels and the change and date follow; a new range draws its line in behind the same glowing tip.") { GlowTipScrubberDemo() },
    Block(slug = "growth-odometer-timeline", name = "Growth Odometer Timeline", category = "Charts", spec = "A followers-growth instrument on a dark page: a month wheel you turn with a finger, a dial knob beside its notch, and a five-drum odometer that rolls from 3,000 to 10,000 under an avatar and a verified name. A halo of light on the right edge grows from a faint green haze to a wall of lime and yellow as the number climbs.") { GrowthOdometerTimelineDemo() },
    Block(slug = "line-to-candles-switch", name = "Line To Candles Switch", category = "Charts", spec = "A dark stock screen whose green area chart turns into candles. The view menu opens from its button; choosing an interval fades the line and grows a candle out of every point from left to right, a longer interval merges neighbouring candles into wider ones, and Line collapses them back into the line. Range pills morph the data, and a finger scrubs the price with a dashed cursor and a date.") { LineToCandlesSwitchDemo() },
    Block(slug = "metric-dropdown-line-scrub", name = "Metric Dropdown Line Scrub", category = "Charts", spec = "A workout progress screen for one lift: a title, two dropdown pills (metric and time range) and a dark card with a line of white dots, one per logged session, on a value grid. Dragging across the card lifts the nearest dot with a halo and a hairline, dims the rest of the line to 35 % and shows a tooltip above the card whose value rolls digit by digit; picking another metric or range morphs every dot to its new place.") { MetricDropdownLineScrubDemo() },
    Block(slug = "mood-stack-columns", name = "Mood Stack Columns", category = "Charts", spec = "A mood journal's day on true black: \"All time\" in a serif heading, then \"Your mood during the day\" as four 100 % stacked capsule columns (Morning, Afternoon, Evening, Late Night) in yellow, green, blue and red for joy, calm, low and stress, each with its percentages and check-ins. Tapping or dragging across the columns widens the one under the finger while the others narrow and dim and a caption names its largest mood; the By mood / By size toggle re-sorts every column, the segments sliding past each other one column after another.") { MoodStackColumnsDemo() },
    Block(slug = "neon-bar-boot", name = "Neon Bar Boot", category = "Charts", spec = "A dashboard boot on a near-black screen under a violet spotlight: two app-icon squares, one violet and one frosted glass, wobble as if tapped and fly up, a glass card rises with its border drawing round, the total sales figure rolls in from zeros digit by digit and seventeen neon bars grow in a wave with their tips lighting up, then breathe. Tapping the card moves it to the next set of figures.") { NeonBarBootDemo() },
    Block(slug = "pixel-spend-staircase", name = "Pixel Spend Staircase", category = "Charts", spec = "A month's spending as a staircase of pixels on a dark screen: each column is a day, lit in an ember gradient from the bottom up to the running total, over last month's staircase in grey. The bright red top cell is the cursor, with \"\$123 today\" above the chart and the month-to-date total floating over it. Dragging across the chart moves the cursor: the days after it go dark from the top down, and moving forward lights them again in a rising pixel sweep while the amounts roll.") { PixelSpendStaircaseDemo() },
    Block(slug = "polar-rose-sweep", name = "Polar Rose Sweep", category = "Charts", spec = "A survey as a polar-area chart on a deep violet screen: ten ideas, one wedge each, every wedge three stacked sectors (likely in lavender, hard to say in violet, not likely in indigo) whose radii read in percent, with the names turned along the circle and a legend pill below. Touching or dragging round the chart selects the wedge under the finger, which springs outward with a larger number while the others dim; the March/June toggle sends a radar line round the chart and each wedge re-flows to the new answers as the line passes, its number rolling.") { PolarRoseSweepDemo() },
    Block(slug = "range-morph-price-line", name = "Range Morph Price Line", category = "Charts", spec = "A dark exchange-rate screen: a jagged price line over a dark area, a seven-range selector under it and two currency buttons. Choosing a range morphs the line into the next series point by point while the area follows, the highlight slides, and the line and the change under the title turn red or green with the sign of the change.") { RangeMorphPriceLineDemo() },
    Block(slug = "semicircle-spend-gauge", name = "Semicircle Spend Gauge", category = "Charts", spec = "A white spending summary card around a half-donut gauge: the half circle is the week's \$2,000 limit, and Shopping, Utilities and Others each take their honest share of it, the unspent rest in grey, with \"SPENT \$1,800.00\" in the middle and the three categories in columns below. Tapping a segment (or its column) pops it out and dims the others while the centre rolls to its total; the \"Last Week\" dropdown switches the period, and the segments re-flow on a spring as every amount rolls to its new value.") { SemicircleSpendGaugeDemo() },
    Block(slug = "sleep-column-scrubber", name = "Sleep Column Scrubber", category = "Charts", spec = "A sleep consistency screen: two weeks of nights as capsule columns on a time axis, each running from falling asleep to waking and striped with its sleep stages (awake, REM, core, deep), over a shaded ideal-bedtime band, a hatched usual wake-up band and lines at the average fall-asleep and wake times. Dragging across the chart widens and rings the night under the finger, dims the others to 70 %, slides a white day badge under it and moves a white label above it whose start and end times roll digit by digit.") { SleepColumnScrubberDemo() },
    Block(slug = "spike-to-stair-chart", name = "Spike to Stair Chart", category = "Charts", spec = "A neon line chart floating over a polished black floor that mirrors it, telling one story in two states: Motivation shoots up, wobbles and crashes to the axis in red; Discipline climbs wavy stair steps and breaks out of the chart in green. A two-segment switch in the same material moves between them, and a finger on the plot scrubs a marker along the line with a day and value chip.") { SpikeToStairChartDemo() },
    Block(slug = "stacked-bars-glass-tooltip", name = "Stacked Bars Glass Tooltip", category = "Charts", spec = "A macros screen on a soft pink-to-blue gradient: a white card with the average calories, the average grams of carbs, fat and protein, and a chart of stacked columns, protein at the bottom, fat in the middle and carbs on top. Press and drag across the chart and the column under the finger lifts while the others fade, and a frosted glass tooltip glides above it with that day's grams. Day, Week and Month morph the columns into each other: seven wide columns split into thirty-one slim ones and gather back.") { StackedBarsGlassTooltipDemo() },
    Block(slug = "stem-wave-cycles", name = "Stem Wave Cycles", category = "Charts", spec = "An abstract chart of a cycle on a pale lilac screen: a lollipop chart of thin stems with black dots, rising above and hanging below a strip of flat colour blocks, their heights following a sine wave. The stems roll as a wave, dissolve into one sine curve through their dots, the curve zooms out to a single period with its crest and trough marked and hairlines at the full and half amplitude, and the stems grow back. Drag to turn the wave, pinch to change its period, tap to switch between the stems and the curve.") { StemWaveCyclesDemo() },
    Block(slug = "steps-bars-to-spikes", name = "Steps Bars To Spikes", category = "Charts", spec = "A steps screen split in two: an electric-blue field with the bars and a black sheet with the total, distance, calories and floors. The D / W / M switch sinks the current bars and grows the next set in a stagger, from seven soft bars per day or week to a month of hairline spikes, while every number rolls to its new value; dragging over the bars lights the one under the finger and shows its steps.") { StepsBarsToSpikesDemo() },
    Block(slug = "stress-dot-grid-donut", name = "Stress Dot Grid Donut", category = "Charts", spec = "A stress patterns screen on black: a heat map of glowing dots, one per two-hour period of the last 7 days (lime low, periwinkle normal, red high, a dim dot for no data), a donut of how many periods were low, normal and high with a chip and count for each, and a card naming the most stressful times. Switching to 4 Weeks morphs the map dot by dot into a grid of days while the grid shrinks and the page below follows, the donut's segments spring to their new lengths and the counts roll.") { StressDotGridDonutDemo() },
    Block(slug = "swipe-month-donut", name = "Swipe Month Donut", category = "Charts", spec = "A light spending screen with a month's expenses as a ring of round-capped segments, paged with a swipe. Between two months every segment's start and length follow the finger, so a category shrinks into its neighbour or grows out of it while the total slides with the page and the list below re-flows. Tapping a segment pops it out and shows its amount in the centre.") { SwipeMonthDonutDemo() },
    Block(slug = "donation-sphere-heart", name = "Donation Sphere Heart", category = "Forms", spec = "A donation welcome sits on warm paper with a white rounded hero card and a separate options panel. A volumetric heart made of cobalt, violet, pearl, clear glass and chrome spheres repeatedly changes between a medium heart, a larger dense heart and twelve sparse spheres. Three concise donation options and a dark Donate now pill remain fixed beneath it.") { DonationSphereHeartDemo() },
    Block(slug = "terminal-reservation-review", name = "Terminal Reservation Review", category = "Forms", spec = "A reservation checkout slides into a white payment review with an isometric reader, a pale payment card and a green vase of pink flowers. A magenta arc completes into a small clock before the card ejects and a photographic stay card confirms the reservation.") { TerminalReservationReviewDemo() },
    Block(slug = "laced-boot-studio", name = "Laced Boot Studio", category = "Forms", spec = "A warm leather customization screen presents an original top-down pair of boots. One continuous lace passes through fixed eyelets and tightens into six completed rows, with the left boot showing the finished pattern. Pull the strand in order, choose leather and sole options, or save the pair locally.") { LacedBootStudioDemo() },
    Block(slug = "mood-petal-bowl", name = "Mood Petal Bowl", category = "Forms", spec = "Independent petals, scallops, soft stars and pointed bursts collect in a cream calendar’s frosted semicircular bowl. Pieces stay crisp above the rim and soften behind its front while the mood word, saved day and local log stay legible. Stir the captured pile, choose a mood or date, and log the illustrated day locally.") { MoodPetalBowlDemo() },
    Block(slug = "beam-checkout-stepper", name = "Beam Checkout Stepper", category = "Forms", spec = "A five-stage checkout built from smoked glass pills, illuminated domes, and a light-filled rail. Real email, shipping, and card fields validate locally, preserve completed-step summaries, and lead to a simulated payment confirmation.") { BeamCheckoutStepperDemo() },
    Block(slug = "credit-card-flip-form", name = "Credit Card Flip Form", category = "Forms", spec = "A dark payment screen: \"CHECKOUT · STEP 2 OF 2\" over a bold \"Card details\" with the total, €248.00, on the right, a live card preview resting on a soft shadow tinted with its own light, four fields with their labels inside (Card number, Cardholder name, Expiry, CVV), a \"Save card for next time\" switch, a small lock line and a wide \"Pay €248.00\" pill that stays dark until the card is complete. The card is brushed metal: a fine horizontal grain and wavy guilloche over its colour, a soft light from above its top left, darker towards the bottom edge, a gold chip with a bright rim, a contactless mark, \"HALCYON\" and an empty dashed slot for the network, bullets for the sixteen digits, \"YOUR NAME\" and \"MM/YY\". Each digit typed rolls into place like a slot reel; the first digit names an invented network (Kestrel teal, Vela indigo, Orrery ember, Nimbus blue) whose mark pops into the corner while its colours spread across the card from it and the card swings to catch the light. A frame of light with a comet running round it hugs whichever part of the card is being edited and glides between the number, the name (growing with it) and the expiry, while one ring in the card's light colour glides between the fields below. Finished fields get a green check; an expiry in the past turns its field red as \"Card expired\". Focusing the CVV turns the card over to its back, with a magnetic stripe, the name signed in script and the frame of light round the CVV box. Dragging on the card tilts it in 3D and its light slides across the surface. Pay folds the button into a spinning ring and then a green circle with a check.") { CreditCardFlipFormDemo() },
    Block(slug = "glow-toggle-checklist", name = "Glow Toggle Checklist", category = "Forms", spec = "A four-item checklist that lives inside a glass pill. Tap the pill and it becomes the cap of a smoked-glass panel that unrolls beneath it, with four small ceramic switches; the cap is an eight-cell progress bar that fills green as they go on. Behind it burns a halo whose colour, size and turbulence follow the switches: restless red smoke at none, through magenta, indigo and teal, to a calm radiant green when all four are on.") { GlowToggleChecklistDemo() },
    Block(slug = "keycap-mood-input", name = "Keycap Mood Input", category = "Forms", spec = "Four sculpted keycaps on a black page spell “i / feel / so / :)”, combining white satin plastic, luminous cobalt glass and an internally lit mood key. Pixel legends change with each press, while a hidden fan offers six moods. Coloured light reveals the wells and travels through the column when a mood is released.") { KeycapMoodInputDemo() },
    Block(slug = "aurora-wallet-top-up", name = "Aurora Wallet Top Up", category = "Forms", spec = "A full-screen \"Add money\" form on near-black: a large amount (\"100\") over a small \"USD\" pill, a wallet row with a round mountain picture, \"Wallet 02\", \"\$478.00 Available\" and a \"Wallets\" button, a number pad without key shapes, and a white \"Continue\" pill at the bottom. Continue blurs and dims the form behind a thin ring spinner and \"Topping up wallet\", while the button turns into a soft bar of light and an aurora grows out of it over the bottom third of the screen: violet at the left, magenta through the middle, peach turning orange at the right. The light then gathers into one bright blob that sweeps up through the screen and out of the top, leaving a white check and \"Wallet topped up\" on the plain dark screen before the form returns with the balance counted up.") { AuroraWalletTopUpDemo() },
    Block(slug = "elastic-savings-slider", name = "Elastic Savings Slider", category = "Forms", spec = "A savings estimator on a very dark green screen. On top a pill banner holds a small drawn house, \"13 Alondra Blvd\", \"Fine-tune your home for more accurate results\" and an outlined \"Fine-tune\" button; under it an off-white card holds a pale sage panel with \"Estimated Annual Bill\", a small white chip with the saving and a down triangle, and the bill as a giant heavy coral amount (\"\$1326\"), then six option chips in two columns, a fat black slider with a coral fill that ends in a white lightning bolt, and \"See your full report\". Dragging the fill to the right switches the options on one stop at a time, from the bottom row up: the chip's text darkens and a black check disc pops in, the saving counts up and the bill drops, each changed digit landing with a squash. The fill is elastic: its end follows the finger while the bolt trails behind on a spring, the fill thinning as it stretches, and on release it snaps to the nearest stop and wobbles; dragging back switches the options off, and a tap on a chip toggles that option alone.") { ElasticSavingsSliderDemo() },
    Block(slug = "emoji-mood-feedback", name = "Emoji Mood Feedback", category = "Forms", spec = "A full-screen feedback form on one flat colour that depends on the answer: lime for \"Good\", amber for \"Not bad\", coral for \"Bad\", with every element a darker shade of it. Under a close and an info button and the question \"How was your shopping experience?\" sits a face made of two eyes and a mouth, then the answer as a giant heavy word barely darker than the screen, a three-stop slider whose round thumb has a little mouth of its own, and a bar with \"Add note\" and a \"Submit\" pill. Dragging the thumb to another stop tweens the whole screen to that answer's colour while the eyes morph (136 pt discs, flat 106 × 34 pt bars, 62 pt dots), the smile turns into a frown and the giant word slides out to one side as the next one comes in from the other. \"Add note\" lifts the face and opens a text card with its own Submit above the keyboard; Submit makes the face hop and shows \"Thank you!\" before the form returns.") { EmojiMoodFeedbackDemo() },
    Block(slug = "exertion-spectrum-slider", name = "Exertion Spectrum Slider", category = "Forms", spec = "A dark rating sheet with rounded top corners over a page whose blurred traces show through: \"How hard was it?\" and a grey subtitle, one huge white numeral from 1 to 10 (112 pt bold), the level's name (\"Very Light\") and one or two grey lines describing it, then a slider, \"Clear Entry\", \"How to Self-Assess\" and a full-width Save button. The slider's track is a 9 pt line filled with a spectrum (teal, sky blue, yellow, orange, red, magenta, purple) with a dot between levels, lit from the usual range to the thumb and shaded beyond; a band of grey diagonal hatching marks everything outside the \"USUAL RANGE\", and the thumb is a white disc with a dot in the colour under it. Touching the slider swells the track into a wedge, 9 pt at the left and 54 pt at the right, and fills the thumb with its colour; dragging rolls the numeral like a counter wheel with a vertical blur at every level, cross-fades the name and description, and runs Save's fill along the spectrum. Outside the usual range the hatching between the range and the thumb takes the spectrum's colours, a red \"ABOVE USUAL RANGE\" or cyan \"BELOW USUAL RANGE\" tag pops in over the thumb in place of the caption, and Save gains a second line; letting go shrinks the track back, and \"Clear Entry\" sends the thumb home.") { ExertionSpectrumSliderDemo() },
    Block(slug = "expanding-filter-rows", name = "Expanding Filter Rows", category = "Forms", spec = "A dark \"Filters\" sheet with five rows, each a 60 pt rounded bar with a grey icon and label at the left and its value at the right: \"Dates\" with \"18 Dec 2024\", \"Friends attend\" with a small column of friends' pictures that take turns and \"12+\", \"Time\" with \"7:00 pm\", \"Genres\" with \"Afrobeat, Bluegrass +6\" and \"Price\" with \"All price\"; at the bottom \"Reset all\" and a blue pill \"Continue with 4\" over a fade that rows slide under. A tap on Time springs the row open, pushing the rows below it down, into a darker well with two options, \"Single time\" and \"Time range\", an analog clock and a wheel of times in half-hour steps: turning the wheel turns the clock's hands, and \"Time range\" slides a second wheel in, points the short hand at the start and the long one at the end, and draws a blue arc between them along the rim. A tap on Genres closes Time and opens two facing lists that lie on the rims of two big wheels, so the names tilt and fade away from the middle: the chosen genres on the left, the others with blue rings on the right; each list turns under the finger and a tap moves a genre across. The other rows change value on a tap, and the number on the button counts the filters that are set.") { ExpandingFilterRowsDemo() },
    Block(slug = "eye-wipe-password-field", name = "Eye Wipe Password Field", category = "Forms", spec = "A sign-in form on a flat periwinkle screen: \"Welcome back\", an email field, a password field and a \"Sign in\" button, all quiet so that the password field's eye is the subject. Hidden, the field is navy with a white padlock, a violet dot for every character and a white disc that holds a shut eye with three lashes. A press on the eye stretches the disc into a pill that grows across the field as a white wipe with round ends; under it the dots blur into the characters, set in a monospaced face, the padlock turns dark where the wipe has passed, and the eye opens with its lashes flipped above it. The field ends white on a soft lilac shadow, and a second press wipes it back into the disc.") { EyeWipePasswordFieldDemo() },
    Block(slug = "loan-step-questions", name = "Loan Step Questions", category = "Forms", spec = "A loan application on white, one question to a screen, in dark slate (#3A3F58) with royal blue (#3F5BD9) accents. \"How much would you like to borrow?\" stands in light 28 pt type over the label \"Amount\" and the figure \"\$25,000\" at 80 pt light, its dollar sign pale grey; under it a ruler of fine lavender ticks moves beneath a blue marker fixed in the middle, with \"1k\" and \"100k\" at its ends, then a pale strip of two cells, \"Monthly: \$2,232\" and, in blue, \"Total: \$26,781\". A grey footer carries PREV and NEXT in blue capitals under a thin progress line. Dragging the ruler runs the figure, its changing digits ghosting, and both totals; NEXT sends the question, the label and the figure up and away with a vertical smear while \"Over how many months would you like to repay?\" and \"12\" rise from below, the ruler only dipping and trading its end labels for \"6\" and \"96\" and the progress line growing. A second NEXT takes the ruler and the totals away too and brings a summary: the monthly payment at the same giant size over two strips (amount, term, rate, total), with the right half of the footer turned into a blue CONFIRM bar.") { LoanStepQuestionsDemo() },
    Block(slug = "mood-capsule-check-in", name = "Mood Capsule Check-In", category = "Forms", spec = "A mood check-in on a near-black screen (#0E0E10): under the grey question \"How are you feeling?\" sit five upright capsules (62 × 103 pt, 9.5 pt apart) in violet, blue, teal, yellow and orange, each with a pale mark in its middle, a glassy edge and a glow of its own colour; a dark tile with a gear and a chart icon is at the top right and a two-part control \"Current mood / Overall today\" at the bottom. A tap makes a capsule swell into a glowing lozenge (158 × 306 pt) in the middle of the screen that holds its mark, two translucent chips (\"Emotions\", \"Context\") and a round pale button with an up arrow, while the other moods turn into small grey capsules (42 × 73 pt) at its sides, the question blurs away, the mood's name (\"Pleasant\") appears above and the whole screen takes a haze of that colour. A sideways swipe, or a tap on a grey capsule, hands the lozenge to the neighbouring mood: one deflates as the other inflates, the name and the haze changing with it. A tap on a chip steps it through its words (it turns solid once it holds one), the round button shows a check and closes the lozenge, and a tap outside closes it without sending.") { MoodCapsuleCheckInDemo() },
    Block(slug = "neon-otp-verify", name = "Neon OTP Verify", category = "Forms", spec = "A phone verification sheet on a black screen: a dark graphite sheet with a grabber, \"Let's verify your number\", two grey lines, four square code boxes, \"Didn't receive the code? Resend\" and the sheet's own number pad. The next empty box carries an orange-red border with a faint glow, and each digit pops into its box as its key flashes. The right code verifies by itself: on all four boxes at once a neon stroke starts in the middle of the top edge and runs clockwise until the outline closes, over a warm haze; the lit boxes swell, slide together into a fanned deck and close into one glowing tile, where a check draws in from a dot under \"Verified successfully\" while a few embers fall. A wrong code turns every box red, shakes the row and empties it.") { NeonOtpVerifyDemo() },
    Block(slug = "orbit-upload-dropzone", name = "Orbit Upload Dropzone", category = "Forms", spec = "A dark upload card (#17161F, 340 pt tall, radius 8, a wide soft shadow) centred on a pale grey screen: a white disc with a dark up arrow on a grey ring, \"Import file\", two grey lines of text and a white \"Choose file\" button. A tap on the card or the button flies a file in from the right (a white sheet with a folded corner and a name tag); as it crosses the card everything inside blurs and swaps: the icon becomes a glowing disc with a stack of pages, the copy reads \"Release file\" and the button smears into a grey bar. The file then drops into the icon, which turns into a black disc with a white arrow on a wider ring, the copy reads \"Importing data\", the button comes back as \"Cancel\", and fourteen white particles burst out of the ring and circle it while the import runs. They are called back one by one, closing the ring into a solid white band, which becomes a white disc with a check over \"Import complete\" as the button fades away.") { OrbitUploadDropzoneDemo() },
    Block(slug = "paper-tape-quantity", name = "Paper Tape Quantity", category = "Forms", spec = "A product screen in soft warm-grey clay (#e3e3e1): two raised round buttons, a sunk panel with a round desk speaker whose light takes the chosen finish, \"Halo Speaker\" with its price, two finishes with glossy beads (\"Cyber-Tech\" orange, \"Blue-Steel\" blue), and an add-to-cart bar: a raised frosted capsule 84 pt tall. At the bar's left end sits the quantity roller: a small drum with ribbed orange caps in a well, and a strip of white paper 54 pt wide that runs behind the bar and over the drum, carrying the numbers 1 to 4 written by hand in ink on small labels, so that at 1 the tape hangs below the bar with 2, 3 and 4 on it and at 4 it stands above it. Beside the drum a white tile holds an up and a down arrow, then \"Add to cart\" with the total under it; under the bar an orange square and \"Order today to get it by Friday\". An arrow shoots the tape through the drum to the next number, smeared along its way, and it lands with a small bounce; the drum can also be dragged up and down by hand, and the total follows the quantity.") { PaperTapeQuantityDemo() },
    Block(slug = "particle-card-details", name = "Particle Card Details", category = "Forms", spec = "A black \"Card Details\" screen for adding a payment card: where the card will be there is a card-shaped cloud of thousands of tiny dots, white and grey with a few violet and green, each twinkling on its own; under it the title, a grey line, one grouped field with \"Name\" and \"Security Code\", a round close button and a \"Continue\" pill that turns white once both fields are filled. Continue switches the text to \"Adding Card\" with a spinner and \"Contacting the Card Issuer…\", the field group shrinks and blurs away as a violet ghost, and a solid grey card with a contactless mark flashes in over the cloud. A ragged, pale line then travels from the card's top edge to its bottom edge: below it the card is solid, above it the card has crumbled into dust that rises and thins out until only the twinkling cloud is left. After the wait the form returns, empty.") { ParticleCardDetailsDemo() },
    Block(slug = "ride-height-filter", name = "Ride Height Filter", category = "Forms", spec = "A white filter sheet with a grabber over a dark page: a close cross, the title \"Ground clearance\" and a teal \"Reset\" link, then a picture strip drawn in the matte light greys of a clay render: a planter with a leafy bush and a round kerb on the left, and on the right the front quarter of a car (bonnet, headlamp, slatted grille, a meshed intake with a fog light, a splitter, and a five-spoke wheel in its arch) with a soft shadow on the ground. Under it five chips in two rows (Sport, Low, Medium; High, Off-road), grey with the chosen one near-black, a bold heading with the clearance (\"Up to 12 cm\"), two lines of text, a grey line of typical cars, and a black \"Show 128 cars\" button at the bottom. Choosing a chip raises or lowers the car's body on its suspension while the wheel stays on the ground: the dark gap in the wheel arch opens, the bumper clears the kerb and the shadow under the car pales and spreads, while the chips' fills cross-fade and the heading, text and count change.") { RideHeightFilterDemo() },
    Block(slug = "shield-password-strength", name = "Shield Password Strength", category = "Forms", spec = "A sign-up password field on a very light blue-grey screen: a cyan shield with a white keyhole inside a large soft glow, and under it the label \"Password\", a white pill field with the password as small dots, an eye to show it and a padlock, and one small line of hint, \"Enter Your Password\". As the password gets stronger the shield and its glow go pale and come back in a new colour, red for weak, burnt orange for fair, green for strong, while the label and field dim for a moment and the hint clears and retypes itself letter by letter (\"Add more characters to strengthen it\", \"Nice, try adding a symbol\", \"Perfect! Strong & secure\"); a strong password also gives the field a thin green outline. Submitting a strong password fades the label, field and hint away, the shield glides down to the middle of the screen with its glow, and its keyhole dissolves into a white check with a small pop.") { ShieldPasswordStrengthDemo() },
    Block(slug = "slingshot-send-money", name = "Slingshot Send Money", category = "Forms", spec = "A full-screen send-money confirmation with no cards: a vertical sheet of satin bands (dusty rose at the top, near-black brown behind the amount, a mauve band under the hint, red-brown at the bottom), the recipient's round picture with the initial \"D\" and the name \"Dave\" at the top, \"\$4.50\" in white 64 pt bold at 37% of the height, the hint \"SWIPE DOWN\" in wide-spaced capitals at 58%, and a round close and a round pencil button in the bottom corners. Dragging down anywhere pulls the amount like the pouch of a slingshot: it trails the finger with ghost copies smearing behind it and leans as if it hung from the recipient, the hint follows less far, the bands stretch down and the top two thirds of the screen heat to amber in proportion to the pull; past the threshold the hint reads \"RELEASE TO SEND\" and the corner buttons fade out. Letting go there fires the amount up into the recipient, shrinking and fading with its ghosts behind it while the amber drains; a green disc with a white check then pops in where the amount was, with \"Sent\" under it and a \"Done\" pill rising from the bottom, and Done drops the amount back out of the picture. Letting go short of the threshold springs everything back.") { SlingshotSendMoneyDemo() },
    Block(slug = "split-bill-claim", name = "Split Bill Claim", category = "Forms", spec = "One step of splitting a bill, on a pale grey sheet under a white header: \"Back\", your portrait, \"Pick your items\", and the receipt's three items as white cards with a grip, a name and a price under \"In total \$25.75\". Swiping a card to the right lifts it and uncovers your portrait with a blue \"+\" badge in the gap it leaves. Let go, and the card springs back while the portrait hops over its edge, pushes the name aside, shrinks and settles under the name; the card tints blue, and a bar rises from the bottom with the number of items, your share counting up, and a blue \"\$1.50 - Pay\" button. Swiping a card that is yours shows a \"-\" badge and gives it back, and the bar leaves when nothing is claimed.") { SplitBillClaimDemo() },
    Block(slug = "stacking-cup-stepper", name = "Stacking Cup Stepper", category = "Forms", spec = "A drink-log screen on black: a navigation row (\"Caffeine Window\"), \"Suggested beverages\" over a ruler of quarter-hour ticks that turn from orange to green under a \"10:30 AM\" chip, and a dark grey sheet (#171717) with \"Caffè Latte\", a time chip and, in its middle, a paper cup drawn in 3D: a cream lid with a sunken top and a drinking hole, a cream body and a kraft sleeve with two coffee beans, lit from the upper left. Under it are \"Caffeine content\" and a large figure (\"75 mg\"), four size pills (\"Small\", \"Medium\", \"Large\", \"Extra Large\", each with its volume below), a quantity stepper and a white \"Confirm\" pill. A size slides a white pill onto it and stretches the cup on a soft spring, the lid hopping clear of the open cup and dropping back on; one cup more drops a second cup in from the upper right beside the first, a third lands in front of two that step back into a triangle, and one less lifts the last cup away. The figure counts to the new total each time.") { StackingCupStepperDemo() },
    Block(slug = "starfield-payment-success", name = "Starfield Payment Success", category = "Forms", spec = "A full-screen payment form on black with a maroon tint at the top and an orange light under the bottom edge: \"Enter Amount\", a large light amount (\"0.00 USD\" with a violet caret), a conversion chip, a grey card row (\"**** 3256\") and a number pad without key shapes. Typing an amount brings a violet \"Confirm\" pill up from the bottom while the pad's rows close up to make room. Confirm takes the form apart (the amount floats up, the card and the pad sink) and leaves a field of stars flying past, with \"Starting your transaction\" under a dark paper plane on a wobbling yellow light. Then a thin red ring bursts outward, a green check lands, swells, darkens and turns over, and what comes round is a spinning gold coin over \"Successfully sent\", the amount, and a \"Review\" pill with a round share button.") { StarfieldPaymentSuccessDemo() },
    Block(slug = "swap-success-card", name = "Swap Success Card", category = "Forms", spec = "An exchange card on a teal radial-gradient screen: a dark glass frame lit green from the top inside a faint halo, with \"Exchange\" and a Swap / Limit / Bridge control in its header, a black panel holding a \"From\" and a \"To\" field (a large light amount, a token chip with a round mark, the balance, \"Max\" and the rate), a round mint button on the line between them, and a mint \"Swap\" bar. Typing an amount in \"From\" fills \"To\" at the rate, and the round button makes the two tokens trade places while it turns half a turn. Swap narrows and darkens the bar, every piece of content fades out, and the frame contracts round the empty black panel; a small mint dot appears and blooms into a white ring round a mint disc where a check draws in, \"Successful Exchange\" rises out of a blur, and two small lines say what was exchanged. The success card then shrinks a little and fades away, and the empty form comes back out of a blur.") { SwapSuccessCardDemo() },
    Block(slug = "unfolding-signature-pad", name = "Unfolding Signature Pad", category = "Forms", spec = "A signature field in the middle of a white screen that starts as a pale grey pill, \"Start Signing\", with a pen-and-scribble icon. A press unfolds it: the pill drops and widens into the bottom button of a dashed, rounded card (\"Finish Signing\") whose outline grows up out of it, with a clear arrow, \"Sign\" and a close disc at the top, and the finger writes on the card in black ink. Finishing folds the card back into a near-black \"Signing Done\" pill with a white check disc, the signature shrinking into it, while a round pencil button slides out from behind its right end to open the pad again with the ink still there. The label changes in place: the word \"Signing\" slides and the word beside it blurs across letter by letter.") { UnfoldingSignaturePadDemo() },
    Block(slug = "unlocking-checkout-steps", name = "Unlocking Checkout Steps", category = "Forms", spec = "The confirming steps of a checkout on white: the title \"Confirm\", three step dots (a green check, a black \"2\" with \"DELIVERY DETAILS\", a grey \"3\") and the order's card with \"Order 12329\", \"\$19.11\", \"Placed on 3 June 2022\" and a large square button, grey with a down arrow. A light grey drawer under the card asks one thing at a time: \"SELECT AN OPTION\" with Delivery and Pickup, where the suggested one sits in a grey pill that turns black when tapped; that unfolds \"DELIVERY BY\", a strip of hours whose middle pill turns black the same way; and that unfolds \"DELIVERY TO\" with \"Home\" and a teal \"Change\", at which the card's button turns green and its arrow turns to the right. Confirm folds the drawer away while the two black picks fly up to the card's right side, the option landing as plain words and the hour as a pill; the price greys, the card grows to show the address over a street map on which a teal route draws itself, the third dot takes over and a green \"Done\" appears. Done grows into a green sheet that takes the whole screen, on which a drawn parcel with a check badge, \"Checkout successful!\" and a black \"Return to Dashboard\" scale up; returning puts the form back as it started.") { UnlockingCheckoutStepsDemo() },
    Block(slug = "dial-slider", name = "Dial Slider", category = "Forms", spec = "A photo-editor adjustment control on a black screen. A scrolling strip of seven round preset buttons (Exposure, Brilliance, Highlights and so on), each ringed by an arc showing its value, sits above a ruler of tick marks that sets the selected preset from −100 to 100.") { DialSliderDemo() },
    Block(slug = "time-target-dial", name = "Time Target Dial", category = "Forms", spec = "A picker for setting a time target in hours. A curved ruler of hour marks runs down the left edge, the chosen value shows large on the right between up and down arrows, and Confirm and Back buttons sit below.") { TimeTargetDialDemo() },
    Block(slug = "auxetic-fit-lab", name = "Auxetic Fit Lab", category = "Gestures", spec = "A pale material lab holds twelve rigid crosshatched squares joined at teal corner pivots. Pull either handle or pinch the sample to rotate the linked plates and grow its width and height together, with extension and open-area readouts derived from the same geometry. Save the illustrated fit with local confirmation.") { AuxeticFitLabDemo() },
    Block(slug = "world-sun-projection", name = "World Sun Projection", category = "Gestures", spec = "An offline solar-planning view projects a thin sun path over an original painted coast and tree canopy. The scenery and solar marks share one camera projection as the view pitches from the beach toward the branches. Drag to look around, scrub the time rail, or select a fixed planning preset.") { WorldSunProjectionDemo() },
    Block(slug = "cassette-deck", name = "Cassette Deck", category = "Gestures", spec = "A cassette deck that is the whole screen: a brushed aluminium faceplate with its name engraved, a recessed well behind a smoked acrylic door holding a mixtape (charcoal shell with screws, a cream paper label written by hand, \"Glass Hours, for Jun, summer mix\"), a mechanical tape counter with a memory lamp, two LED level meters, and a row of five aluminium piano keys. Press play: the key goes down and latches, the motor brings the tape up to speed and it winds from the left reel's pack to the right one, the counter's wheels roll and the meters move with the music. Fast forward winds it on at speed; rewind winds it back and the counter's memory stops it at 000 by itself. Stop and pause act and spring back up.") { CassetteDeckDemo() },
    Block(slug = "page-curl-journal", name = "Page Curl Journal", category = "Gestures", spec = "The onboarding of a habit journal set as a printed book: ivory paper with its grain, the binding's shade along the gutter and the page edges still to turn on the right, a running head and a folio, Newsreader throughout. A title page (\"The Great Book of Habits\", a printer's rule, the publisher's seal), a preface with two run-in paragraphs and a footnote, a foreword in justified text, and an ownership page with a foil-blocked title and \"Untitled Author\". Drag anywhere on a page to peel it: the point under your finger follows it 1:1, the sheet rolls over a cylinder showing its ivory back with the print reading through, its fold shaded and a soft shadow cast on the page beneath. Let go and the sheet goes over or falls back with your speed; drag right to bring the previous page back, and flick right hard to riffle every page back to the title. A tap on the right margin or on \"turn the page\" turns forward, the left margin goes back, and VoiceOver users adjust the journal like a slider.") { PageCurlJournalDemo() },
    Block(slug = "receipt-printer", name = "Receipt Printer", category = "Gestures", spec = "A year of runs as a grid of tiles under three figures for the year (91.4 km, 12 runs, 5'29\"/km), each tile with the run's route traced in ink, its weekday and date and its distance. Long-press a run and pick Long receipt (or just tap it): the tile flies up and flattens into a black printer slot, and a long slip of thermal paper is fed out of it in jerks, the newest lines still pale. The receipt holds the run on warm thermal paper with its grain: logo, run number, date and route (\"RIVERSIDE LOOP – TEMPO\"), a table of five steady kilometres and the finishing kick with pace, zone, time and heart rate, the pace traced every 100 m against its average, TOTAL 6.21 KM, duration, average pace, best kilometre and heart rate, *** DUPLICATE COPY *** and a torn foot. Drag the paper itself to read it; at its end Save, Tear off and Signature come up. Tear off, or pulling the paper down past its top, draws it back into the slot and the grid returns.") { ReceiptPrinterDemo() },
    Block(slug = "glass-lock-key", name = "Brass Padlock Vault", category = "Gestures", spec = "A personal vault behind a solid brass padlock, in a dark room lit from above: a cast brass body seen three-quarter, its brushed face engraved \"HALDEN 40 MM\", a hardened steel shackle, and a nickel key waiting below. Drag the key up to the keyhole on the padlock's underside: it is pulled in and slides home. Drag across its bow to turn it right through three clicks, the bow narrowing as it turns; at the third the shackle springs open, light sweeps across the brass and the vault sheet rises with recovery codes, a passport scan and the home Wi-Fi. Turning the wrong way strains the key and shakes the lock. Lock vault turns everything back in order; the key is also a button for VoiceOver.") { GlassLockKeyDemo() },
    Block(slug = "drag-card-to-send", name = "Drag Card to Send", category = "Gestures", spec = "A light wallet home: a large \"Wallet\" title, a midnight anodised card at the ISO 1.586 : 1 ratio (etched contour lines, a champagne-gold chip, a monoline \"cove\" logotype, contactless mark, balance and last four digits), a \"Send to\" row of five recent people (round photos spanning the content width) and the latest activity (people by photo, merchants by their own marks on pale tinted squircles). Pull the card down and the Dynamic Island lets out a drop of glossy black liquid that holds the amount, \$5 to \$200 in detents, written on the drop and growing with it; slide sideways to choose who, a ring follows to the nearest person and the hint reads \"Let go to send \$45 to Theo\". Let go: the drop pinches off the island, which wobbles back, falls across the card and drains into that person, who catches it; the ring rings out, the island opens into an expanded Live Activity as wide as the card (their photo with a check, \"To Theo\" over the amount, Undo with a 4 s countdown ring), the balance's changed digits tick over and a new row slides in. Let go without an amount and the drop goes back into the island; a tap makes the card nod to teach the pull.") { DragCardToSendDemo() },
    Block(slug = "drag-multi-select", name = "Drag Multi Select", category = "Gestures", spec = "Offline for the flight, at night: a flight card on top (UA 1514, SFO to JFK, 9:05 AM to 5:30 PM, the route between the two airports) and a podcast's new episodes as the flight's timeline. Hold an episode and drag: every episode you pass takes its place on the timeline with the time you would start it and a rail segment (orange and violet alternate so neighbours read apart), while the route on the card fills toward JFK and two figures say what is planned and what is still to fill. Tap to add or leave out one episode. Past the flight's length a green \"Lands JFK 5:30 PM\" marker drops into the timeline. Download, and the plane flies the route as the episodes land, each ring turning into a check as it passes; a dot-matrix boarding pass then rises with what is on the phone. VoiceOver users start planning or toggle an episode with a double tap.") { DragMultiSelectDemo() },
    Block(slug = "envelope-gift-reveal", name = "Envelope Gift Reveal", category = "Gestures", spec = "A letter on a linen table under one warm lamp: \"Something for you\" from Nora, a cream cotton envelope with real paper grain, \"for Sam\" in blue ink, and an oxblood wax seal pressed with an N. Swipe up on the envelope (or press \"Lift the flap\"): the seal cracks in two, the flap folds back in perspective and curls like paper, showing its green liner, and a heavy letterpressed gift card from Fable & Fern follows the finger out, swinging with the drag. Let go past the line and the card arcs into place while the envelope drops away, then turns over with weight to Nora's handwritten note and the amount; the caption and \"Add to Wallet\" rise in. A short swipe lets the flap fall closed again.") { EnvelopeGiftRevealDemo() },
    Block(slug = "gift-slot-drop", name = "Gift Slot Drop", category = "Gestures", spec = "A wallet's welcome gift at night: four gift cards from invented shops (Kiln & Clay, Northline, Fernhouse, Ember Roasters), each its own material drawn in code, in a perspective carousel above a glass shelf with a slot lit from inside, the one light on the page. Swipe to choose; pull a card down and it shrinks and leans back into the slot while the title changes to \"Let go to activate it\". Let go: the card slides in under the slot's lip, the slot reads it (\"Activating your gift…\"), and the activated gift rises back out and turns over to its code, with two steps and a button to use it. VoiceOver changes gifts with swipe up and down and activates with a double tap.") { GiftSlotDropDemo() },
    Block(slug = "glass-disc-onboarding", name = "Glass Disc Onboarding", category = "Gestures", spec = "The first screen of Strolls, an invented walking-routes app: cream paper, the wordmark, \"Walks worth taking, five minutes from your door.\" and a glass dome at the bottom edge through which the map under the screen shows enlarged. Pull the dome up and it becomes a magnifier you move over the map: streets, a park with its pond, a canal and the roads bend at its rim like light through thick glass, red and blue a hair apart there. Let go past the threshold (or flick it up) and the lens opens out past the corners into the map screen, where the Canal loop draws itself above a route card with \"Start walk\". Back gathers the map into a magnifier in the middle and drops it into the dome.") { GlassDiscOnboardingDemo() },
    Block(slug = "gumball-crank", name = "Gumball Crank", category = "Gestures", spec = "Today's treat from a real gumball machine: cherry enamel over a cast body, a chrome lid, collar, plate and foot, and a glass globe full of gumballs, on an oak table against a warm plaster wall, lit from one window high on the left. Turn the handle once around with your finger: it clicks through four detents (the pawl lets it strain back but never turn back) and the gumballs jostle against each other and the glass at each click. The chute's flap swings open, a capsule rolls out of the door toward you, rocks to a stop, and its clear top pops off and lands upside down on the table; a card rises out of it with the day's coins. Collect sends eight coins arcing into the wallet, whose balance rolls up from 1,240 to 1,290.") { GumballCrankDemo() },
    Block(slug = "habit-bubble-cluster", name = "Habit Bubble Cluster", category = "Gestures", spec = "A habit tracker's day as a cluster of glass bubbles over a calm dusk page, each sized by how much the habit matters and tinted a quiet mineral colour (sage, sand, clay, mist), with the quiet-hours dial among them. Hold a bubble: liquid rises inside it, its surface moving, while a thin ring of light closes round it; full, it stays filled under a check, a ring of light leaves it, the neighbours are pushed out and the cluster re-packs round its smaller size. Drag a bubble to shove the others and fling it; tap one to read its name on a label above it; tap a done one to reopen it. A glass segmented control switches between the Social and Personal sets, and a pill counts what is done today. VoiceOver gets one button per habit.") { HabitBubbleClusterDemo() },
    Block(slug = "hold-drag-resize", name = "Hold Drag Resize", category = "Gestures", spec = "Make room for deep work: Thursday's plan at night in Liquid Glass. A dark page with one warm horizon light low on it, faint hour lines and a dotted rail; every surface above it is glass that refracts the frosted page (bent inward over the last 12 pt of its rim, red and blue a hair apart), lit by a crisp rim highlight from above and a fainter one below. Header: \"Thursday\", \"16 October · 8 plans\" and a glass chip with the day's focus total (\"Focus today 1h 00m\"); a glass week strip, Monday 13 to Sunday 19, today in its own brighter lens, a dot per plan in its kind's colour. The day 09:00 to 18:00: hour labels in JetBrains Mono, now (09:41) a red pill and a red line under the glass, each plan a glass block with a capsule on the rail as tall as the block: amber for the focus block \"Pricing memo, first draft\" (its glass glows amber), sky for your tasks (with a circle), grey for other people's meetings, which never move. A floating glass bar: \"3h 15m open until 18:00\" and a glass \"+\". Hold a block: the glass lights from under the finger, then thickens (its rim bends more), lifts with a deeper shadow and shows a grip on the nearer edge. Drag the edge: it clicks from quarter hour to quarter hour, an amber pill takes the place of the hour labels and reads the time, the added time fills the block with warm light and \"+1 h\" sits beside the grip, the focus total and the open time roll. Grow into the next task and it is shoved later as one rigid chain, each pushed task showing its old time struck through beside the new one. The chain stops hard against \"Lunch with Maya\": push on and the tasks squash, the meeting's glass dims, gives by a point and shows a lock. Drag back and the tasks spring home to their own times one after another, the block showing what it lost (\"−1 h\"). A start edge moves only into free time. VoiceOver can move a block's end by a quarter hour.") { HoldDragResizeDemo() },
    Block(slug = "mood-orb-jar", name = "Mood Orb Jar", category = "Gestures", spec = "A mood journal on warm paper: a clear soda-lime glass jar with a knurled steel lid holds the month's moods as glass beads in a calm range (dusk, rain, sand, sage, apricot), stacked by physics, with the month and its count printed on the glass. Flick a bead up from the five-mood picker: it passes in front of the jar, the lid lifts, it drops through the mouth and lands on the pile with a knock that rocks the jar; a copy flies to the list and the day's entry grows out of it. Swipe that entry to undo and the bead rises out of the jar back to the picker. Every picker bead is also a button.") { MoodOrbJarDemo() },
    Block(slug = "pinch-to-summarize", name = "Pinch to Summarize", category = "Gestures", spec = "A long-form review in an invented reading app, with a masthead, a dark header panel, a serif headline and a duotone photo. Pinch the article and the summary is visibly made from it: while the fingers close, the rest of the page washes out and four key sentences get a lavender highlighter sweep, locking in one by one with a tick; a small label under the page shows how deep the summary will be (Key points, Brief or TL;DR, deeper pinch, shorter summary). Let go and the page waits, still readable, while the picked sentences pulse in turn (“Summarizing for you…” if it takes a moment). Then each sentence lifts off the page as a chip and flies on a curved path into the summary line it became, while the page settles into a small card at the top of a drifting blue-to-pink gradient. The summary is a lead, entity chips (tap one to light its words) and icon-led points with source marks; the price rolls in and the review meter fills to 4 of 5. The card shows how far you had read, and the footer reads “You read 50% · 14 min → 40 s” with rolling numbers. Tap a point to see its sentence in the article, flashed; pinch out, tap the card or the close button and the chips fly home. Long-press the summary to lift it as a card with Copy summary and Share. The article keeps an opaque band under the status bar, so nothing scrolls over the clock.") { PinchToSummarizeDemo() },
    Block(slug = "pull-cord-theme", name = "Pull Cord Theme", category = "Gestures", spec = "A reading app whose Day/Night switch is the lamp over the page. A green enamel pendant hangs over a chapter of an invented novel; a nickel ball chain hangs from a knurled switch housing under the shade. Take the pull (or any ball of the chain) and tug: past the click the filament fades through orange and the room goes dark, the far corners first and the pool under the shade last; pull again and the filament warms from ember to warm white while the lit page develops out of the pool of light the shade throws, text changing colour inside the glyphs as the front crosses them. The light is a light field, not a gradient: a cone with a soft penumbra, falloff with distance, a faint haze with a few dust motes, the chain's soft shadow on the page, the shade's own shadow above it. The chain swings with the finger, shivers at the click and springs back; the shade sways and its light swings with it. Tapping the pull or the switch's accessibility action plays the same tug.") { PullCordThemeDemo() },
    Block(slug = "pull-lever-refresh", name = "Pull Lever Refresh", category = "Gestures", spec = "A lever espresso machine drawn in Skia and shot like a product photo: one key light from the top left on a warm near-black studio sweep with a fine grain. A matte black body with a brushed steel top carries a 0–12 bar pressure gauge (polished bezel, printed scale, a brew zone from 8 to 10 bar, an orange needle under a domed glass) and a shot timer of two drums behind glass with a small amber pilot lamp. A polished chrome group head stands off it on a neck, with the lever on top (a brushed steel arm round a polished hub, a turned and lacquered walnut handle), the portafilter below (chrome basket, two spouts, walnut handle), and a white porcelain cup on the drip tray's slotted grate. Chrome, steel, walnut, porcelain, glass and coffee are SkSL runtime shaders that reflect one studio; the lever's highlights are computed from its angle, so its sheen and the walnut's lacquer move as it turns. Pump the lever down: each stroke adds 3 bar and the needle steps up with an overshoot (\"Building pressure · 3 bar\", \"6 bar\"); at 9 bar the brew zone lights (\"Release to brew\"). Let go and the spring pushes the lever back up slowly while the shot pours: first drips, then two thin tiger-striped streams that blond toward the end, the cup filling under a mottled hazelnut crema, the needle falling and the timer counting (\"Brewing · 13 s\"). When it is done the pilot lamp glows warm, steam rises and the copy reads \"Espresso ready · 9 bar · 27 s · 36 g\". Pull again and the full cup slides out while an empty one slides in. The machine is fitted with the lever's whole travel at least 16 pt inside both screen edges, under the copy.") { PullLeverRefreshDemo() },
    Block(slug = "save-to-collection", name = "Save to Collection", category = "Gestures", spec = "Atlas, a quiet photo browser at night: a black page, \"Discover\" and a row of chips, a two-column masonry of places, and the chrome as glass floating over the photos (a tab capsule and a round saved button with a count). Hold a photo until it lifts and carry it down: it leans with your finger, the others step back, and near the saved button it is pulled in and shrinks while the button swells. Let go over it and the button swallows the photo with a small bounce, the count rolls from 12 to 13, the photo in the feed gets a saved mark and a glass toast says \"Saved to Slow coast · View\". Tap the button (or View) and the collection rises as a sheet: the places already in it sit in a 2-column grid with their names and the new one settles into the first cell, marked \"Just saved\". Let go anywhere else and the photo springs home.") { SaveToCollectionDemo() },
    Block(slug = "slide-to-answer-cord", name = "Slide to Answer Cord", category = "Gestures", spec = "An incoming call answered by lifting a real receiver: an ivory bakelite handset hangs on its coiled cord in a dark room lit from the upper left, swinging and buzzing at each ring, above an iOS call screen (\"Mara Lindqvist\", \"mobile\", \"Lift the receiver to answer\", red Decline and green Accept). Lift it to answer: it stays up, Accept fades, Decline slides to the middle as End, Mute, Keypad and Speaker rise above it and the timer runs. Pull it down to decline, or to hang up during the call. The coil bunches when lifted and stretches thin when pulled, its far half-turns in shadow and the receiver casting a soft shadow on the wall. The buttons do the same for a tap or VoiceOver.") { SlideToAnswerCordDemo() },
    Block(slug = "tilt-poster-parallax", name = "Tilt Poster Parallax", category = "Gestures", spec = "A streaming app's film page at night for \"The Long Light\": glass close, awards and share buttons inside the safe area, the poster card, then the title in Instrument Serif, its year, genre and length, a glass Watchlist pill and a Play trailer button, and a three-line synopsis with Show more. The poster is painted in code in five depths (a dusk sky, a low sun, three ridges from haze to near-black with a walker on the nearest) under an embossed gold-foil title, and they slide against each other as the card turns with the phone's rotation or a finger; the emboss's shadow side moves with the light, a foil band and a faint holographic sheen run through the title, a glare swims against the tilt, and the same poster, blurred, is the page's backdrop. Hold the card and it rises; let go and it springs back with one soft wobble. The print is 4.5 pt deep and its cream edge shows past about 8°. Tap it to turn it over to the credits; Watchlist morphs into a gold Added pill with a tick.") { TiltPosterParallaxDemo() },
    Block(slug = "tilt-swipe-actions", name = "Tilt Swipe Actions", category = "Gestures", spec = "A private-banking ledger on warm laid paper: one engraved ink account card with a brass hairline frame and woven cheque lines, a balance set like a cheque in Bodoni Moda (raised brass dollar sign, ivory cents), and \"Latest spending\" as a ruled ledger of six transactions in one money style (–\$114.00). Swipe a transaction right and keep pulling: the line lifts as a strip of heavier paper and breaks into equal shares, one person per detent (2 to 5), each share with the person's monogram, name and amount; yours turns to ink with a brass monogram, the others stay paper. An ink bar rides over the row above (\"\$96.60 ÷ 2 3 4 5\", the count on a brass disc) and the other rows dim. Let go on two or more and the shares heal into one row reading \"–\$32.20 of \$96.60 · Split with Mai, Leo\" with small monograms; the requested people's monograms fly from their shares to an ink toast (\"Requested \$64.40 · Mai and Leo · \$32.20 each\") with a brass Undo, the week total rolls down. Undo leaves the row whole: its amount rolls back to –\$96.60, \"of \$96.60\" fades, the subtitle cross-fades back to \"Dining · Yesterday\", the week total rolls back and the toast leaves with its monograms. Let go before the first detent and it springs back. Swipe left for Flag and Delete as flush graphite and oxide tiles; past the middle Delete swallows the strip, and a delete folds the slot with an Undo toast. The name never peeks out as a fragment while the row is open. The FAB sits in the tab bar and opens Income, Expense and Transfer. Every row has Split between 2–5 people, Flag and Delete as accessibility actions.") { TiltSwipeActionsDemo() },
    Block(slug = "booster-pack-opening", name = "Booster Pack Opening", category = "Gestures", spec = "A sealed foil booster pack that is torn open with a swipe. The tear follows the finger across the top of the pack in either direction while the torn strip folds over and curls; when the cut reaches the far edge there is a flash, the strip flies off, the mouth of the pack opens and slides down, and the first card rises and centres. Five cards are then revealed one at a time: drag to tilt the stack, tap or flick to bring the next one, and the two rarest turn through their back with a foil sweep, sparkles and a coloured backdrop. The last card stays until \"Open another pack\" is pressed. Tearing, opening and each card have a sound, over a looping ambience.") { BoosterPackOpeningDemo() },
    Block(slug = "chrome-prize-wheel", name = "Chrome Prize Wheel", category = "Gestures", spec = "Daily Spin: a dark indigo donut-café reward screen with a reflected chrome wheel, six glossy blue wedges, upright prize objects, a hinged magenta gem pointer and a quiet glossy star field. The winning prize leaves its wedge, grows into a floating hero and reveals a chrome count above a Collect button. Responsive measured composition, accessible spin and collection, and a still Reduce Motion presentation.") { ChromePrizeWheelDemo() },
    Block(slug = "day-one-medal", name = "Day One Medal", category = "Gestures", spec = "A collectible achievement medal that you forge, turn over, spin and wear on a ribbon. Its grid slot starts as blank iron and becomes the current forged Day 1, Day 7 or Day 30 medal, with an engraved back and a dark achievement sheet.") { DayOneMedalDemo() },
    Block(slug = "foil-pack-tear", name = "Foil Pack Tear", category = "Gestures", spec = "A collectible foil booster pack suspended inside a cyan, blue and violet rarity frame on a dark, reflective stage. Tear the crinkled HALCYON wrapper to discover Solstice Koi, a legendary holographic card with a luminous koi circling a pale sun.") { FoilPackTearDemo() },
    Block(slug = "goo-pull-refresh", name = "Goo Pull Refresh", category = "Gestures", spec = "A two-column photo feed of cats and birds seen from neighbours' windows, under a white header with a bold \"Sightings\" title, a bell and a row of filter chips. Each tile is a rounded photo cropped portrait, square or landscape, with a one-line title and a byline of a monogram, a name and a like count. Pulling the feed down draws a drop of orange liquid out from behind the header's edge on a neck that thins as you pull, until it snaps and the drop hangs free, jiggling. Let go and the drop becomes a gooey loader: three droplets breathe out of a core and pinch off as the trio turns, then melt back together; the header draws the drop back up into itself, the feed closes and a new row of two photos, marked with an orange dot, slides in on top.") { GooPullRefreshDemo() },
    Block(slug = "pinch-density-grid", name = "Pinch Density Grid", category = "Gestures", spec = "A herbarium of thirty-six botanical plates (leaves, bouquets and tulips) on warm paper whose column count follows a pinch: spreading the fingers walks the grid from five columns to three, two and one, and pinching walks it back, every plate sliding and growing between the two neighbouring grids around the fingers instead of jumping, the plate under the fingers staying under them. The dense grid is laid nearly edge to edge with square-ish corners; as it opens up the gaps, margins and corner radii grow, and at two columns and one each plate gets its name, its species and a small \"No. 07\" underneath. A medium-weight \"Herbarium\" title sits at the top with \"36 plates · Pinch\", and at the right a small ladder of the column counts, 5 3 2 1, with a dark pill sliding between them as the grid changes.") { PinchDensityGridDemo() },
    Block(slug = "scratch-ticket", name = "Scratch Ticket", category = "Gestures", spec = "A scratch-off lottery ticket lying on a dark green table: cream card stock with a printed dashed frame, a sunflower mark, the title \"Lucky Bloom\" and a tear-off stub joined by a row of punched holes, its prize line hidden and a barcode beside it. The middle is a window of holographic foil, brushed silver with a fine diamond guilloché, soft iridescent bands, a drifting sheen and twinkling four-point sparkles, with a sunflower and \"Scratch to reveal\" pressed into it. A finger rubs the foil away along a soft round brush, shedding little foil flakes that tumble down the screen; once enough is cleared the rest dissolves with a hot golden edge, the sunflower photo underneath settles into place, the stub prints the prize and confetti bursts. \"New ticket\", or throwing the ticket off to the left, deals the next one in from the right.") { ScratchTicketDemo() },
    Block(slug = "sticker-board", name = "Sticker Board", category = "Gestures", spec = "A cork board covered in die-cut stickers with thick white borders and soft shadows: round and rounded photo stickers of fruit and dogs, a star, a smiley, a pink speech bubble, a green scalloped seal and a heart, under a strip of masking tape with the board's name. Any sticker can be dragged, turned with two fingers and pinched at the same time; it lifts as it is picked up and slaps down with a squash when let go. A long press lifts a corner instead: it curls back over the sticker after the finger, showing its pale backing, until the sticker comes off. Then a small steel pedal bin rises from the bottom edge, leans towards the loose sticker and opens its hinged lid as it comes near, pulls it in over its mouth, and on release crumples it into a paper ball that drops in before the lid slams shut and the number on the bin ticks up.") { StickerBoardDemo() },
    Block(slug = "breathing-gap-grid", name = "Breathing Gap Grid", category = "Gestures", spec = "A wall of square tiles on a black screen in four columns centred on it, the outer two running half off its edges: eighty editorial photos (portraits, busts and plaster casts, ceramics, dried flowers, fashion, sneakers, chairs and still lifes, a dune) mixed with seven squares of set type (a white \"A\" on cobalt, a red \"N\" on cream, \"ROOM\" three times in white on black, \"Hi.\" in black on white, \"LOOK\" twice in cobalt on white, a white \"O\" on red, \"GAP\" in black on cream), dealt so that the same tile never appears within eight cells of itself. Each photo darkens softly towards its bottom edge. Tiny capitals sit in the corners: \"Studio Notes\", \"Frames\" and a live readout of the columns and the gap (\"4 col · Gap 14 pt\") along the top, \"Pinch\", \"Drag\" and \"Tap\" along the bottom. Opened out, the wall zooms out to eight whole columns of small tiles with even margins at both edges, and the rows part around a darkened lane across the middle where \"Room to breathe\" sits in spaced capitals between two thin rules. A tapped tile lifts out to nearly the full width over the blurred, dimmed wall, with a glow in its own colour beneath it and its note and title underneath.") { BreathingGapGridDemo() },
    Block(slug = "choose-your-ball", name = "Choose Your Ball", category = "Gestures", spec = "A full-screen picker that shows one of 26 balls at a time as a glossy 3D model lit by an HDR room. A swipe, or a tap on the strip of thumbnails, turns the shell one full revolution into the next ball, and the backdrop, the wordmark and the button's label change with it.") { ChooseYourBallDemo() },
    Block(slug = "glowknob-console", name = "Glowknob Console", category = "Gestures", spec = "A volume and brightness console that behaves like hardware: a pill of liquid light to drag, a knurled knob with 28 detents to spin and flick, and two buttons that hand the light from warm to cool. Hold the housing and the flat drawing becomes a 3D object that rises off its glass floor, turns over under the finger to show an engraved back, and sets down again.") { GlowknobConsoleDemo() },
    Block(slug = "reward-card-reveal", name = "Reward Card Reveal", category = "Gestures", spec = "A collection grid of achievement cards. Tapping an unlocked card lifts it out of the grid into a detail view with its title and description below, where the card tilts in 3D under your finger with a holographic sheen.") { RewardCardRevealDemo() },
    Block(slug = "paste-places-import", name = "Paste Places Import", category = "Inputs", spec = "An import screen for places kept in notes or messages: a large text area with a paste button, a character counter and a start import button that stays disabled until there is text. Pasting a note fills the area; import picks out the city and every place in it, and the text area folds open into a small map of the city with each place pinned on it and a route through them.") { PastePlacesImportDemo() },
    Block(slug = "send-amplify-preview", name = "Send Amplify Preview", category = "Inputs", spec = "A frosted message composer previews a sculpted 60 wearing a soft red-and-white cap. Four selections conceal it behind opaque ink, inflate it gently, swell and recoil, or launch an oversized tilted slam that snaps upward through a spreading shadow. Tap or drag between effects, or use the local preview and reset controls.") { SendAmplifyPreviewDemo() },
    Block(slug = "rotary-phone-dial", name = "Rotary Phone Dial", category = "Inputs", spec = "A vintage rotary dial set in a bottle-green bakelite body: a cream enamel number plate with the digits and exchange letters printed under the holes, a turned chrome finger wheel with ten holes, a curved chrome finger stop, and a number card (\"Elmwood 5-0193\") under a clear dome in the middle. Put a finger in a hole and turn the wheel clockwise to the stop; let go and it runs home at a steady governed speed, a pulse dot filling for each number that passes the stop, and the dialled digit drops onto the paper tape above in typewriter type, grouped like a phone number. Letting go before the stop returns the wheel without dialling; holding the card clears the tape. \"Rotary Dial\" and the card's number sit above the tape, \"Turn a hole to the stop · Hold the card to clear\" below.") { RotaryPhoneDialDemo() },
    Block(slug = "ink-signature-pad", name = "Ink Signature Pad", category = "Inputs", spec = "A full-screen signature page on warm near-black: a small \"STUDIO LEASE · PAGE 4 OF 4\" over a serif \"Sign to accept\", then a tall sheet of speckled cream paper with a printed acceptance line at the top, a signature line marked with an × near the bottom and \"MARA ELLISON · TENANT\" and the date under it. A finger writes on it in fountain-pen ink that is thick where it moves slowly and thin where it moves fast, glossy royal blue while wet and blue-black once dry. Below the paper sit three pill buttons, Clear, Replay and Done: Clear sweeps a walnut wiper with a felt edge and a brass knob across the page, Replay redraws the signature at the pace it was written with a gold nib over a pale ghost of it, and Done shrinks the page onto two earlier pages of the lease and presses a red wax seal with the monogram \"ME\" on its corner, under \"Lease sealed\" and \"Signed by Mara Ellison · 13 Oct 2026\".") { InkSignaturePadDemo() },
    Block(slug = "liquid-search-morph", name = "Liquid Search Morph", category = "Inputs", spec = "A light shop home page on warm paper: \"ATELIER NORD\" with a bag button, a large \"Walk soft, smell of rain.\", an ink-black search pill reading \"Search 12 pieces\", a hero photo of a sneaker on orange labelled \"Dune Slip Low\" and €148, and two trending pieces. Tapping the pill pulls it up to the top of the screen and across it like a drop of ink, the magnifier trailing as a smaller drop that parts from it on a thread and melts back in, while the page shrinks back under a frosted blur and Cancel slides in. Recent searches pop in as white chips under the bar with a numbered Popular list below them. Typing filters a two-column grid of sneakers, scents and jewellery live (\"air\" leaves five), with a count line above it; tiles pop in, fade out when they stop matching and flow to their new places. Cancel pours the bar back into the pill.") { LiquidSearchMorphDemo() },
    Block(slug = "morph-otp-input", name = "Morph OTP Input", category = "Inputs", spec = "A one-time-code screen on near black: an open envelope in a mint circle, \"Check your inbox\", the address the code went to, and a row of six soft rounded cells with crisp hairline borders. The focused cell's border lights mint and a copy of it collapses into a glowing mint caret that breathes; typed digits rise softly into their cells and settle, each digit clipped to its own cell. A wrong code shakes the row, flushes the cells and digits red over \"That code didn't match. Try again.\", then the digits drop out one by one. The right code slides the six cells together into one pill carrying the digits, closes it into a mint circle, draws a check and sends out a crisp ring, a fainter second ring and a burst of short dashes, while the title turns to \"You're in\". Below the row a \"Resend code in 0:30\" countdown turns into a tappable \"Resend code\". A hidden text field takes the keyboard, paste and one-time-code autofill.") { MorphOtpInputDemo() },
    Block(slug = "pattern-lock-input", name = "Pattern Lock Input", category = "Inputs", spec = "A 3×3 pattern lock on a near-black screen lit by a soft aura in the lock's colour, under a small \"Private notes\" label and the title \"Draw to unlock\". Drawing connects the dots with a glowing cyan line whose open end lags behind the finger and bows like a stretched rubber band; each dot it reaches pops with a springy core, a halo and a ripple ring, snapping the line's end onto its centre with a little wobble, and dots the line passes over are picked up too. A wrong pattern turns the line and dots red, shakes the grid and fades away; the right one, a \"Z\", flashes green, the dots collapse into one glowing point that swells into a padlock, whose shackle draws on and springs open as a check is drawn on its body, and then the grid comes back.") { PatternLockInputDemo() },
    Block(slug = "attachment-tray-input", name = "Attachment Tray Input", category = "Inputs", spec = "A prompt composer on a white screen, built as two stacked parts in one rounded light grey container: a tray of attachment chips on top (white pills with a file-type icon, a truncated name and a cross: \"contract-agree...\", \"cloud.png\", \"folder 3\") and a white text area below with the placeholder \"Add instructions from attached images...\". Its toolbar holds an attach button, three selection tools on a grey track with a white tile under the chosen one, a \"Nova 2.0\" model label and a round black send button. Holding a chip hangs a preview card from it: the full file name, a monospaced \"PDF · 2.3MB · 93 LINES\" line and a boxed summary whose text fades out at the bottom.") { AttachmentTrayInputDemo() },
    Block(slug = "docking-prompt-card", name = "Docking Prompt Card", category = "Inputs", spec = "An assistant prompt on a rounded charcoal panel with a slowly drifting violet and magenta aurora. A glass card with a violet edge and a magenta glow along its bottom holds an \"AI Assistant\" picker, the heading \"What are you working on?\" and a real text field with a plus, the placeholder \"Ask me anything\" and a microphone that becomes a white arrow disc once something is typed. On send the sentence flies up into a violet message bubble at the top right, the card shrinks into a slim capsule docked at the bottom of the panel, three thinking dots pulse under the bubble, and then the card rises back and its heading resolves again from left to right.") { DockingPromptCardDemo() },
    Block(slug = "folding-message-bar", name = "Folding Message Bar", category = "Inputs", spec = "A chat composer at the foot of a deep teal gradient panel, under a support message (\"Can you send me your order ID so I can check right away?\"). The bar holds a field with a smiley, the placeholder \"Message...\" and three outline tools (paperclip, image, camera), next to a square white button with a teal microphone. While a message is written the tools fold away and the microphone becomes a send plane; sending turns the text into a white bubble with teal type above the bar, under \"You\".") { FoldingMessageBarDemo() },
    Block(slug = "glow-border-chatbar", name = "Glow Border Chatbar", category = "Inputs", spec = "A dark assistant chat bar on a black screen: a violet sparkle and \"Hi Alex\" above the question \"What’s the opening move?\", then a two-row rounded field whose first row reads \"Ask Swift ⌄ anything...\" with the model picker inside the sentence, and whose second row holds a plus, a sliders icon, a mic and a round send button. A light with a white hot spot and pink and violet tails keeps travelling around the field's border, with a dimmer pink streak on the opposite side. Under the field a row of grey pill chips (\"Create image\", \"Compose music\", \"Help me learn\", \"Boost my day\") scrolls sideways and fades out at the right.") { GlowBorderChatbarDemo() },
    Block(slug = "growing-composer-pill", name = "Growing Composer Pill", category = "Inputs", spec = "A white chat composer on a pastel panel of lavender, sky blue and pink. Empty, it is a 48 pt pill with a thin plus, the placeholder \"Ask anything\" and a microphone; with the first character a round black send button with a white arrow takes the microphone's place. Once the text no longer fits beside the buttons the pill opens into a rounded card, the text at the top and the buttons on their own row along the bottom, and after sending it shrinks to a small pill that reads \"Thinking…\".") { GrowingComposerPillDemo() },
    Block(slug = "hold-to-speak-input", name = "Hold to Speak Input", category = "Inputs", spec = "A chat field on a charcoal screen that doubles as a push-to-talk button: a near-black pill with a hairline that runs from teal through green to yellow, the same light bleeding out along its edge, the placeholder \"Start typing or hold to speak.\" with a blue caret, and five suggestion chips stacked in three rows above it (\"Plan my day\" outlined in the gradient). Holding the pill swaps the placeholder for five white level bars and \"Listening\", puts a mic under the finger and \"Slide up to cancel\" with a chevron above it; sliding up turns the light red and the hint into a cross over \"Release to cancel\". Releasing in place drops the transcript into the field; a tap focuses it for typing instead.") { HoldToSpeakInputDemo() },
    Block(slug = "image-prompt-card", name = "Image Prompt Card", category = "Inputs", spec = "A prompt card that takes reference images, on light grey. Above it sit two white picker chips (\"Nova 2.1\" with an asterisk mark, \"Creative Agent\" with a lilac avatar) and two bare icons; the white card has a purple wand at its top right, a real text field, a bottom row of a plus, three tools, two more on the right and a black rounded-square send button. Attached photos stand in a row of 44 pt thumbnails with white frames and round \"x\" badges above the text \"Make a moodboard from these photos\".") { ImagePromptCardDemo() },
    Block(slug = "jelly-attach-capsule", name = "Jelly Attachment Capsule", category = "Inputs", spec = "A violet-blue message capsule on a pale lavender screen, with a large soft shadow of its own colour: a lighter round \"+\" button at the left and an inner pill field with the placeholder \"Message\". Tapping the plus turns it into a cross and replaces the field with three more round buttons spread along the capsule, each with a white outline icon: video camera, photo camera, picture.") { JellyAttachCapsuleDemo() },
    Block(slug = "mode-switcher-input", name = "Mode Switcher Input", category = "Inputs", spec = "A near-black prompt composer on a dark navy screen, lit from behind by two large soft glows, coral at its top-left corner and blue at its bottom-right, that also rim its ends with light and pick a faint grid of dots out of the dark. Its hairline border runs from the left glow's colour through a pale middle to the right glow's. Inside: the placeholder \"Ask anything...\" and a row of small dark pills: \"+\", a tone pill (\"Normal\"), the mode pill (\"Balanced\") with a chevron, a voice button and a round violet-to-coral send button. The mode pill opens a menu of four modes with icons (Quick answer, Balanced, Deep think, Research), the one in use ticked.") { ModeSwitcherInputDemo() },
    Block(slug = "model-picker-prompt", name = "Model Picker Prompt Box", category = "Inputs", spec = "The prompt box of an assistant called \"Atlas\" on a near-black screen with a warm terracotta glow: the name in a white serif beside a coral compass-star mark, and under it a dark rounded box with a coral hairline that holds the placeholder \"How can I help you today?\", a plus, the model label \"Swift\" with a chevron and a waveform icon, above a row of four outlined chips (\"Create\", \"Write\", \"Learn\", \"Code\"). The waveform gives way to a coral rounded-square send button once there is text and to a turning stop ring while an answer is generated, and the model label opens a menu of three models with one-line descriptions and a coral check on the selected one.") { ModelPickerPromptDemo() },
    Block(slug = "morphing-mic-pill", name = "Morphing Mic Pill", category = "Inputs", spec = "An assistant panel on a warm grey screen: an off-white rounded card headed \"You might want to ask\" with three white suggestion cards (a two-line question, a small picture on a tinted disc and an arrow) above a bottom bar of a white round \"+\" button, a black capsule with a white mic, and a white round keyboard button. Tapping a suggestion sweeps a lilac-grey veil with a pale iridescent sheen up over the cards, which wobble as it passes, while the round buttons step back and the capsule stretches into a white-outlined \"Thinking…\" pill with a pulsing dot; the veil then lifts on a four-line answer and the capsule springs back. Holding the capsule swells it and shows seven level bars, the keyboard button stretches it into a text field (\"Ask anything\") and becomes the send button, and \"+\" brings the suggestions back.") { MorphingMicPillDemo() },
    Block(slug = "orbit-prompt-pill", name = "Orbit Prompt Pill", category = "Inputs", spec = "A prompt field on an off-white screen whose attachments circle it: a white pill with a thin grey \"+\", the text and a round black send button with a white arrow. Once something is typed (the demo types \"What's today's run?\"), three blue tag chips with a small cross each (\"Daily\", \"Trail\", \"Run\") rise from behind the pill's top edge, a cyan light crosses the pill, and five rounded photo thumbnails burst out from behind it onto a tilted ring: behind the pill on the far side, in front of it on the near side, larger the nearer they are. \"+\" adds a picture to the ring, up to seven; sending spirals them all into the send button, which jumps and throws a ring.") { OrbitPromptPillDemo() },
    Block(slug = "rainbow-outline-search", name = "Rainbow Outline Search", category = "Inputs", spec = "A search pill on light grey that is only an outline, and only part of one: a ribbon of green, yellow, red, violet and blue runs over the top left, round the left cap and along the bottom, fading out to the right, with a magnifying glass and sparkle icon at its left end. A tap snaps it open into a white input card with a real text field, a close button, image, lens and microphone tools and a blue send button, while a green, yellow and red streak travels round its pale blue border. On send the card folds into a thin line of blue light that bows and fades, and the outline is drawn again from the right.") { RainbowOutlineSearchDemo() },
    Block(slug = "rotating-suggestions-input", name = "Rotating Suggestions Input", category = "Inputs", spec = "An assistant's composer on a light grey panel titled \"Nova\", with a faint four-pointed sparkle behind it. A grey plus and a white pill field (\"Ask anything\") sit above a small line of legal text, and three white suggestion pills are stacked above the field, left-aligned with it, each as wide as its text and led by a small icon (sparkles, bars, a speech bubble). The suggestions change by themselves, and a tapped one drops into the field, is typed there beside a round black send button and is sent.") { RotatingSuggestionsInputDemo() },
    Block(slug = "slash-command-input", name = "Slash Command Input", category = "Inputs", spec = "A dark two-row composer on a near-black screen, with a faint blue light under its right corner: a text row (\"Ask, or type / for commands\") above a row of context chips, each a blue-grey pill with a blue check dot, its name and a small cross (\"Design\" at rest). Typing \"/\" boxes the slash as a token and opens a command menu right under it, grouped under small caps headers: CONTEXT (design-file, from-brief, from-code, past-output) and SKILLS (contrast-check, give-variants, critique, ally-check), with a pale highlight bar behind one row. Choosing a context flies its name down into the chip row and takes the token out of the text; choosing a skill leaves it in the text, as \"/critique\" inside a blue-tinted box.") { SlashCommandInputDemo() },
    Block(slug = "smart-token-input", name = "Smart Token Input", category = "Inputs", spec = "A task composer on a blue-grey screen: a white card with a checkbox, a real text field, a calendar button and a \"No list\" chip. As \"Send email to John on Wed\" is typed, the date word turns blue and a small \"Schedule\" menu with two dates opens under it; picking one puts a blue dot on the calendar button. Typing \"/\" opens an \"Attachment\" menu with a grey \"ile\" completing \"/f\", and its \"File upload\" row drops a \"Redesign.doc\" chip into the sentence while the card grows line by line.") { SmartTokenInputDemo() },
    Block(slug = "swipe-reply-composer", name = "Swipe to Reply Composer", category = "Inputs", spec = "A dark chat panel: a title chip (\"Weekend in Lisbon\"), three paragraphs of an assistant's answer in a light serif, and a composer along the bottom with a round plus and a pill field (\"Reply to Atlas\") that holds a round send button. Swiping a paragraph to the right pulls a coral reply arrow out beside it and dims the rest; once quoted, the paragraph keeps a coral bar at its left edge, a preview of its first words with a small \"x\" sits on top of the composer, the placeholder reads \"Reply to this part…\" and a \"Branch\" pill with a branching arrow stands beside the field.") { SwipeReplyComposerDemo() },
    Block(slug = "thinking-frame-search", name = "Thinking Frame Search", category = "Inputs", spec = "A white search field on a light grey screen with the placeholder \"Search or ask\" and a small grey waveform icon at its right end. Submitting a query wraps the field in a gradient frame of purple, magenta, orange and amber with a taller band on top, which reads \"Thinking…\" behind three pulsing dots at the left and names the current step at the right (\"Reading notes\", \"Checking calendar\", \"Looking for files\"). The frame then melts into a white panel below the field, \"Top results\", with three rows that each show a small gradient tile, a title and a grey detail.") { ThinkingFrameSearchDemo() },
    Block(slug = "tone-rewrite-composer", name = "Tone Rewrite Composer", category = "Inputs", spec = "A rewrite sheet for a chat draft on a pale blue to lavender gradient panel: \"Cancel\" on the left, a spark mark and \"Rewrite\" in the centre, \"Apply\" on the right, pale until there is a result. The draft (\"It's getting ugly out here\") sits in the middle as a blue bubble above a scrolling row of white tone chips (\"Rephrase\", \"Fix grammar\", \"Make funnier\", \"Shorter\", \"Make supportive\") and a white instruction field (\"Describe your changes\") with a round send button. Choosing a chip or sending an instruction dissolves the bubble into a pale shimmering shape, then the rewrite is written into it, the bubble grows to three lines and two dots appear under it.") { ToneRewriteComposerDemo() },
    Block(slug = "voice-note-composer", name = "Voice Note Composer", category = "Inputs", spec = "A chat composer on a rounded sunset panel (blue-grey at the top, peach, then orange) on a dark screen, every element frosted translucent white with navy ink: a round \"+\" button and a pill field with the placeholder \"What’s on your mind\" and a small waveform icon, under an incoming bubble that asks \"How was the flight?\". The waveform icon turns the pill into a recorder (a waveform of thin bars, a timer, a round stop button), then into a preview (play button, waveform, \"0:02\", a discard cross and a send arrow), and a sent take becomes a bubble above the composer with its own play button and waveform, the line \"Generating transcript…\" and then the transcript in two lines. Nothing is recorded: the waveform is a fixed pattern, and callbacks mark where a recorder goes.") { VoiceNoteComposerDemo() },
    Block(slug = "race-result-standings", name = "Race Result Standings", category = "Lists", spec = "A dark race results screen for Round 09, Harbor GP: a back button, a \"Race Results\" title with a ⇅ switch, the podium's three-letter codes behind their livery marks, a navy 3D circuit, the fastest lap, driver of the day and fastest pit stop, then six standings rows with position, driver, team in its colour, places gained and points. Tap the circuit to replay the race: it lifts out of its corner into a live map, the start lights go out, six team-coloured cars race two laps with light trails, and every overtake on the track swaps the two rows in the standings at that instant, with each car's points rolling in as it takes the flag. Tap the title or swipe left across the list to switch between the race and the sprint: every driver drives to the new finishing order, overtakers lifting over the cars they pass, while the points and the podium livery change in place and a comet laps the circuit to set the fastest lap.") { RaceResultStandingsDemo() },
    Block(slug = "for-you-insights", name = "For You Insights", category = "Lists", spec = "A pale health feed: a rail of glass context tiles, a bold AI tip and editorial article rows with painterly art, over a Liquid Glass tab bar. Tap an article and its illustration lifts out of the row and opens as a deep, layered hero above a reader; drag the hero to look around the scene, pull it down to put it back. The tip can rewrite itself on demand.") { ForYouInsightsDemo() },
    Block(slug = "contact-file-stack", name = "Contact File Stack", category = "Lists", spec = "A contact directory is organized as a stack of thin tabbed folders on warm grey paper. One file lifts out, opens, and releases a fan of business cards and small scenic prints before settling back into the index. Tap or drag to unfold the file.") { ContactFileStackDemo() },
    Block(slug = "folding-week-agenda", name = "Folding Week Agenda", category = "Lists", spec = "A bright personal agenda with a charcoal two-week calendar and softly separated appointment rows. The calendar continuously folds into a compact next-appointment capsule as the rows rise beneath it. Original silhouettes and small color-study artwork keep the quiet look of the reference.") { FoldingWeekAgendaDemo() },
    Block(slug = "heart-loupe-agenda", name = "Heart Loupe Agenda", category = "Lists", spec = "A scarlet collage surrounds a metal schedule dispenser with an outlined script masthead, candy hearts, a record player and a small heart bag. A paper agenda unrolls as a clear heart loupe on an articulated silver arm appears and magnifies the scrolling event text. The reference composition is recreated with the invented My Little Loop identity and original charm artwork.") { HeartLoupeAgendaDemo() },
    Block(slug = "bank-card-picker", name = "Bank Card Picker", category = "Lists", spec = "A debit card designer, copied from a bank app's card screen. Under a teal hero the chosen card stands at an angle in front of a stack of glass plates that recede down and to the left, above the product name, the illustrator's credit with a lime price pill, and a row of design thumbnails with a lime ring on the chosen one. Below sit a Basic / BloomPrime switch, a white panel with the card's monthly fee and cashback categories, and a dark Get the card button on a frosted bar. Picking a thumbnail swaps the front card for that design; picking the other plan changes the fee and the number of categories. The flowered card is drawn in code; the four illustrated designs are invented, and the bank's name, logo and card network are replaced by Bloom Card, a leaf mark and an invented network mark.") { BankCardPickerDemo() },
    Block(slug = "believe-card-carousel", name = "Believe Card Carousel", category = "Lists", spec = "The opening of a crowdfunding-style app. A grey mark on a white splash gives way to the headline \"Believe in Someone\", and three project cards rise from below: a big centre card for Beehive (green picture with its app icon, \"I believe in\", the name, a date and who made it) flanked by a smaller food-app card on the right and a third cut off at the left edge. The headline's last word blurs into \"Something\", then the row and headline lift away and Get Started, Already have an account and the terms line come up from the bottom. The cards can be dragged sideways.") { BelieveCardCarouselDemo() },
    Block(slug = "card-balance-wallet", name = "Card Balance Wallet", category = "Lists", spec = "A black card-balance home: a profile portrait and name with a notification bell, a wide card whose art is a sunset gradient seen through reeded glass with its balance in large type, white \"add money\" and \"transfer\" buttons, page dots, scan and add tiles, a \"Spent in May\" panel with a four-colour split bar, and a floating tab bar. A finger on the card tilts it toward the finger and the reeds refract with the tilt.") { CardBalanceWalletDemo() },
    Block(slug = "donation-fan-carousel", name = "Donation Fan Carousel", category = "Lists", spec = "A latest-donations screen places a compact photographic fan beneath its date header. The active donor is a square portrait with a lime keyline and two lines of metadata; smaller portraits recede behind it on both sides. A green contribution coin and three red hearts briefly collect over the active portrait while the fan advances through three donors.") { DonationFanCarouselDemo() },
    Block(slug = "film-poster-carousel", name = "Film Poster Carousel", category = "Lists", spec = "A film card that fills the screen: the film's key art bleeds from the top into a dark panel tinted to the film, with its title, year and director, running time, star rating and hashtag chips, a small up-chevron, and a close button in a white square. The panel's rounded bottom lies over a coloured Watch now footer. Swipe sideways to the next film: the art slides in behind its frame, the text arrives line by line and the panel and footer change colour with it.") { FilmPosterCarouselDemo() },
    Block(slug = "for-you-card-stack", name = "For You Card Stack", category = "Lists", spec = "A book app's For you screen: a pink page with a search field and a blue Design card holding a deck of book covers under New & Trending and a row of Top Charts. Pulling the front cover aside reveals the next one in the deck; tapping it pushes an audiobook player with the cover, title and controls. Play shrinks the cover into the page as a lilac wave rises, opens it and riffles to a spread while the passage lights up line by line; pause riffles back and closes the book.") { ForYouCardStackDemo() },
    Block(slug = "gift-card-picker", name = "Gift Card Picker", category = "Lists", spec = "A gift flow that opens from a portfolio screen. Tapping the \"Choose your gift stock\" tile slides up a sheet where a soft colour cloud sits behind an iridescent \"Discover your gift amount\" headline. Discover amount collapses the cloud into a glassy sphere whose colours spin while the amount is found, then the sphere melts into a wider cloud showing USD 3. Choose a gift stock pushes a dark sheet in from the right: a grey skeleton, then a carousel of five stock cards with tilted neighbours, page dots, a two-line description and a white Choose button, while the whole backdrop takes on the colours of the card in the middle. Choosing a stock lifts its card, flips it over to a share certificate and flies it into the portfolio's gift tile, which bounces as it lands. The companies, their marks and all artwork are invented.") { GiftCardPickerDemo() },
    Block(slug = "memo-card-fan", name = "Memo Card Fan", category = "Lists", spec = "Two dark memo folders are staged vertically on a black screen: the first is closed around a red-lit portrait, while the second presents three white-framed portraits as a tactile fan above its pocket. Each folder preserves the pin's tabbed silhouette, compact metadata, count and note label; the original person's likeness is replaced by an invented portrait set with the same red, black and warm-brown colour masses.") { MemoCardFanDemo() },
    Block(slug = "menu-product-carousel", name = "Menu Product Carousel", category = "Lists", spec = "A cafe's menu as a carousel of dishes. On peach paper printed with topographic contour lines, under the cafe's lockup, one large brown card holds a dish (its name in a heavy rounded white face over a cut-out product photo) with the next and previous cards smaller at the screen's edges. The menu steps through coffee, burger, french fries, pizza, cold drink, pasta, taco and sandwich; then the row draws in and collapses into the centre, \"Don't wait\" appears with TAKE A / BITE sliding in from the left, everything leaves, and the lockup pops up large in the middle. Drag the row to browse the dishes yourself.") { MenuProductCarouselDemo() },
    Block(slug = "movie-card-list", name = "Movie Card List", category = "Lists", spec = "A cinema app's film picker. Three film cards on a white carousel: the centre card holds the poster, with the film's title lockup (cast name, title, tagline, date) on its key art across the top of the screen, and the title, three genre chips, a rating with stars, a page-dots mark and a BUY TICKET button under it; the neighbouring cards peek at the edges, washed white. Swipe between films or tap the card: the posters gather into a row at the top and a white sheet rises with the cast, three actor photos and an introduction. BUY TICKET turns into a seat map under a curved cinema screen showing the film: pick seats, a date and a time, and PAY.") { MovieCardListDemo() },
    Block(slug = "music-cover-carousel", name = "Music Cover Carousel", category = "Lists", spec = "A music player floating over a blurred amber room. Five album covers stand in a cover flow of frosted glass cards, each with its title and artist, the front one large and two on each side receding. Below sits a glass player bar: rewind, pause and forward, a dark now-playing capsule with the cover, title, artist, a progress line and a small pill-shaped now-playing mark, and buttons for lyrics, the queue and volume. Drag the flow or use the buttons to bring another album to the front; the room takes on its colours.") { MusicCoverCarouselDemo() },
    Block(slug = "planet-explorer-carousel", name = "Planet Explorer Carousel", category = "Lists", spec = "A playful astronomy browser places a low-poly Earth above a white information card, with neighbouring planets peeking from a deep blue orbital sky. A matching detail view enlarges the selected planet above a concise description, launch illustration and photographic video card.") { PlanetExplorerCarouselDemo() },
    Block(slug = "poster-glow-carousel", name = "Poster Glow Carousel", category = "Lists", spec = "A streaming app's front door. It opens on Who's watching: four round profiles on a violet, teal and magenta glow. Pick one and it dissolves into the home feed: a hero poster that bleeds into the dark background, its title, genres, star rating and a white play button, then row after row of horizontally scrolling posters: Now Playing, Continue Watching with red progress lines, tall Set The Mood cards, Trending, For You, New On FilmFlow, Games Based On Movies, Documentary, Coming Soon, Award Winners, Movie Night and Staff Recommend. A back arrow and a gear stay over the feed, a five-icon tab bar sits at the bottom.") { PosterGlowCarouselDemo() },
    Block(slug = "send-money-cards", name = "Send Money Cards", category = "Lists", spec = "A light wallet home: a black \"Send to\" pill wraps the Dynamic Island with three contact faces, round menu and add buttons sit beside it, an electric-blue card shows the balance, card number and Send to / Receive / Add actions, and a \"Last Transactions\" list of grey pill rows follows. Holding the card sinks it and grows a tab under the island with \"Drag to send\"; dragging it up sends it into the island, which swells like a drop into a black \"Send Money To\" sheet with favourite contacts, a contact list and a Next button. Swiping the sheet up folds it back into the island and the card rises into place.") { SendMoneyCardsDemo() },
    Block(slug = "stacked-colour-cards", name = "Stacked Colour Cards", category = "Lists", spec = "A friends list built as a signpost: seventeen thick, arrow-shaped boards in pastel and saturated colours are stacked up a pole from under the status bar to the bottom of the screen, on a background that runs from near-black green to deep blue. Each board carries a friend's name, some a distance, and points the way to that friend, so the post looks like a jumble of arrows at different angles. As the heading changes the whole post turns about its pole in 3D: boards swing from face-on to edge-on, their tops, ends and arrow points come into view, and the lettering foreshortens with its board.") { StackedColourCardsDemo() },
    Block(slug = "wallet-card-stack", name = "Wallet Card Stack", category = "Lists", spec = "A light wallet home: round menu and add buttons around the \"Wallet / My Cards & Transaction\" title, a purple leather wallet holding two lavender cards (the front one shows the holder, the last four digits, an invented network wordmark and the expiry) with the total balance, an Add Balance pill and swap and hide buttons on its pocket, a Quick Top-Up row of 3D avatars behind a dashed Add circle, three Latest Transactions tiles and a tab bar with a raised gradient scan button. Pulling the front card lifts it out of the pocket, letting go drops it home with a bounce and the leather gives; the eye button hides the balance digit by digit.") { WalletCardStackDemo() },
    Block(slug = "wallet-transactions", name = "Wallet Transactions", category = "Lists", spec = "A faithful personal-finance home with an invented wordmark, a large balance, Invest, Shared and Loans tiles, a dark action band, and a white Transactions sheet. The All, Recurring and Friends filters swap concise payment rows while preserving the pin's measured spacing, soft inset surfaces and compact app-style marks.") { WalletTransactionsDemo() },
    Block(slug = "weekend-mood-carousel", name = "Weekend Mood Carousel", category = "Lists", spec = "A weekend mood picker: a pastel panel holds a carousel of seven flat, blobby characters, each one a mood with its own colour and face, above the serif question \"Select your weekend mood\", a ruler of fading ticks with a tinted centre line, and a scrolling strip of pill chips. The selected chip fills with the mood's gradient, the panel and the ruler's centre line take the mood's colour, and the character plays its expression: Zzz, a drooling grin, a cross that turns red, flickering 3D glasses, a beating heart, tired eyes over a phone, fluttering butterflies.") { WeekendMoodCarouselDemo() },
    Block(slug = "widget-stamp-picker", name = "Widget Stamp Picker", category = "Lists", spec = "An onboarding screen that asks you to choose your starting widgets. Under a back button, a Skip pill, a door with three blob creatures peeking out and the two-line title, the widget packs stand as postage stamps on a curved wheel: the chosen stamp large in the middle, its neighbours smaller, higher and leaning outward at the screen's edges. Each stamp has a perforated edge, a pale tint of its colour, a coloured glow below, an illustration on a rounded panel and the pack's name (Organisation, Mixed, Games, Daily). Swipe sideways to roll the wheel to the next pack; a curved-arrow hint and a one-line caption sit underneath.") { WidgetStampPickerDemo() },
    Block(slug = "workout-stack-list", name = "Workout Stack List", category = "Lists", spec = "A fitness app's class browser: a deck of photo cards (Running, Acrobatics, Cardio, Aerobics, Yoga…) stacked in depth above a frosted tab bar. Swiping runs the deck forward; tapping a card grows it into a full-bleed hero with the week strip and the day's classes below. Scrolling tucks the live class behind the next card, pulling down opens the whole month with the classes stacked under it, and picking another day slides that day's classes in.") { WorkoutStackListDemo() },
    Block(slug = "badge-vault-grid", name = "Badge Vault Grid", category = "Lists", spec = "A dark, three-column vault of eighteen original enamel-and-silver achievement badges. Earned badges lift continuously from their sockets into a full-screen, colour-lit inspection view; locked badges show progress and gain liquid enamel when a day is logged.") { BadgeVaultGridDemo() },
    Block(slug = "glass-folder-burst", name = "Glass Folder Burst", category = "Lists", spec = "A playlist that lives in a glass folder. On a black screen a folder of thick smoked emerald glass stands under its title, with a glowing disc stored inside it, seen through the frosted front as a soft light. Tap the folder: it sinks to the bottom of the screen while its front leans open, the disc climbs out and flies up to become the mark of the list header, and the folder sprays the whole track list upward: rows shoot out of the mouth edge-on, tumbling inside a green bloom, in a column that leans right and curls back, and land one after another as a tidy list. Tap a row to make it the one playing. Tap the folder again and the rows are sucked back in, the nearest first, the disc drops in after them and the folder rises back to the middle. The front panel is real glass in the sense that matters on a screen: a shader bends and frosts whatever is drawn behind it, so the disc and the rows diving in show through it, displaced at the bevel.") { GlassFolderBurstDemo() },
    Block(slug = "origami-fold-list", name = "Origami Fold List", category = "Lists", spec = "A diver's logbook on a deep ink-blue screen: a coral \"Logbook · 2026\" eyebrow, the title \"Where the reef opens up\" and six dive sites in dark rounded rows, each with a square reef photo, the site's name and place, its depth large on the right with the water temperature under it, and a small chevron. Tapping a row unfolds its details under it like folded cream paper, three panels opening one after another with shadows that lift as they flatten: visibility, current and level; a strip of twelve months with the best ones marked in coral; and a wide aerial photo of the water with a line about getting there. The rows below are pushed down, only one site is open at a time, and dragging a row down opens its fold under the finger.") { OrigamiFoldListDemo() },
    Block(slug = "rubber-chain-list", name = "Rubber Chain List", category = "Lists", spec = "A dark list of twelve upcoming shows under \"Tonight & After\": each row is a rounded card with a square concert photo, the act's name, the venue and city, and a date chip on the right with the month in amber over the day. The rows hang together like a chain of springs: flung, they drift apart, each lagging a little more than the one before it, and catch up with a springy settle when the list slows; pulled past either end, the gaps open like a stretched spring. Tapping a row highlights it and opens it on a spring to show the door and show times, a line about the show, its price and an amber \"Tickets\" button.") { RubberChainListDemo() },
    Block(slug = "portrait-filmstrip", name = "Portrait Filmstrip", category = "Media", spec = "A photographic journal arranges cinematic portraits and landscapes in a narrow vertical filmstrip. The selected frame expands smoothly to the edges of the screen, then folds back into the reel before the next image arrives. Drag to explore the reel or tap to fill the screen.") { PortraitFilmstripDemo() },
    Block(slug = "luma-run-studio", name = "Luma Run Studio", category = "Media", spec = "An invented image editor turns a locally drawn canyon into directional pixel streaks inside a movable brightness window. Complete colors are reordered within contiguous eligible runs while dark islands stay sharp. Drag the artwork, adjust the luma range or direction, hold to compare the original, and keep a local edit.") { LumaRunStudioDemo() },
    Block(slug = "bubble-ring-recorder", name = "Bubble Ring Recorder", category = "Media", spec = "A dark voice recorder screen built around a glowing red record orb. A big thin timer (Barlow Condensed ExtraLight) sits top left with a caption, a three-line menu top right; the orb (#FF1F4B, \"RECORD\" set vertically inside) glows inside a faint circle, with three small glyphs under it and a list of three takes, the first showing the last take's waveform. Recording turns the orb into a pulsing red dot and the circle into a white outline that wobbles like a soap bubble with the voice, trailed by a grey ghost; the timer counts and the first row records live.") { BubbleRingRecorderDemo() },
    Block(slug = "camera-carousel-fan", name = "Camera Carousel Fan", category = "Media", spec = "A camera shelf on a near-black screen: a glossy 3D camera floats in the upper half under a soft spotlight tinted by the camera's colour, with eight white-framed instant photos orbiting it on a tilted ring, some passing in front of the lens and some behind. The five invented cameras (OKA 35 with an orange top plate and pearl lens, the leather RF-2 rangefinder, the red toy PIP, the olive MOSS 6 medium format and the silver HALF compact) are drawn in code from extruded rounded shapes with real perspective and shading, not loaded models. Under the camera sit its name in bold mono, a spec line naming its film, a strip of five camera thumbnails sliding under a fixed white outline, a hint and a round close button. Each camera has a film look, so the photos (flowers, a building, a portrait, a sunset, mountains, a plant, a night city, dunes, all drawn in code) turn warm, black-and-white, red, green or blue with it.") { CameraCarouselFanDemo() },
    Block(slug = "continuous-zoom-grid", name = "Continuous Zoom Grid", category = "Media", spec = "A photo library on a white screen that zooms continuously, like a pinch, from three large square photos per row to a contact sheet of twenty per row and back. Its 3,000 photos are drawn in code from their index (sun over the sea, hills in haze, city lights out of focus, dunes, pines in mist, petals close up, a building in low sun, a beach, in eight palettes, in runs like days out), so the grid needs no images. While zoomed out each month's first photo carries a white chip with its month, at full size videos show their length, and the grid dissolves into white under a header (a round back button, \"Library\" over the month in view, a Select pill) and above a floating glass control (Years, Months, All Photos) whose highlight follows the zoom.") { ContinuousZoomGridDemo() },
    Block(slug = "dot-matrix-camera-pad", name = "Dot Matrix Camera Pad", category = "Media", spec = "A manual camera screen whose controls feel like hardware, on black. A viewfinder with white corner brackets fills the top 62% and shows a night street drawn in code (city blocks with lit windows, three street lamps with bokeh and wet reflections, cars passing both ways) that answers every setting, with lens chips 13, 24 and 77 MM at its foot. Below it, two control modules with mono readouts: a rubbery drum wheel for exposure beside an A/M switch with an orange knob, and the same for warmth. Switching the first to M opens the wheel into a glowing 11 × 8 dot-matrix pad of shutter speeds (1/4 to 1/4000, across) by ISO (100 to 12800, up). A glossy orange-red shutter in a white ring, a gallery thumbnail and a round chevron button sit at the bottom. Exposure and ISO brighten or darken the street, slow shutters stretch the cars' lights into long trails, high ISO adds grain and warmth tints it.") { DotMatrixCameraPadDemo() },
    Block(slug = "filmstrip-arc-scrubber", name = "Filmstrip Arc Scrubber", category = "Media", spec = "A dark video player whose scrubber lifts into a curved 3D filmstrip of frames. The \"video\" fills the top 60% of the screen with rounded corners: a one-minute night drive drawn in code as a function of its time (golden hour turning to dusk and night, the sun setting and the moon rising, stars coming out, hills drifting past, lane dashes rushing at the camera, lamp posts lighting up, a car's tail lights ahead), with a title chip, an HD badge and a running timecode. Below it sit the title and a line about the episode, a thin progress bar with a round thumb and times, and back 10, play/pause and forward 10 buttons. Pressing the bar lifts a filmstrip of frames, each a film cell with sprocket holes showing the same drive at its own time, wrapped round a cylinder so the frames near the finger face the viewer, swell and sit under a white magnifier with the time above it, while those further away turn away, shrink and darken; the video scrubs live under it.") { FilmstripArcScrubberDemo() },
    Block(slug = "ink-gradient-song-card", name = "Ink Gradient Song Card", category = "Media", spec = "A \"make your first song\" sheet over a dimmed music app. The card's background is ink being stirred in water: burgundy, signal red and lilac clouds with sprayed, grainy edges that drift and trade places; on it sit a round close button, a large serif headline (\"Make your first song\", Instrument Serif), a short subtitle, three tilted prints with art drawn in code (a studio microphone, a record, a sunset) and a pale pink \"Let's make music\" footer button.") { InkGradientSongCardDemo() },
    Block(slug = "iridescent-cd-flip", name = "Iridescent CD Flip", category = "Media", spec = "A compact disc in a sci-fi HUD on a black, film-grained screen. A thin white frame with two chamfered corners holds the disc: its printed side is glossy black with warm light bands across the lower third, a fan of cold light streaks at the right, a gold mono \"MIRROR INDEX\" and red and green rings round a clear hub; its data side is mirror grey with diffraction rainbows that sweep round as it turns. Mono captions above and below the frame retype themselves in a glitch each time the disc flips. Under the frame sit the jewel case with the same art and a spine, the track list of the invented album \"Halation\", a small level meter, a laser read-out sweeping across a tick scale, and an outlined \"FLIP DISC\" pill. Drag the disc sideways to turn it with the finger, or tap it to flip it over.") { IridescentCdFlipDemo() },
    Block(slug = "light-table-loupe", name = "Light Table Loupe", category = "Media", spec = "A glowing light table of twelve 35 mm slides and a black loupe that magnifies whatever it is moved over. The table is a softly lit cool white panel (#EEF1F4 to #CFD6DD) under a black header reading \"CONTACT 04 · 12 FRAMES\"; the slides sit in a 3 × 4 grid of cardboard-white mounts with their frame number and \"OCT 84\" printed in a small mono, each holding a backlit transparency drawn as gradient art (harbor at dusk, wheat field, open sea, night street, desert road, glacier lake, northern lights, pink beach, alpine snow, tulip rows, city at dusk, fern forest) whose colour spills onto the table around it. The loupe (a 128 pt black housing with a chrome lip) shows the table 2.2 times larger under its glass, with grain, a vignette, colour fringes and a glass highlight, and it pulls focus as it lands on a slide; a tap circles a slide in red grease pencil. Below the grid a dark slide viewer projects the slide under the loupe on its 1.4 : 1 screen, with its frame number and title under it, next to the loupe's dashed home ring.") { LightTableLoupeDemo() },
    Block(slug = "mood-shape-mixer", name = "Mood Shape Mixer", category = "Media", spec = "A mood item expands into a compact floating feeling picker over five faint activity pills on warm paper. Its colored disc holds one white face that morphs through Melancholy, Tired, Bored, Calm, Happy, Super Happy and Awesome while a scrambled title resolves above a pale slider strip. Dismissing the picker and activities reveals a line-drawn desk, a blue window, a sleeping cat and a split-flap clock reading 13:14.") { MoodShapeMixerDemo() },
    Block(slug = "morphing-print-layout", name = "Morphing Print Layout", category = "Media", spec = "A film picker in which one white instant-print frame morphs between five formats: Single, Double, Triple, Four and Six. A white top strip holds the nav bar (\"Select Film\" with a small \"?\" badge) and a one-line pager of the format names, the selected one black and the others grey, with five dots; below it an orange stage (#F4B043 to #EE4D0F) shows the frame, its square wells filled with six summer photos by the sea, a caption for the format, an export button and a white \"Choose photos\" pill. Between formats the frame stretches and the wells split a new photo out from under their neighbour; on the way to Four the prints come loose as separate tilted instant photos and gather again into the grid.") { MorphingPrintLayoutDemo() },
    Block(slug = "particle-listening-ring", name = "Particle Listening Ring", category = "Media", spec = "A song search screen that listens: on a warm off-white background a ring of 112 coloured dots (coral, violet, teal and sun) breathes with the voice it hears, under the caption \"Hum, sing, or play the tune\". Loud moments swell the ring, grow the dots of the leading colour, drop a few dots into the middle and tint the space behind it; quiet moments thin it to specks with half the ring empty. A round back button sits top left and a white mic button with \"Hold anywhere to hum along\" at the bottom.") { ParticleListeningRingDemo() },
    Block(slug = "record-stack-deck", name = "Record Stack Deck", category = "Media", spec = "A record crate shown as a vertical 3D deck on a black screen. Ten invented albums with covers drawn in code (a striped sunset, a dot screen, giant lowercase type, a glowing orb, diagonal bands, a night sea, misregistered rings, a checkerboard, big numerals, a single circle) lie stacked as square sleeves 0.78 times the screen's width: the one at the focus, 42 % down the screen, is seen edge-on as a thin strip under a white ring, and the others open up in perspective the further they are from it, each titled in small type above its edge. The colour of the focused cover lights the screen from above and below, and a large caption sits at the bottom (\"Every album, pressed to vinyl.\"). Holding a record lifts it out of the deck, lays it flat and slides its vinyl half out of the sleeve, spinning with the cover as its label, while the caption becomes \"Now spinning\" and the album's title.") { RecordStackDeckDemo() },
    Block(slug = "shake-develop-polaroid", name = "Shake Develop Polaroid", category = "Media", spec = "A freshly ejected instant print that develops while you shake it. A dark aubergine viewer (#1F161C) with \"Today · 10:10 AM\" between round back and more buttons; in the middle a warm white instant film (80% of the width, up to 330 pt, square photo, thick bottom margin) that starts as a flat, milky, almost blank grey and gains colour, contrast and detail, its haze lifting from the bottom up, until a turquoise mountain lake at sunrise stands out in full. Under it a phone glyph with \"Shake to develop\" and a thin mint progress bar turn into a check and \"Developed\"; a bottom bar holds share, the camera roll as a small framed thumbnail, and trash.") { ShakeDevelopPolaroidDemo() },
    Block(slug = "spatial-orbit-mixer", name = "Spatial Orbit Mixer", category = "Media", spec = "A spatial-audio mixer: five instruments float as glowing orbs on three perspective rings round a listener seen from behind, wearing over-ear headphones. On deep indigo-black with star dust, the floor is drawn from 40° above with hairline rings, bearing ticks and two dashed arches; each orb (Vocals lime, Keys violet, Guitar amber, Drums coral, Bass cyan) is a lit sphere with a white pictogram, a halo, a comet tail, a stem to the floor and a faint wedge of light towards the head. Above: \"Spatial Mix\" and \"Head tracking on\"; below: a Stereo / Spatial / Fixed segmented control, five level bars, a play button and the track. Everything is drawn in code.") { SpatialOrbitMixerDemo() },
    Block(slug = "tape-reel-physics", name = "Tape Reel Physics", category = "Media", spec = "A cassette deck whose tape behaves like real tape. On dark walnut, a big cream cassette fills the width: a label with a red-and-amber band, side A, \"Night Drive Mix\" in a marker hand and C60; a black glass window with two brown tape packs on white six-toothed hubs; and the tape itself, running from each pack round two steel guides and straight across the head opening. Under it six transport keys (rewind, play, fast forward, pause, stop, record), two backlit VU meters, a rolling four-digit counter, and the tape's time and progress. Everything is drawn in code.") { TapeReelPhysicsDemo() },
    Block(slug = "tape-shelf-player", name = "Tape Shelf Player", category = "Media", spec = "A library of home-video tapes under a retro player, on a warm off-white page. A light grey shelf band at the top carries the player: a dark rounded box with a curved-glass CRT, a cassette slot, an LED and three small buttons. Below a \"Collections\" heading sits a three-by-three grid of VHS sleeves in red, cream, navy, violet, black, lime, orange, teal and tan, each with an invented brand in condensed type, a rainbow band and a white sticker with a handwritten title (\"Summer '98\", \"Lake house\", \"Sunset pier\"…). A magenta \"Play something old\" pill floats at the bottom. Picking a tape slides its cassette out of the sleeve and flies it into the slot; the CRT powers on with a home video drawn in code (a sky and a sun over water, glints, a pier, a rolling tracking band, the camcorder's PLAY and date stamp) and a black transport bar with eject, rewind, pause, fast-forward and shuffle replaces the pill.") { TapeShelfPlayerDemo() },
    Block(slug = "torn-photo-delete", name = "Torn Photo Delete", category = "Media", spec = "A day's instant photo that you delete by tearing it in two. A pale page (#EFEFF1) with a soft pink glow behind a pink camera button at the lower right, a trash glyph and \"Selected Day\" over \"Thursday, 2 July\" at the top, and in the middle a cream print (#F7EEDD to #EFE3CC, 85% of the width up to 340 pt, corner 3 pt, soft shadow) holding a 5:6 photo of a desert road with a faint glare and the date \"02/07/2026\" in a mono face in its thick bottom margin. Dragging across the print rips it along a jagged line from the nearest edge, the two flaps opening into a wedge that shows the white paper core; let go early and it heals, go most of the way and the halves fall away, a dark \"Photo deleted · Undo\" toast rises and \"Nothing kept for this day\" takes the print's place until Undo brings it back.") { TornPhotoDeleteDemo() },
    Block(slug = "vinyl-swap-scratch", name = "Vinyl Swap Scratch", category = "Media", spec = "A turntable \"now playing\" screen seen from above, recoloured by the record on the platter. A black record 1.12 times the screen's width is cropped by the left edge (centre at 29 % across, 35.5 % down), with fine grooves, two track gaps, a gloss that stays fixed to the light and a label drawn in code: \"Slow Satellites\" by The Amber Rooms (a saffron sunburst with a rust sun) or \"Glass Harbor\" by Noa Lind (cream with teal rings and a coral dot). The background is the label's colour turned into a blurred wash (ochre fading to near-black for one album, teal for the other), and a chrome tonearm with a counterweight and a black headshell pivots on a round base at the top right. Under the record sit a waveform strip (rounded, translucent black, bars that scroll past a white playhead, kicks in the album's accent), the title in 24 pt semibold with the artist under it and a \"33⅓ RPM\" tag, and three dark pills with mono captions: pause, previous and next. A finger on the record scratches it: the platter stops, follows the finger and scrubs the waveform.") { VinylSwapScratchDemo() },
    Block(slug = "watercolor-voice-orbs", name = "Watercolor Voice Orbs", category = "Media", spec = "A voice picker on a black screen: under \"Choose a voice\", a large orb painted as a living watercolour with a soft glow of its colour, the voice's name and line, a pager of four dots and a white \"Continue\" pill. Each voice has its own palette and cloud pattern (Lagoon blue, Dune terracotta, Moss green, Dusk violet); swiping makes the clouds flow into the next voice's pattern while its colours seep in through them, and the orb gives, bounces and pulses as the new voice speaks a short preview.") { WatercolorVoiceOrbsDemo() },
    Block(slug = "wave-scrub-slider", name = "Wave Scrub Slider", category = "Media", spec = "A photo editor's contrast screen whose slider is a living wave. A dusk lake drawn in code fills the top 60 % of the screen; a near-black panel (#0E0E0E, top corners 24) rises over its foot with an orange (#F39A1C) toolbar (back, undo, redo, more, SHARE), a strip of seven line-icon tools with Contrast selected on a dark square, a card (#161616, corners 18) with a fading perforated grille, the label CONTRAST and the value (0 … +100), and a bottom bar of five tools. The slider is a single line: an orange sine wave with a soft glow left of the thumb, a faint grey ripple right of it, both meeting the centre line at a 14 × 42 pill thumb; the photo's contrast and saturation follow the value live.") { WaveScrubSliderDemo() },
    Block(slug = "bubble-media-burst", name = "Bubble Media Burst", category = "Media", spec = "A media \"add\" screen on light grey: a heading, a one-line hint and a round lilac \"+\" button. Pressing \"+\" opens a cluster of five photos in glass bubbles (a large portrait, three middle ones and a tiny one) that are born behind the button, swirl up along curved paths to their places with a springy overshoot and float there, while the \"+\" turns into an \"×\". Each bubble looks like a glass sphere: a darkened rim, a crescent of light at the top left with a glint, a coloured reflection along the bottom and a soft shadow; tapping one picks it (it swells slightly and gets a white ring and a check), and pressing \"×\" drops the bubbles back into the button one after the other.") { BubbleMediaBurstDemo() },
    Block(slug = "film-box-unboxing", name = "Film Box Unboxing", category = "Media", spec = "A daily filter reward on a black camera screen, in a monospaced face. A yellow slide-to-act pill opens a cardboard film box drawn in perspective: its flaps swing open, light streaks across it and the view dives into it, and the filter's canister comes out turning about its axis above its name, description and four details, with an expiry that counts down. Load film flies the canister to the top of a camera; the shutter flashes and lays the filter's tint over the photo, with Save, Retake and Share.") { FilmBoxUnboxingDemo() },
    Block(slug = "glow-file-uploader", name = "Glow File Uploader", category = "Media", spec = "A dark file-upload screen: a large two-line title fading from dim to light grey, a drop zone lit from inside by a soft white glow along its edges (brightest at the bottom) over faint diagonal hairlines, with a paperclip badge, \"Add files to upload\", \"or browse, 4 MB max\" and a \"Select files\" pill, then a list of up to three files and Cancel / Continue at the bottom. Each file row shows its upload as a filling ring and a lighter fill sweeping across the row; a finished file gets a green check, a failed one an \"Upload failed\" pill and a Retry button, and Continue lights up once every file is through.") { GlowFileUploaderDemo() },
    Block(slug = "scatter-grid-album", name = "Scatter Grid Album", category = "Media", spec = "A photo album screen that folds between two layouts. Open: eight photos (132 × 176 pt, corner radius 18, soft shadows) lie scattered in two loose columns down the screen, each tilted by 1.5° to 5.5° and overlapping its neighbours, the one in the middle tucked behind the others, over a pale gradient that fills the screen (base #F4F7FA, a blue light #B2C6DE upper left and a mint light #C3E0CF right of middle); the album's name \"Highlands\" is set large (52 pt heavy, white, tracking −1) at the top with its year \"2025\" small above it, partly behind the photos. Folded: the gradient becomes a square card (20 pt in from each side, centred at 46% of the screen height, corner radius 15) on a white screen, the photos straighten into a 3×3 grid on it (equal columns with 16 pt gaps, 12 pt row gaps, a taller middle row), the middle cell leaves the gradient showing the name, now shrunk to fit the cell, with the year under it, and a row of four grey line icons sits under the card: share, heart, info, trash. Tap the collage to fold, the card to unfold; the heart fills red (#FF4D6A) with a pop and a ring of six dots, and a second tap empties it; the other icons shrink while pressed. Photos are remote and preloaded; the demo plays it full screen with autoPlay.") { ScatterGridAlbumDemo() },
    Block(slug = "cover-flow-vinyl", name = "Cover Flow Vinyl", category = "Media", spec = "A cover flow of ten album covers on a dark floor. The cover in front faces you; the others stand on each side turned towards it in perspective, overlapping, smaller and darker the further out they are, and every cover is reflected in the floor, fading away below it. The album's title and artist sit under the floor and a header reads \"Crate\" with the number of records. Tapping the front cover slides its black vinyl record out to the right while the cover lifts and the other covers fade away: the record spins, its grooves catching a still light, its label printed with the cover, and a small player with a progress line, elapsed and remaining time and back, pause and forward buttons fades in under the title. Tapping again slides the record back into its sleeve.") { CoverFlowVinylDemo() },
    Block(slug = "cube-story-viewer", name = "Cube Story Viewer", category = "Media", spec = "Full-screen photo stories from three people, each on a face of a cube. A person's photos play one after another under a row of thin progress bars, with their round avatar, name, how long ago they posted and where, and a numbered caption in large bold type over the bottom of the photo above a \"Reply to …\" field with heart and send icons. Swiping sideways turns the cube to the next or previous person: the faces swing in true perspective about their shared edge and the face turning away darkens. Tapping the right side of a photo shows the next one, the left side the one before, and holding a photo pauses it and fades everything but the photo away.") { CubeStoryViewerDemo() },
    Block(slug = "film-strip-reel", name = "Film Strip Reel", category = "Media", spec = "A strip of 35mm film crossing a dark light table at a slight slant, its twenty-four frames shot between the skatepark and the beach. The film is drawn: a dark base with eight perforations per frame along both edges, warm light showing through them, frame numbers and \"▸ 12A\" by the perforations above and \"NC 400T 5207 07\" along the bottom, all printed in orange. A pool of warm light and a thin loupe ring sit in the middle, where the frame under the loupe stands slightly larger while the frames further out fall into the dark. Tapping that frame lifts it out of the strip into a white-bordered print with a burnt-in orange date stamp and a caption (\"Drop In\", \"Indoor ramp, Unit 9\", \"13A / 07\"), the strip dimming and shrinking back behind it. Small tracked capitals read \"Roll 07 — Coastline\" and the frame count at the top, and how to use it at the bottom.") { FilmStripReelDemo() },
    Block(slug = "flipbook-scrub", name = "Flipbook Scrub", category = "Media", spec = "A thick flipbook lying on a dark wooden table, bound along its top edge under a stitched cloth tape, with a photo of a dancer or a runner printed on each of its twenty-four cream leaves and a serif caption and page number under each print; the edges of the leaves under the top one show as a block of hairlines along its bottom. Dragging up thumbs the leaves over: each curls up from its bottom-right corner along a rolled fold, showing its lighter back with the print faintly mirrored through it and throwing a shadow on the leaf it uncovers, rolls over the binding and folds away behind the book. Fast, several leaves are in the air at once and the photos run like a film. Above the book \"Motion Studies\" sits over the chapter in a semibold italic serif (\"The Dancers\", \"The Runners\"), and a large semibold counter on the right rolls like an odometer as the leaves go by.") { FlipbookScrubDemo() },
    Block(slug = "ink-bleed-reveal", name = "Ink Bleed Reveal", category = "Media", spec = "A sheet of warm, grainy paper with a large print area marked only by four crop marks, a tracked-capitals \"Field Journal\" header and a caption below in a sturdy book serif with a bold italic title. A glossy bead of ink hangs over the paper, falls and splashes a ring of droplets, and the next photo of a lake or waterfall bleeds into the print through an organic ink stain: a blue-black front that blooms out the instant the drop lands, with soft lobes, blotches and a feathery fringe, dark and wet at its edge, with the photo coming through behind it in a mottle. The print keeps a ragged watercolour edge with a thin darker line, each photo's caption rises in once its ink lands, and at the end of the loop the prints dry back to paper in blotches.") { InkBleedRevealDemo() },
    Block(slug = "loupe-magnifier", name = "Loupe Magnifier", category = "Media", spec = "A large photo of a cable-stayed bridge fills the screen, slightly dimmed, with a round magnifying loupe over it. Inside the glass the photo is enlarged 2.5 times through a curved lens: it bulges towards the middle, its colours split into fringes near the thick brushed-metal rim, the edge darkens, and a soft gloss and a glint sit on the glass. A small dark tab on the rim reads the zoom, the loupe casts a soft shadow, and the bridge's name and a line of small print sit at the bottom. The loupe trails the finger on a spring, a pinch changes the zoom, a tap on the glass looks closer and a tap elsewhere sends the loupe there on an arc.") { LoupeMagnifierDemo() },
    Block(slug = "orbit-photo-ring", name = "Orbit Photo Ring", category = "Media", spec = "A retro camera hangs in the dark, drawn in true perspective: a body in pebbled leather between chrome plates, a prism hump with knobs on top and a deep ribbed lens with tinted glass. Ten polaroid prints (white cards with a slightly tall photo, a pencil caption and a small ring mark) orbit it, the ones behind the camera smaller, darker and blurred. A switcher at the top offers three ring styles that morph into each other: Ring, a wide tilted halo around the camera at rest; Tumble, where the camera becomes a soft, glossy toy-like body ray-marched in 3D (a lacquered shell with a carry hump and two dark knobs over a satin body with a pale base, a deep knurled lens holding a matte white sphere, an accent dot and a small tab) that turns round together with a wide ring of polaroids, the front of both travelling left to right; the ring hangs low and is rolled so its left side sits lower than its right, its front prints sweeping across the lens and its back ones passing small under the body, every print leaning with it; and Gyro, two crossed rings of five spinning against each other. Under the scene sit the model's name and a line of specs, and at the bottom a bar of camera thumbnails that scrolls freely, the chosen one in colour: scrolling only browses, tapping a thumbnail chooses it. Dragging sideways spins the prints and turns the camera with them; choosing another camera spins the body as it morphs into the new model while the prints fly off and new ones are shot out of the lens.") { OrbitPhotoRingDemo() },
    Block(slug = "photo-vortex-morph", name = "Photo Vortex Morph", category = "Media", spec = "Forty small photos (fashion editorials, film stills, gallery rooms and interiors) on an off-white sheet that morph between five layouts, every card travelling on its own spring a beat after its neighbour and tumbling a little on the way. They open as a vortex: a ring of overlapping portrait cards, each turned past its spoke like the petals of a flower around a small hole, turning slowly. Then they burst into a drift of little cards floating in depth, near ones larger, the whole field turning slowly; gather into a single neat stack in the middle; fan into a horizontal strip of thin slivers with the last card open in full; and settle into a five-by-eight grid laid edge to edge over the whole screen. Small tracked capitals at the top read \"Kinetic Archive\" and the layout's number, \"01 / 05\"; the layout's name and a line about it sit at the bottom left with \"Tap to morph\" at the right, all set in white with a difference blend so they read dark on paper and light on photos.") { PhotoVortexMorphDemo() },
    Block(slug = "scatter-collage-hero", name = "Scatter Collage Hero", category = "Media", spec = "An airy collage for a meditation library: two dozen photos of different sizes float on an off-white page with lots of space between them, small and faint near the middle and larger towards the edges, as if the whole field were drifting slowly towards you and up past the top. A serif wordmark, \"Stillhour\", and a line under it sit top left beside a round avatar, and a row of chips (All, Meditation, Yoga, Breath, Sleep) along the bottom dims the photos outside the chosen one. Tapping a photo flies it out of the collage into a full-screen hero: the photo fills the screen, its guide's name, a two-line serif title such as \"Salt / Balance\" with the second line in italic and a line about it rise in, with the time and date either side of a pale green Start pill and a strip of four thumbnails along the bottom. Swiping sideways pushes in the next hero, and dragging down or tapping the chevron puts the photo back in its place in the collage.") { ScatterCollageHeroDemo() },
    Block(slug = "water-ripple-photo", name = "Water Ripple Photo", category = "Media", spec = "A full-screen photo of lavender fields and cherry blossom that behaves like the surface of a pond. Touching it sends rings of ripples across the picture that bend the image and catch the light in thin bright lines, dragging leaves a trail of them, and a finger resting on the water keeps them coming. Swiping up sends a big swell out from the finger whose front carries in the next photo, while a small \"Still water\" header, a page count and the photo's place and title sit over soft dark scrims.") { WaterRipplePhotoDemo() },
    Block(slug = "waveform-scrubber", name = "Waveform Scrubber", category = "Media", spec = "A night-drive music player over a blurred photo of a neon-lit street: a square cover card, the title \"Afterglow Avenue\" by Juno Vale, and a waveform of sixty rounded bars with the elapsed and remaining time under it, above rewind, play/pause and fast-forward buttons. Dragging across the waveform scrubs it: the bars under the finger swell and brighten like a loupe sliding along the track, the played bars fill with a peach-to-pink gradient, and a white bubble rides above the tallest bar with the time under the finger. Letting go snaps the playhead to the start of a bar, the play button morphs between play and pause, and while the track plays the bars sway and throb to the beat.") { WaveformScrubberDemo() },
    Block(slug = "pit-stop-review", name = "Pit Stop Review", category = "Modals", spec = "A racing dashboard pairs a Blender-rendered race car with bold capsule cards, a Liquid Glass tab bar and a real review composer. Tap Write a review and the car comes into the pit box; five start lights become the composer's rating stars. Choose a rating, write an optional note and share it through the system sheet; local race notes, saved weekends and a reflex test complete the screen.") { PitStopReviewDemo() },
    Block(slug = "banner-grow-card", name = "Banner Grow Card", category = "Modals", spec = "A dark onboarding screen with a line-art phone outline. A real notification (app icon, title, body) slides into the outline, warms to amber, then grows into a full photo card of peaks above a sea of cloud, clipped by the outline, with a 'Morning sit' caption and a play button, while the headline and the button stay put.") { BannerGrowCardDemo() },
    Block(slug = "blur-backdrop-composer", name = "Blur Backdrop Composer", category = "Modals", spec = "A trips page (avatar, search, a welcome card on a dusk photo, a tilted collage of three travel photos, a Create a Trip button and a tab bar). The button raises a full-screen composer over a blurred travel photo that changes on every opening: a large name field with a caret, three frosted cards with icons (itinerary dates, timezone, cover image) and a drawn keyboard with suggestions and key callouts, whose keys work by touch, so the system keyboard never opens.") { BlurBackdropComposerDemo() },
    Block(slug = "crystal-trophy-reveal", name = "Crystal Trophy Reveal", category = "Modals", spec = "An achievement overlay staged like a theatre: a closed curtain of royal-blue velvet with a blade of light at its seam parts on a spot-lit stage, where a clear crystal trophy, a thick faceted slab engraved with the number 30, stands in an octagonal plinth of white marble. Above it a heavy tilted headline reads PERFECT MONTH with the date it was won; below are two lines of copy, a Share bar of smoked crystal and a small crystal close button. The crystal and the plinth are ray-traced on every frame: the crystal refracts the actual stage behind it, splits light into thin colour fringes, carries its frosted engraving inside and throws flecks of spectrum onto the velvet.") { CrystalTrophyRevealDemo() },
    Block(slug = "emoji-rating-popup", name = "Emoji Rating Popup", category = "Modals", spec = "A travel feed (stories row, posts with avatars, text, photos and like counts) with a Rate the app button that opens a rating dialog. The glossy emoji in its header, drawn with gradients, a highlight and blush, changes with the stars from a worried frown to heart eyes, while the layered wave behind it shifts from red through yellow to green; a comment box and Cancel and Submit buttons follow. Submit sends the dialog away in a burst of hearts.") { EmojiRatingPopupDemo() },
    Block(slug = "grow-delete-dialog", name = "Grow Delete Dialog", category = "Modals", spec = "A Files screen (storage card with a segmented usage bar and legend, a list of recent files with type tiles or a photo thumbnail, size and last edit, and a tab bar) with a trash button on each row. The button grows into a confirmation dialog: it starts as the button's own rounded square, measured on screen, and spreads to the centre while its content pops in. Confirm turns the dialog into its success version and closing it collapses the deleted row; Cancel folds the dialog back into the button.") { GrowDeleteDialogDemo() },
    Block(slug = "island-alert-pill", name = "Island Alert Pill", category = "Modals", spec = "A Batteries page under a dynamic-island pill that shows a low battery: a widget of four battery rings with device icons and a grouped list of six devices (icon tile, name, status, percent and a small battery glyph), the phone's numbers following the island's charge. An alert grows the pill into a wide island with a track, a glowing knob that carries the percent and the time left; the knob can be dragged to preview a charge and springs back.") { IslandAlertPillDemo() },
    Block(slug = "island-toast-stack", name = "Island Toast Stack", category = "Modals", spec = "An original Native Cook design on a dark lock screen: a deep ink wallpaper with wide, soft pools of cobalt, plum and teal, and a date, a big white rounded 9:41 and a hint line at the bottom. A black pill sits exactly over the Dynamic Island (126 × 37 pt; just under the notch on older iPhones; Android keeps its status bar and shows the pill just under it only while something grows out of it) and morphs into live toasts: an incoming call from Theo Marsh with red and green round buttons, a message from Rafael Ortiz, an upload of 24 photos to \"Lisbon, spring\" with a blue progress ring, and a \"Sourdough proof\" kitchen timer in large orange rounded digits. Each toast is the island grown to the screen width minus 20 pt and 99 pt tall with continuous corners. After a moment it drops out of the island as a black card into a stack below, joined by a gooey neck that thins and snaps, and clears into the system’s notification material: the wallpaper seen through the card under a grey tint, with older cards peeking out as narrower, darker bottom edges. Each card reads like an iOS notification: a 38 pt icon (an app squircle, or the contact’s photo with an app badge), a semibold title with \"now\", and a line or two: \"Missed call · mobile\", the message, \"Uploading 16 of 24 photos\", the timer’s orange countdown \"left · Kitchen\". Tapping the stack opens it into a list under a \"Notifications\" header with a Show less pill and a round ✕ that clears it; a card swiped sideways is thrown away. Tapping the island brings the next toast, pulling it down (also from just under it, out of reach of the system’s top-edge swipe) opens the timer as a big card with Pause and +5 min that pushes the stack down, and clearing draws every card back up into the island while it gulps each one.") { IslandToastStackDemo() },
    Block(slug = "level-up-takeover", name = "Level Up Takeover", category = "Modals", spec = "A full-screen level-up celebration on a warm cream gradient. A glossy gold hexagon badge in a white bezel bursts out of a small dot with confetti in front of a slowly turning sunburst, then the heading, a line of praise and a frosted card with two counted figures follow, and a gradient Continue button and a share row slide up; after a pause everything fades back to the dot.") { LevelUpTakeoverDemo() },
    Block(slug = "payment-check-burst", name = "Payment Check Burst", category = "Modals", spec = "A payment-success screen on a soft grey page. A big glossy green check pops with ripples and green confetti and its tick draws on, then it shrinks to the top above 'Payment Complete' while a paper receipt (rounded top, side punches, dashed tear line, torn teeth at the foot, soft shadow) slides up with its amount counting in large figures and its rows of details; a brushed-silver 'Peel to claim your reward' bar then peels back to reveal +400 points while silver coins spill.") { PaymentCheckBurstDemo() },
    Block(slug = "stacking-toast-feed", name = "Stacking Toast Feed", category = "Modals", spec = "A travel shop page (greeting, Explore title, cart with a badge, search, a featured balloon-ride photo card and a list of experiences with photos, ratings and prices, over faint topographic lines) that collects toasts. Each toast (error, warning, info, success: a tinted band with an outline icon, a bold title, a body with an underlined link and an x) slides in from above with a short shake and pushes the earlier ones down; the pile can collapse into a depth stack, and toasts leave by a sideways swipe or their x. Every position comes from a toast's place in the list.") { StackingToastFeedDemo() },
    Block(slug = "streak-flame-takeover", name = "Streak Flame Takeover", category = "Modals", spec = "A dark streak-celebration screen. A gold coin spins, pops into a flame mascot drawn in Skia (a glossy three-tipped gold flame round a hot orange character in cream-lensed shades, with a waving arm and a sparkle) in front of a warm glow, gold wings flap once, the large rounded day count rolls up by one with a glow, and a 'This week' card fills its bar while the chunky share button and the continue link slide up.") { StreakFlameTakeoverDemo() },
    Block(slug = "task-toast-confetti", name = "Task Toast Confetti", category = "Modals", spec = "A bold blue 'Today' screen with three tasks. Ticking the first strikes it through, drops a springy orange toast from the top that bursts into confetti over the page, and a big speech bubble pops with the next hint beside a tomato-red mascot.") { TaskToastConfettiDemo() },
    Block(slug = "taste-profile", name = "Taste Profile", category = "Navigation", spec = "A social profile screen with a taste summary: a portrait capsule, follower counts, a rank coin and a streak gem, city chips and four stat tiles (favorites, recommend, okay, disliked) above a photo strip. Picking a city re-scopes the profile to that city like a split-flap departure board; the photo strip swipes as a 3D cover-flow, and holding a stat tile opens a six-month bar chart for the city.") { TasteProfileDemo() },
    Block(slug = "bubble-tab-bar", name = "Bubble Tab Bar", category = "Navigation", spec = "A white bottom tab bar on a dark screen whose active tab rises out of the bar as a round bubble, sitting in a bite cut from the bar's top edge. Changing tabs closes the bite, glides the bubble to the new tab with a slight overshoot and opens the bite under it again a moment later, so the bar behaves like a liquid; the icons cross-fade between the bar and the bubble, and the page above cross-fades its heading.") { BubbleTabBarDemo() },
    Block(slug = "account-scrub-tab-bar", name = "Account Scrub Tab Bar", category = "Navigation", spec = "A dark mail screen with a floating tab bar whose last item is a round account badge. Pressing and holding the badge turns the whole bar into an account switcher: the four icons blur away, the addresses stand in a wheel beside the badge, and dragging up or down scrubs through the accounts and \"All accounts\" while the inbox behind follows. Letting go keeps the account under the slot and brings the icons back; a plain tap on the badge steps to the next account, and the icons change tab.") { AccountScrubTabBarDemo() },
    Block(slug = "action-grid-tab-bar", name = "Action Grid Tab Bar", category = "Navigation", spec = "A page with a floating capsule tab bar (Home, Inbox, Alerts, Apps) and a round plus button beside it, in a light and a dark theme. The highlight behind the selected icon slides to a new tab stretched, its front end leaving first, while the page's title cross-fades and its cards slide. The plus turns into a cross and the bar itself stretches upward into a panel with a grid of eleven actions (Trim, Crop, Enhance, Text and so on); pressing an action, the cross or the page shrinks it back into the bar.") { ActionGridTabBarDemo() },
    Block(slug = "chip-morph-menu", name = "Chip Morph Menu", category = "Navigation", spec = "A light community page: a \"Live now\" capsule and two round buttons, a line saying who came online, a row of category chips (a filter chip, then \"Career\", \"Wellness\", \"Travel\", \"Money\", each with a glyph and a chevron), \"For your first chat\" over a row of profile cards with round portraits, \"Member Takes\" over a row of photos, and a floating \"Home / Chats\" capsule. Tapping a chip does not drop a menu under it: the chip itself swells into a white card in the middle of the screen over the darkened page, its glyph and label travelling to become the card's title, with a members line and four topic capsules arriving one after another. A tap outside, or a topic, sends the card back into its chip; a picked topic turns the chip dark and changes the heading and the profile cards.") { ChipMorphMenuDemo() },
    Block(slug = "circle-reveal-menu", name = "Circle Reveal Menu", category = "Navigation", spec = "A white studio page with a menu button at its top right, and a full-screen dark green menu that grows out of that button as a circle. While the circle spreads, the button's three lines turn into a cross and the logo turns white as the edge passes it; the four large items then rise in one after another above a strip with two actions. Choosing an item turns it white and closes the menu, the circle shrinking back into the button, onto that section's page.") { CircleRevealMenuDemo() },
    Block(slug = "collapsing-player-header", name = "Collapsing Player Header", category = "Navigation", spec = "A near-black podcast screen made of type. Its top is a full player: \"Yesterday\", the show's name, a large three-line title, a thin progress track with the elapsed and remaining time, and a transport row (bookmark, back 15, a round pause button, forward 15, play on another device); under it \"Episode Notes\" and the notes run off the bottom. Scrolling the notes folds the player into a one-line mini player that stays as the header: the title leaves upward, the track travels up and narrows, a yellow cover grows in at its left and the pause button shrinks to its right, while two small tabs (\"Description\", \"Links\") appear over the notes. Every piece is placed from one number, the scroll offset.") { CollapsingPlayerHeaderDemo() },
    Block(slug = "depth-side-drawer", name = "Depth Side Drawer", category = "Navigation", spec = "A light shop screen (top bar, search field, three shelves of coloured product tiles and a four-tab bar) over a violet side menu that fills the screen underneath: a round portrait with \"Mara Ellis\" and \"Portland\", seven destinations with line icons, and \"Logout\". Opening the menu swings the page aside as a rounded card, scaled down and turned about its left edge like a door, with two faint cards trailing behind it, while the menu's rows slide in one after another. Choosing a row marks it, changes the page behind the menu and closes the drawer; the page can also be dragged open from its left edge and dragged or tapped shut.") { DepthSideDrawerDemo() },
    Block(slug = "dot-icon-tab-bar", name = "Dot Icon Tab Bar", category = "Navigation", spec = "A light grey screen with a floating pill tab bar of three outlined icons drawn by hand: a house, a picture and a gear. Selecting a tab thickens and darkens its icon and brings a blue-violet dot into it in the icon's own way: the dot drops into the house and bounces, the picture rocks while its small circle fills and grows, and the gear turns while its centre ring fills. The title and the placeholder page above (\"Home\" with two cards, \"Photos\" with a grid, \"Settings\" with rows) cross-fade to the tab's own.") { DotIconTabBarDemo() },
    Block(slug = "editorial-menu-morph", name = "Editorial Menu Morph", category = "Navigation", spec = "A museum's site, \"Orsel, Museum of Form\", on warm paper: a spaced serif wordmark, a two-line hamburger with a small \"Menu\" label, a section kicker with a \"01 / 05\" index, a two-line Iowan Old Style headline (the system serif on Android), a large hero photo with an italic caption and a \"Plan a visit\" link. Tapping the hamburger crosses its lines and rolls \"Menu\" to \"Close\" while a near-black curtain comes down with a soft, bowed leading edge, the page under it sinking, shrinking slightly and darkening, and five large serif words (Exhibitions, Collection, Architecture, Visit, Journal), each with a small italic number and a small count (12, 4,120, 1911, 10–18, Nº 12), rise letter by letter out of clipped baselines over an opening-hours footer. Running a finger down the words dims all but the one under it, which turns italic, steps right and draws a thin rule under itself; a round photo in a thin paper ring floats beside the finger, chasing it with a lag and leaning into its motion, and wipes up to each word's photo (sculptures and spiral staircases) with a band of colour on the wipe's edge, while the menu turns to that word's colour: oxblood, prussian blue, ochre, verdigris, olive. Lifting on a word flies the photo on a spring into the new page's hero, the circle opening into the hero's rectangle as its ring thins away, as the curtain lifts away above the new page; the card becomes the hero and the page's kicker, headline lines and caption write themselves in as the index rolls to the new number.") { EditorialMenuMorphDemo() },
    Block(slug = "holo-agenda-carousel", name = "Holo Agenda Carousel", category = "Navigation", spec = "A conference agenda on pure black whose sessions are a carousel of four square foil tiles: WELCOME, 2ND DAY, EXPERIENCE and KEYNOTE. The centre tile is large and in front, its neighbours smaller and tucked half behind it, and inside every tile a vivid gradient is alive: rings are born at a point and grow away from it into a funnel, a tilted ellipse or a dome, or slide down as bands. Each tile has a lit top edge and a darker underside, glows onto the page and is mirrored faintly in the floor; under the row are pager dots, the selected session's time, title, description and speaker, and an \"Add to agenda\" button whose plus, rim, pager capsule and speaker disc are cut from the same material. The gradients are a fragment shader, not images, and the carousel is a pager you drag with a finger; it wraps round endlessly.") { HoloAgendaCarouselDemo() },
    Block(slug = "hopping-dot-tab-bar", name = "Hopping Dot Tab Bar", category = "Navigation", spec = "A white tab bar on a saturated blue screen whose indicator is a white dot resting in a notch of the bar's top edge, above the open tab. Choosing a tab makes the dot hop there on a parabola, low for a neighbour and well above the bar for the far jump, while the notch it left closes and a new one opens under it as it lands. Four line icons (home, messages, saved, profile) take the active colour and rise a little when chosen, and the page above, a title over placeholder cards, changes with the tab.") { HoppingDotTabBarDemo() },
    Block(slug = "liquid-action-pill", name = "Liquid Action Pill", category = "Navigation", spec = "A two-tab bar whose top edge dips into a bowl that holds a round plus button. Pressing the button throws it out of the bowl, which flattens behind it, and stretches it into a pill of four actions: the plus shrinks into a white dot that divides into four, joined by necks that thin and snap, and each dot turns into an icon. The cross, an action or a touch on the page runs it back, and the two tabs cross-fade a Home and a Profile page of placeholder cards.") { LiquidActionPillDemo() },
    Block(slug = "live-timer-tab", name = "Live Timer Tab", category = "Navigation", spec = "A black-and-white recipe page with a three-icon tab bar and a timer. \"Start oven\" contracts into a light box that counts down, each changing digit rolling. When that box scrolls off the screen, the stopwatch in the tab bar swells into a black pill that carries the running time; when the box comes back the pill collapses and the time rises from it to the box, which fades in around it. Tapping the pill scrolls back to the box, and tapping the box stops the timer.") { LiveTimerTabDemo() },
    Block(slug = "magnify-dock", name = "Magnify Dock", category = "Navigation", spec = "A desktop-style dock of seven invented apps over a blue-hour mountain wallpaper: four ridges fading into the haze under a sky that warms towards a low sun, with the date and a bold \"9:41\" in the sky. The dock is frosted glass with a lit rim and a soft shadow. Each icon is drawn in layers on a squircle like a real app icon: Postbox (an envelope on blue), Margin (a ruled notepad with a yellow band), Hum (a double note on red), Wayfare (a little map with a river, roads and a pin), Lumen (a camera lens on graphite), Fairweather (a sun behind a cloud) and Workshop (a steel gear). Sliding a finger along the dock swells the icons near it on a smooth falloff, pushing their neighbours apart, with one dark name popover that glides from icon to icon over the one under the finger, resizing to each name as the names cross-fade; a tap launches an app with two bounces and a running dot under it; a long press sets the icons wiggling with a Done button, and an icon can then be dragged to a new place in the row.") { MagnifyDockDemo() },
    Block(slug = "orbiting-top-tabs", name = "Orbiting Top Tabs", category = "Navigation", spec = "An editorial shop screen in black and white whose top tabs are tiny capitals set on an arc, like the rim of a large wheel with its hub far below the screen: \"NEW IN\", \"BROWSE\", \"ARCHIVE REVIVAL\" and \"TRAIL RUNNER\". Paging turns the wheel: the next tab climbs to the top centre and straightens while its page comes in over the one that leaves, its picture trailing behind its text. The pages hold drawn sneakers, two full-width photos with a paragraph each, and a black bottom bar closes the screen.") { OrbitingTopTabsDemo() },
    Block(slug = "period-stats-switcher", name = "Period Stats Switcher", category = "Navigation", spec = "A light statistics screen under a three-way switch, Week, Month and Year. Week shows a green goal disc with the step count, three totals, a bar chart of the days and two cards; Month and Year replace the disc with a large italic total and add a second row of cards for the best and the worst day or month. Changing the period rebuilds everything under the switch in one move: the white capsule slides to the tapped segment, the disc shrinks away and the page closes up, every figure rolls to its new digits column by column, and the old bars sink while a new set grows from the baseline, left to right.") { PeriodStatsSwitcherDemo() },
    Block(slug = "pinch-out-timeline", name = "Pinch Out Timeline", category = "Navigation", spec = "A calm, journal-like conversation set in a serif face on a pale grey page that turns rose at the bottom, with a list of days behind it. Pinching the conversation shrinks it onto its day's card while the other days slide in around it; tapping a card, or spreading two fingers on it, blows the cards up, shows that day's date alone on the page for a moment and brings its conversation in message by message. Each day has its own conversation, and the small arrows in the top bar make the same two moves without a pinch.") { PinchOutTimelineDemo() },
    Block(slug = "rail-to-bar-morph", name = "Rail To Bar Morph", category = "Navigation", spec = "One white navigation surface on a blue field that exists in three shapes: a labelled list of seven destinations, a narrow icon rail and a bottom bar of five icons. The surface itself morphs from one shape to the next, and every icon is the same view all the way: it flies from its row in the column to its place in the bar along a curve, so that mid-way the icons lie on a diagonal across a large white card. The current destination has a capsule in the list and is tinted in the rail and the bar, where a tapped icon hops and fills; the field behind shows the destination's name over three cards.") { RailToBarMorphDemo() },
    Block(slug = "roadmap-path-stepper", name = "Roadmap Path Stepper", category = "Navigation", spec = "A white roadmap screen with one indigo accent: a top bar with a back button, a \"Trip on 22 Dec, 09:52 PM\" pill and a home button, the heading \"The Roadmap to Your Trip\", and a numbered list of six steps on a vertical rail. A line leaves a map pin beside the heading, turns under it and becomes the rail. On entry the line draws itself, the pin rides it down to the first step and becomes its node, then the screen rises while the accent runs down the rail and each step fades in as the line reaches it. Afterwards the list scrolls under the fixed heading, a tap on a step moves the accent to it, and Continue goes one step on.") { RoadmapPathStepperDemo() },
    Block(slug = "roaming-fab-tab-bar", name = "Roaming FAB Tab Bar", category = "Navigation", spec = "A white screen with a plain four-icon tab bar and one round blue button that changes place and purpose with the tab. The icon of the chosen tab turns into a heavier drawing (a solid house, a thick magnifier, a smiling face with a badge, a solid bubble) and wiggles on its own pivot. The button is a large plus above the middle of the bar on Home, shrinks away on Search and Add friends, pops in at the right as a smaller compose button on Chats, and slides along a shallow arc between its two places while one glyph turns into the other. Each tab shows its own page of placeholder cards or rows.") { RoamingFabTabBarDemo() },
    Block(slug = "spotlight-tab-bar", name = "Spotlight Tab Bar", category = "Navigation", spec = "A monochrome tab bar lit by a lamp: a grey pill with four solid glyphs in the shade (person, house, bell, camera), a short white bar lying on its top edge, and a cone of light falling from that bar into the pill, which turns the glyph under it white. Choosing a tab slides the lamp there with its beam leaning back and flaring on arrival; on the jump across the whole bar the lamp dims and the glyphs it passes catch the light for a moment. The lamp can also be dragged along the pill and goes to the nearest tab on release. The page above, a title over grey placeholder cards with the tab's glyph on the first one, changes with the tab.") { SpotlightTabBarDemo() },
    Block(slug = "stack-grid-switcher", name = "Stack Grid Switcher", category = "Navigation", spec = "A music library with two views of the same sleeves, chosen with a toggle at the top right. The stack shows the sleeves lying flat one above the other in perspective: above eye level you look at their underside, below it at their covers, and the one at eye level shows only its front edge with the title, so scrolling turns each sleeve over as it passes. The toggle blows the stack apart and assembles a flat three-column grid of the covers, and back; a segmented control swaps albums for playlists, and the covers are drawn in code.") { StackGridSwitcherDemo() },
    Block(slug = "subitem-tab-bar", name = "Sub-Item Tab Bar", category = "Navigation", spec = "A light page of placeholders with a black bar of four tabs docked at the bottom: Work, About, Journal and Login, each a line icon over a small label. Pressing a tab makes the bar grow upward to hold that tab's sub-items: rows of filter chips for the first three, a sign-in form (email, password, \"Sign in\", \"Forgot password?\") for the last, while the page behind blurs and pales. Another tab swaps the panel and the bar's height; pressing the open tab, or the page, closes the bar.") { SubitemTabBarDemo() },
    Block(slug = "swipe-deck-toolbar", name = "Swipe Deck Toolbar", category = "Navigation", spec = "A dating-style swipe deck on a dark screen with a blue glow, and a black toolbar that changes shape for it. On the deck's tab the band's top edge sinks into a valley between the first and the last icon, and the clock and the heart in the middle slide together into a glass capsule as a cross and a solid heart; dragging the top card lights the red or the green side of the capsule, and letting go past the threshold sends the card off and brings the next one up. On the other three tabs the band is flat, with a ring that slides to the tab that was pressed.") { SwipeDeckToolbarDemo() },
    Block(slug = "switcher-deck-nav", name = "Switcher Deck Nav", category = "Navigation", spec = "A four-page photo journal, \"Slow Departures\": a cream feed with a dusk station photo and two smaller platform shots, a dark entry page under an airplane-window photo with altitude, local time and flight length, a pale blue-grey route map drawn with a rail line, a dashed flight arc and five stops above a \"Next stop\" card, and a navy profile with stats and a grid of saved frames. Every page ends in a small handle, a plain pill above the bottom edge. Pulling the handle up shrinks the page under the finger into a card while the other pages slide in beside it, fanned over a dark warm backdrop as an app-switcher deck in perspective: pages to the right lie on top and spread wide, pages to the left tuck under, recede and darken, each with a glass title chip over its top-left corner, under \"Slow Departures\" and a count of open pages. The deck scrolls sideways with momentum; tapping a page zooms it back to the full screen, flicking one up closes it while the rest close the gap, and a \"Reopen closed pages\" chip brings them back.") { SwitcherDeckNavDemo() },
    Block(slug = "expanding-bottom-tabs", name = "Expanding Bottom Tabs", category = "Navigation", spec = "A bottom tab bar with four tabs, Home, Discover, Chat and More, on a black screen. The active tab is a wide white pill showing its icon and label; the others are narrow and show only an icon, and the screen above names the selected tab.") { ExpandingBottomTabsDemo() },
    Block(slug = "find-friends-invite", name = "Find Friends Invite", category = "Onboarding", spec = "A find-friends onboarding screen: a black search field with a close button, an invite card with a rendered takeaway cup, a bold headline and a blue-to-violet \"invite them\" button, and a contacts card with a cluster of round avatars, a privacy line and a black \"check contacts\" button. Type is Anybody; layout, sizes and colours follow the pin.") { FindFriendsInviteDemo() },
    Block(slug = "price-tag-welcome", name = "Price Tag Welcome", category = "Onboarding", spec = "A welcome screen for a spending-awareness app: a green card icon, a two-line headline, and a row of product stickers with tilted white price tags above a blue Get started button. Tap a product to freeze its price: ice crystals grow from the tag over the whole sticker, the product greys and cools, the price blurs under the rime, \"Wait 24h\" is etched into the tag and a 24-hour countdown is etched over the product. Tap again to thaw it. The row is still a conveyor you can fling, with tags that swing like pendulums.") { PriceTagWelcomeDemo() },
    Block(slug = "cloud-basket-essentials", name = "Cloud Basket Essentials", category = "Onboarding", spec = "Pixel ESSENTIALS lettering and a decorative DESIGNERS headline sit above a teal sky crossed by a diagonal bank of soft clouds. Six miniature objects fall into a pale pink wire basket with two red handles: a CRT computer, notebook, socks, striped mug, toast and cherry headphones. The screen follows the reference composition with original English copy and code-drawn artwork.") { CloudBasketEssentialsDemo() },
    Block(slug = "mascot-social-tour", name = "Mascot Social Tour", category = "Onboarding", spec = "A white social onboarding tells four illustrated stories with scalloped blue, green, red, yellow and magenta mascots. Friends gather around a phone, spring out from a squashy blue character, unfold a yellow widget frame and take pictures of memories in pale bubbles. Heavy rounded headlines sit above small legal copy behind a pale scalloped cloud boundary, with a blue pager and Login pill at the top.") { MascotSocialTourDemo() },
    Block(slug = "neon-card-flight", name = "Neon Card Flight", category = "Onboarding", spec = "A white first-launch screen for the invented Nova <18 wallet, with a fixed headline and two pill actions. An acid-yellow card approaches through speed lines, cuts to two rapid lateral flights through assembling glossy objects, then glides back in front. Local generated 3D sculpture sprites reproduce the closed interlocking links, sculpted cup, headset, padlocks, shield, star, cap, puzzle piece and coins; the card itself is drawn in code.") { NeonCardFlightDemo() },
    Block(slug = "rainbow-book-beam", name = "Rainbow Book Beam", category = "Onboarding", spec = "A reading welcome for the invented Oria app, built around an orange-gold book floating above a reflected pool. Its covers hinge apart and release five broad, wavy ribbons of pink, magenta and warm yellow, carrying bright pearl lights upward. A quiet headline and pale pink call to action frame the luminous illustration.") { RainbowBookBeamDemo() },
    Block(slug = "denim-pocket-welcome", name = "Denim Pocket Welcome", category = "Onboarding", spec = "A full-screen memory-journal welcome hidden behind dark indigo twill and a centered grey metal zipper. Dragging the pull separates individual teeth into a bowed V before the fabric halves leave a saturated blue setup page with a cream calendar emblem, three short features and a journal action.") { DenimPocketWelcomeDemo() },
    Block(slug = "pool-caustic-welcome", name = "Pool Caustic Welcome", category = "Onboarding", spec = "A sunny blue pool frames a large rippled serif Afloat wordmark, a cobalt palm shadow and a horizontal steel ladder. A top-down yellow duck and two tilted life rings float above the refracted artwork. One translucent local action sits beside the rings.") { PoolCausticWelcomeDemo() },
    Block(slug = "glow-gesture-guide", name = "Glow Gesture Guide", category = "Onboarding", spec = "A guide to a story viewer's gestures on a deep blue-to-violet screen with a warm orange glow drifting behind it: four rows, each with a hand icon, a title and a hint. A frosted highlight springs from row to row and stretches as it travels; the row it lands on grows and brightens, and its hand icon acts the gesture out (a tap ripples, a hold sends arcs outward, the edge bar flashes, the swipe chevrons nudge). Rows can be tapped, and the footer ends the guide.") { GlowGestureGuideDemo() },
    Block(slug = "wallet-unpack-welcome", name = "Wallet Unpack Welcome", category = "Onboarding", spec = "A light welcome screen for a prepaid wallet: an overline, a large ultra-light \"WALLET\", the hero, a tagline over a dotted rule, and a square black \"Get started\" button with the next section's heading cut off beneath it. The hero changes hands: the black card tips back past edge-on and drops behind a green croc-grain card wallet as it appears, two pale notes rise out of the wallet's notched pocket, ripple and slide back in, and the card rises out of the pocket and lands flat where it started. A tap on the hero plays it.") { WalletUnpackWelcomeDemo() },
    Block(slug = "archway-zoom-welcome", name = "Archway Zoom Welcome", category = "Onboarding", spec = "A sign-in sheet (a wordmark, a two-line title, a black \"Continue with Passkey\" button, a text link and a line of small print) at the bottom of a pale monochrome scene that never stops: the camera travels through a stone archway to the tiny bar chart behind it, the bars grow until two of them, turned green, tower over the sheet, and then the camera pushes on through them to the next archway. The scene is flat vector shapes drawn afresh on every frame, so it stays crisp at any zoom, and the round closes on itself without a cut. Dragging up or down over the scene moves the camera by hand.") { ArchwayZoomWelcomeDemo() },
    Block(slug = "aurora-glass-welcome", name = "Aurora Glass Welcome", category = "Onboarding", spec = "A welcome screen for an invented aurora-forecast app under a live northern-lights sky. Three curtains of light hang at three depths over a night-blue sky with faint twinkling stars: crisp green-white hems that fold along their length, comb upwards into rays and turn teal, then violet (red-violet on the farthest), above a mountain range standing as a dark silhouette with the light in its wet reflections. A bold \"Chase the northern light.\" climbs out of its lines under a SOLVIND wordmark and a small weather chip. Low on the screen floats a frosted glass forecast card with a hairline edge brightest along the top: tonight's Kp 6.3, the best window, an activity curve that draws itself on with a pulsing marker on the peak, and cloud cover, moonlight and darkness figures; a white Get started pill and a sign-in link sit below. Dragging tilts the card in 3D while a sheen slides across its glass, and the aurora bends towards the finger.") { AuroraGlassWelcomeDemo() },
    Block(slug = "bookmark-pocket-intro", name = "Bookmark Pocket Intro", category = "Onboarding", spec = "A welcome screen on pale lilac: a big dark bookmark in the middle, the name \"Stash.\" with a coral full stop, a tagline that types itself behind an underscore cursor, and a black \"Get Started\" button. Saved posts (photo cards) fall from the top edge into the bookmark as into a pocket, and it gulps each one: its sides bow out, its top edge dips, and colour glows under it on the third. A tap on the bookmark shrinks it, lifts it leaning 15° and drops it as the hub of two hairline rings on which eight source icons fly out and slowly turn, while the tagline is deleted and typed again. By hand the card waiting at the top edge is dragged into the pocket, and a finger turns the rings.") { BookmarkPocketIntroDemo() },
    Block(slug = "breathing-tide-welcome", name = "Breathing Tide Welcome", category = "Onboarding", spec = "A first launch that starts with one breath. An off-white splash with an orange dot and the wordmark \"stillwater\" gives way to an orange tide whose top edge is a wide arc, carrying a sleeping face (two closed eyes and a smile). Holding the screen makes the tide rise under \"Breathe in\"; at the top it sinks again by itself, more slowly, under \"Breathe out\". After that breath the welcome fades in: a yellow panel with a phone, the face on an orange disc and eight small ornaments that float, above an arched white sheet with a title, a consent checkbox and two pill buttons, the first of them dimmed until the box is ticked.") { BreathingTideWelcomeDemo() },
    Block(slug = "chrome-zero-numeral", name = "Chrome Zero Numeral", category = "Onboarding", spec = "An onboarding screen for an invented wallet, \"nought\", built around one object: a thick chrome \"0\" with mirror faces and cobalt chrome walls, a gunmetal \"%\" hooked on its side, a black glass card leaning under it and three chrome sparkles, on deep navy crossed by two ribbons of blue-white light. Under it sit a brand pill, the headline \"0% deposit fees. Every time.\", one line of body and a full-width glass button. The numeral is ray-traced on every frame against a studio environment, so its reflections are real and move as it turns.") { ChromeZeroNumeralDemo() },
    Block(slug = "color-shift-card-stack", name = "Color Shift Card Stack", category = "Onboarding", spec = "A loud typographic welcome: the whole screen is one flat colour, with a huge four-line headline in a dark tone of that colour (one word in white), two lines of small print, a little stack of white cards and a white \"Sign in\" button. Each card spells out a number in words with its last word in colour. Flicking the top card away brings the next one up from the stack and gives the screen that card's colour; the cards go round in a ring, and dragging the other way brings the last one back.") { ColorShiftCardStackDemo() },
    Block(slug = "curtain-split-welcome", name = "Curtain Split Welcome", category = "Onboarding", spec = "A welcome screen for an invented architecture-stays app: a full-screen photo of a building, a large index number with \"/ 05\" beside it and a tracked wordmark at the top, and at the bottom a small place name over a two-line white headline, with a round white arrow button and \"Swipe up\" on the right. Turning to the next scene cuts the photo and its headline into six vertical strips that slide away like blinds, alternately up and down and one after another, parting and darkening as they go to show the next scene settling in underneath. Dragging up or down scrubs the strips by hand.") { CurtainSplitWelcomeDemo() },
    Block(slug = "ember-glow-story", name = "Ember Glow Story", category = "Onboarding", spec = "A black screen that tells a short argument one sentence a page, in large bold type above a faint pill button. Light glows up from the bottom edge, a dark tint with a hot spot half below the screen, and changes colour with each page: ash, green, green with a streak of amber, crimson. Each sentence is written word by word in a warm grey, then its key words and their small glyphs light up white one after another. The third page keeps the second sentence, dims it and writes on under it. A tap goes on, a swipe down goes back, the glow comes under a finger resting on the button, and the last page's \"Unlock\" floods the screen with light before the first page returns.") { EmberGlowStoryDemo() },
    Block(slug = "energy-wave-story", name = "Energy Wave Story", category = "Onboarding", spec = "A three-step explainer on a white screen under a pale lavender header whose lower edge sags. In the header a thick wave line with two crests runs between two white discs, one with an amber alarm clock and one with an indigo bed. The wave is grey at first, then colour runs along it from left to right: gold on the crests, blue in the troughs. A tap anywhere brings three white emoji tags out of the crests and the trough while the headline below changes; the next tap flips each tag to a new emoji and moves one of them along the wave. A finger dragged along the wave on the first step moves the colour, and a tapped tag hops while its emoji turns once.") { EnergyWaveStoryDemo() },
    Block(slug = "flow-field-welcome", name = "Flow Field Welcome", category = "Onboarding", spec = "A black welcome screen whose hero is a field of 324 short white strokes. Packed, they are a small shimmering square; opening, the square is torn into a pinwheel and settles as a vortex of rings round a wandering eye, and closing runs the same way back. Under it sit the title \"Welcome\", a grey subtitle, a white and a dark pill button and a legal note with two underlined links. A tap on the field opens or closes it, and a finger on it pushes the strokes away and turns them towards itself like iron filings.") { FlowFieldWelcomeDemo() },
    Block(slug = "glass-blade-draw", name = "Glass Blade Draw", category = "Onboarding", spec = "An onboarding page for a prize draw, built around a fan of thick frosted-glass blades. The blade in the middle faces you and is lit from inside in its own colour; the number set into it is its light level, so the count and the glow are one value. A lit glass bar at the bottom draws a blade.") { GlassBladeDrawDemo() },
    Block(slug = "glass-rod-onboarding", name = "Glass Rod Onboarding", category = "Onboarding", spec = "A three-page onboarding for an invented desert-routes app whose pages change under a glass rod lying across the screen. Each page is a full-bleed photo of dunes, a slot canyon or a night sky over the sand, with a tracked label, a bold two-line title and one line of copy, under the app's mark and a Skip link. Dragging pulls the rod over the page: behind it is the next page, and the seam between the two shows flipped and squeezed in the glass, with red and blue fringes, two highlights, dark edges where the glass turns away and a soft shadow on the page beside it; the rod follows the finger, leans as it moves and tilts as the finger rises or falls. The page dots stretch with the paging and the cream button below changes from \"Continue\" to \"Get started\" on the last page.") { GlassRodOnboardingDemo() },
    Block(slug = "goal-staircase-glow", name = "Goal Staircase Glow", category = "Onboarding", spec = "A black stage with two lights: a glowing ball at the lower left and a gold goal at the upper right, each with a soft halo and a dim copy on the floor. The ball wonders how to get there: a dashed line reaches towards the goal and three question marks pop up over it. A tap calls a staircase of five word labels between them, each further tap makes the ball hop one step up (a long press runs the rest), every label lights up as the ball lands on it, and on the last hop the goal bursts. A tap after that fades everything to black and the scene starts again.") { GoalStaircaseGlowDemo() },
    Block(slug = "liquid-swipe-onboarding", name = "Liquid Swipe Onboarding", category = "Onboarding", spec = "Four onboarding pages for an invented volcano-trekking app, Caldera, each a bold full-bleed colour (lava orange, basalt black, ash peach, oxide red) with a photo in a tall arch, a heavy condensed two-line headline, a short line of copy and page dots. A smooth bump of the next page's colour sticks out of the right edge with a small chevron, and the previous page waits the same way on the left. Dragging pulls the next page after the finger as a liquid wave whose bulge follows the finger and widens as it goes; past a third of the width it sweeps across and fills the screen with a springy overshoot, and an early release lets the liquid fall back into its tab. The last page ends with a \"Pick a volcano\" button.") { LiquidSwipeOnboardingDemo() },
    Block(slug = "liquid-swipe-pages", name = "Liquid Swipe Pages", category = "Onboarding", spec = "Three full-colour onboarding pages (indigo, green, orange), each with a flat picture, a title, a line of text, a dash pager and an outlined Skip button. The next page waits behind the right edge as a strip that swells into a breathing bump with a round arrow in it. Dragging the bump pulls a tall wave of the next page's colour across the screen with its tip under the finger, and letting go past the middle sends the wave to the left side, where it settles with one soft overshoot. The pages' content never slides: the wave covers one page and uncovers the next, and the last page's wave leads back to the first.") { LiquidSwipePagesDemo() },
    Block(slug = "logo-window-reveal", name = "Logo Window Reveal", category = "Onboarding", spec = "The intro of a countdown app on a white screen. Its mark, a black disc with a rounded window in it, swells and flies at the viewer until the window has swallowed the screen: the photo that showed through it now fills the screen with an event's title. The photo then shrinks into one square card of a list, the list scrolls, zooms out into three columns and runs up until its last row hangs from the top over the app's name, spelled out letter by letter above a tagline.") { LogoWindowRevealDemo() },
    Block(slug = "merging-step-dots", name = "Merging Step Dots", category = "Onboarding", spec = "The controls of a three-step onboarding flow, with a page per step above them (a soft tile with an icon, a title, two lines of text). The pager is one green pill that stretches from the first dot to the current one, turning each grey dot white as it swallows it. \"Back\" comes out from under the blue main button, which moves its left edge over to make room, and on the last step the button's label changes from \"Continue\" to \"Finish\" behind a white check that pops in.") { MergingStepDotsDemo() },
    Block(slug = "metacard-unify-fan", name = "Metacard Unify Fan", category = "Onboarding", spec = "An onboarding hero for a card-aggregator: eight bank cards, each with its own print and material, fanned in a slowly turning circle around a glossy black octagonal hub, with a headline below and a hint line at the foot of the page. Pressing the hub folds all eight into the centre, where the hub grows into a single black Metacard that rises in perspective with a moving studio reflection, under a wordmark and a second headline.") { MetacardUnifyFanDemo() },
    Block(slug = "morphing-badge-tour", name = "Morphing Badge Tour", category = "Onboarding", spec = "A wallet's intro on near-black: a fixed lower third (a two-line caption, small print with two blue links, a white \"Create new wallet\" pill and a plain \"I already have a wallet\") under a stage where one cast of flat gradient shapes keeps re-forming. A hero badge (white disc, black rounded square, blue ring) sits on a yellow capsule with eight glyph badges floating round it; the badges become a three-by-three grid round the hero, the grid bursts into a constellation of discs, and the constellation folds into a striped wallet with a clasp, under a beam a blue diamond drops along. Nothing cuts: every shape keeps its identity and travels, resizes, re-rounds and recolours into what it is in the next scene. Tap the stage or swipe left for the next scene, swipe right for the one before.") { MorphingBadgeTourDemo() },
    Block(slug = "orbit-coin-tour", name = "Orbit Coin Tour", category = "Onboarding", spec = "A feature tour in three scenes. On a sand screen three coins, each with a line icon, ride thin rings round a coral disc with the letter N, among small flipping coins and dots. A tap on a coin pushes the camera through the rings while that coin flies to the top of the screen, flipping, and the disc opens into the top of the product's card: a green savings card, an upright coral payment card on a green ground, or a slate insights card with a chart on taupe. Swipes slide from scene to scene, a swipe down or a tap on the coin pulls back out to the orbit, and in the orbit a drag spins the rings.") { OrbitCoinTourDemo() },
    Block(slug = "polaroid-develop-welcome", name = "Polaroid Develop Welcome", category = "Onboarding", spec = "A welcome screen for an invented road-trip journal, set on a dark walnut table under a warm lamp. A drawn cream instant camera sits at the top with a big lens in a ringed barrel, a ribbed flash, a viewfinder and a terracotta shutter button; below it the headline \"Every mile, one frame.\", one sub line, a cream \"Start your roadbook\" button and an \"I already have an account\" link. The screen opens with the camera taking a photo: the flash fires and a print slides out of the slot and, without stopping, settles onto the table with a tilt, then develops from a dark brown blank through a pale, washed-out ghost to full colour while a blue handwritten caption writes itself on its border. Tapping the shutter takes another, which lands on top of a messy pile; holding and shaking the top print develops it faster, and throwing it aside sends it under the pile.") { PolaroidDevelopWelcomeDemo() },
    Block(slug = "press-hold-sunrise", name = "Press Hold Sunrise", category = "Onboarding", spec = "A welcome screen in cream with a small mark, the name \"Motes.\" in a serif face, a two-line tagline and one control: a 58 pt orange button with a bolt on a white disc, over a faint field of halftone dots, with \"PRESS AND HOLD TO GET STARTED\" at the bottom. Holding the button makes it grow until it fills the disc; at the end of the hold it bursts over the whole screen and a tunnel of shapes born in the centre (a rounded square on its corner, a scalloped circle, a squircle, a wavy blob and a circle, dark and orange in turn) carries the app into its dark first page, where a heading slides in, three orange balls drop onto a disc, a curved pager draws itself and two pill buttons rise. Tapping the mark on that page goes back through three shrinking shapes to the welcome.") { PressHoldSunriseDemo() },
    Block(slug = "shape-shuffle-welcome", name = "Shape Shuffle Welcome", category = "Onboarding", spec = "A white welcome screen with a title, a line of text, a small Get Started button and, in the middle, a still life of grey blocks with one accent colour that keeps rebuilding itself. The same eleven pieces (squares, a staircase, a roof, discs, a bowl) tumble, stretch, round off and change colour to form four buildings in turn: a house with stairs, a bungalow, a tower and a terrace. Every piece keeps its identity from one building to the next, and lands with a springy overshoot.") { ShapeShuffleWelcomeDemo() },
    Block(slug = "sky-glass-steps", name = "Sky Glass Steps", category = "Onboarding", spec = "An introduction in three steps under a drifting sky. A white headline floats on blue sky and soft clouds, and the steps are cards of frosted glass in a carousel without end, each with a small preview that plays when its card comes to the middle: four goals with a white selection that steps down the list, a stack of three lesson cards, and a month of a routine whose squares tick green. The sky is drawn, not a photo: three strips of soft white ellipses that move at different speeds, drawn a second time inside each card, larger, fainter and tinted, so the clouds pass behind the glass as slow shifts of light without any blur filter. A swipe brings the next card, a tap on a card at the side brings that one, a tap picks a goal or changes a square, and the headline leans 6 pt against a dragging finger.") { SkyGlassStepsDemo() },
    Block(slug = "spirograph-pager", name = "Spirograph Pager", category = "Onboarding", spec = "A white intro pager whose only artwork is one set of 24 hairline ellipses in navy. Every page arranges them into another figure: a small circle that blooms into a cone of rings, two wire spheres that turn about their axis, three sets of rings that squash into a lens, an hourglass that opens into two bowls, a lattice that collapses into three circles, one large faint circle. A change of page sends each ellipse from its place in one figure to its place in the next, one after another, while the blue title and the grey body slide up. Swipe up or tap the round arrow for the next page, swipe down for the one before; a drag scrubs the change, and after the last page comes the first.") { SpirographPagerDemo() },
    Block(slug = "theme-flavor-carousel", name = "Theme Flavor Carousel", category = "Onboarding", spec = "A personalisation step on a white screen: \"Select or Create a Flavor\" over a carousel of tall cards, each a soft mesh gradient in one colour family (Mint, Clay, Graphite, Azure, Cobalt, Lagoon), with a glassy \"Select Flavor\" pill underneath. The carousel goes round without an end, the cards beside the middle one sit a little smaller and lower, and the pill's tint, border, glow and label take the colours of whichever card is passing the middle, in step with the swipe. Pressing the pill gives the whole screen that flavor: the card's mesh grows from the card over the screen and the texts turn white; pressing again takes it back.") { ThemeFlavorCarouselDemo() },
    Block(slug = "value-word-wheel", name = "Value Word Wheel", category = "Onboarding", spec = "A sign-up entry screen. In the white upper half a wheel of single words (Spend, Earn, Save, Pay, Invest) turns one row at a time: the word on the focus line is dark and sharp beside its coloured icon, the rows above and below are faint and blurred, and the list never ends. Below it a blue light with a domed upper edge breathes behind the app's tile, a two-line headline, a caption and two pill buttons. The wheel can be dragged, and a faint word can be tapped into focus.") { ValueWordWheelDemo() },
    Block(slug = "velocity-marquee", name = "Velocity Marquee", category = "Onboarding", spec = "An onboarding screen for an invented photo app, on warm off-white paper with a fine grain. Under a small mark and the \"Afterimage\" wordmark, three rows of rounded photo tiles tilted about 8 degrees, rising to the right, run as endless marquees, the middle row the other way. Below them sit page dots, a short semibold headline with a line of body text under it, a full-width black \"Get started\" pill and an \"Already have an account? Sign in\" line. Swiping through the three pages throws the rows with the finger's speed: they race, the tiles lean into the motion like italic type and stretch, then ease back to the idle drift while the headline slides across to the next page and the wide page dot moves with it.") { VelocityMarqueeDemo() },
    Block(slug = "watchful-eyes-permission", name = "Watchful Eyes Permission", category = "Onboarding", spec = "A permission primer for health data on a night-blue screen, told by a pair of glowing eyes. They sit over a chat, come down and grow to ask from inside a small house with data falling in it, fly back to the top while a phone's outline draws itself, watch six switches turn on, and smile at a check mark. The four pages change on one clock, and the eyes keep their own timing on top of it: they blink, glance left and right, stretch in surprise, shake a \"no\" for Later and look towards a finger.") { WatchfulEyesPermissionDemo() },
    Block(slug = "gravity-tags-onboarding", name = "Gravity Tags Onboarding", category = "Onboarding", spec = "An onboarding step for choosing interests. Colored tag pills fall into the lower half of the screen and pile up like physical objects; tapping a tag selects it. A step indicator sits on top and a Continue button at the bottom.") { GravityTagsOnboardingDemo() },
    Block(slug = "card-carousel-onboarding", name = "Card Carousel Onboarding", category = "Onboarding", spec = "An onboarding screen for a gifting app on a pale lilac-to-white-to-mint gradient. The headline \"See what your friends want\" has three small avatar photos set into it, a row of small cards (photos in rounded and scalloped frames, \"Gift your Friends\" collages, a gradient checklist) drifts past underneath, and Find Friends and Create an account buttons sit at the bottom.") { CardCarouselOnboardingDemo() },
    Block(slug = "owl-alarm-ruler", name = "Owl Alarm Ruler", category = "Pickers", spec = "An onboarding step that sets the first alarm: a white owl with round glasses works at a laptop above a big 1:05 PM, and a ruler of ticks under a red needle sets the time in five-minute steps. The ticks swell and darken as they pass the needle, the digits roll like an odometer, AM and PM flip as the ruler crosses noon, and the button's label always reads the chosen time.") { OwlAlarmRulerDemo() },
    Block(slug = "stamp-diary-calendar", name = "Stamp Diary Calendar", category = "Pickers", spec = "A dark diary calendar pairs a sheared collage of perforated, illustrated postage stamps with memories stamped on their days. Peel a day's stamp with your finger and it flies into its place in the collage, where a postmark with the date is inked onto it; tap to send it home. Empty dates and neighbouring months stay selectable.") { StampDiaryCalendarDemo() },
    Block(slug = "horseshoe-time-ruler", name = "Horseshoe Time Ruler", category = "Pickers", spec = "A dark day planner winds its time ruler into a deep U-shaped track. Appointment markers, labels and fine ticks travel around the bend beneath a fixed blue clock and needle. A compact date toolbar directly below the status bar and small blue footer details retain the spare hierarchy of the reference.") { HorseshoeTimeRulerDemo() },
    Block(slug = "velvet-nap-studio", name = "Velvet Nap Studio", category = "Pickers", spec = "An invented fabric shop presents a fixed folded navy velvet sample with crushed fiber texture. Brushing the pile in opposite directions makes the same local trail lighter or darker while its folds and shadow stay still. Choose a color and quantity, or add a sample with a local confirmation.") { VelvetNapStudioDemo() },
    Block(slug = "four-elements-class-picker", name = "Four Elements Class Picker", category = "Pickers", spec = "An ivory wellness home pairs four elemental line drawings with an earthy class picker. A leading ink tip traces the selected mark, then reveals its class details and a local reservation action. Warm rust, sage and ochre accents sit beneath a quiet serif wordmark.") { FourElementsClassPickerDemo() },
    Block(slug = "magnetic-feeling-field", name = "Magnetic Feeling Field", category = "Pickers", spec = "A dream journal surrounds an eleven-by-eleven field of pastel dots with two softly tinted glass panels. The dots swell around a translucent touch disc as neighboring hues shift through teal, yellow, coral and violet. Each feeling word compresses and blurs from left to right as its letters change. Drag the field to choose a feeling or save it locally.") { MagneticFeelingFieldDemo() },
    Block(slug = "morph-bubble-column", name = "Morph Bubble Column", category = "Pickers", spec = "A field-survey app on a white screen with a faint dot grid, edge to edge: the date and a pixel clock reading 9:PM at the top left, a black pill at the top right with an avatar and a bolt button, a dark notch in the right edge holding three tool icons and a white bar at the bottom with a zoom slider. Down the middle runs a column of round photo bubbles, one per survey site, each with its number and name beside it. The selected site is a big rounded square with its coordinates and a hairline leading to it; dragging along the column moves the selection, and the bubbles morph between circle and rounded square as it passes. Tapping the selected site grows its bubble into the whole screen, where a monospace heading types itself behind a block cursor, a target ring locks onto the photo, a big dot-matrix reading counts up and the slider zooms into the photo; dragging down puts it back in the column.") { MorphBubbleColumnDemo() },
    Block(slug = "arc-activity-picker", name = "Arc Activity Picker", category = "Pickers", spec = "A wheel of activities seen from its left flank on a light grey panel. Each row is a grey label and a pale icon chip with a line icon in the activity's own colour; the rows ride an arc whose centre is far off the right edge, tilting along their spokes and fading towards the top and bottom. A thin rim with a dark capsule knob marks the selected slot: the row beside it sits level, its chip a tinted pill with a coloured outline and glow, its label dark on a small white plate.") { ArcActivityPickerDemo() },
    Block(slug = "bending-line-humidity-slider", name = "Bending Line Humidity Slider", category = "Pickers", spec = "A vertical humidity slider on a dark navy panel, drawn as one thin line that swerves left around its white knob like a string pushed aside by a bead. The line is cyan through the recommended band (20% to 55%) and turns magenta above and below it; a ladder of short ticks left of it bends with it, and further left stand the labels of an uneven scale (100%, 75%, 50%, 45% … 10%, 0%), the extreme ones with a yellow dot and the one beside the knob replaced by the live set-point in cyan. Right of the line three read-outs are stacked: a temperature, the humidity as a large figure, an absolute humidity, and a warning about set-points outside the band.") { BendingLineHumiditySliderDemo() },
    Block(slug = "branching-price-wheel", name = "Branching Price Wheel", category = "Pickers", spec = "A white card with nothing on it but type: a column of amounts in tens (30\$ to 100\$) in a heavy navy face, the one in the middle twice the size and mint green. From that amount the units (61\$, 62\$, …) branch out to the right on the same line in a hairline pale grey, so the picker is a T on its side: dragging up or down turns the tens, dragging sideways slides the units through the selected cell. A thin close cross sits top right and a green Save capsule bottom right.") { BranchingPriceWheelDemo() },
    Block(slug = "budget-scrub-scale", name = "Budget Scrub Scale", category = "Pickers", spec = "A budget panel built around a ruler: a row of category chips, the amount in heavy digits on a white card, and an indigo panel with a ruler of dots and ticks under a fixed turquoise indicator, a verdict (\"Normal\", \"That's a lot\", \"Are you crazy?\") and a Save button. The open category is a coloured pill that carries its name and amount; dragging the ruler sets the amount, which counts on rolling digits.") { BudgetScrubScaleDemo() },
    Block(slug = "camera-mode-arc-dial", name = "Camera Mode Arc Dial", category = "Pickers", spec = "The top of a camera's mode dial drawn flat, white on black: a fixed half circle of 49 ticks with a long index at 12 o'clock, and inside it a ring of ten mode marks (a tulip, two peaks, AUTO in an outlined capsule, P, S, A and M on white discs, C1 to C3 in bare monospaced type), each turned to follow the ring. Dragging around the centre turns the ring, and the mode under the index is named in the middle.") { CameraModeArcDialDemo() },
    Block(slug = "color-ring-picker", name = "Color Ring Picker", category = "Pickers", spec = "A colour picker on a dark panel: the serif title \"Pick a color\", two grey lines of text, a ring of sixteen small outlined circles, one per colour, and an orange \"FINISH & SAVE\" pill. The chosen colour is not on the ring: its place is empty, and it sits in the middle as a large ring with a thick line.") { ColorRingPickerDemo() },
    Block(slug = "cylinder-month-carousel", name = "Cylinder Month Carousel", category = "Pickers", spec = "A month of tall picture cards (225 × 400 pt, drawn autumn landscapes) standing on a drum seen from outside, on a near-black screen. The card in front faces the viewer with its title and its artist's name on a dark pill; its neighbours are turned 56° away around the vertical axis, pushed back, darkened and partly hidden behind it, and each card carries a lock or a heart in a round badge. Under the drum a strip of ticks, one per card and bunched towards its far end, keeps the front card's tick (white, thicker, taller) in the middle, above the month's name and a soft glow in the front card's colour.") { CylinderMonthCarouselDemo() },
    Block(slug = "date-lens-strip", name = "Date Lens Strip", category = "Pickers", spec = "A date picker in a white capsule on pale grey: the label \"PICK A DATE:\" in royal blue on the left, then a row of days, each a small grey weekday over a bold two-digit number. Over the selected day stands the lens, a tall capsule of electric blue that rises above and below the bar and shows that day in white.") { DateLensStripDemo() },
    Block(slug = "disc-tray-picker", name = "Disc Tray Picker", category = "Pickers", spec = "A disc player seen from above on a light grey screen: a rounded tray with a round well, and under it a grid of six compact discs drawn with gradients, a rainbow sheen and a white hub, over a black \"Continue\" pill. Tapping a disc flies it into the tray, where it grows to the well's size and turns; the name of the loaded disc replaces \"Choose a disc\" under the tray.") { DiscTrayPickerDemo() },
    Block(slug = "duration-scrub-strip", name = "Duration Scrub Strip", category = "Pickers", spec = "A compact duration scrubber on a dark screen: a rounded strip with the start time and the end time in two monospaced chips and a row of 25 thin ticks between them, one for every half hour up to twelve. A red marker stands in the ticks at the chosen duration, and a red pill riding above it, across the strip's top edge, reads the duration (\"0m\", \"3h 54m\", \"12h\"). The ticks the marker has passed are lit, brightest just behind it.") { DurationScrubStripDemo() },
    Block(slug = "gooey-radial-picker", name = "Gooey Radial Picker", category = "Pickers", spec = "A radial mood picker made of drops, on a pale blue-grey stage. A white disc in the middle shows the chosen mood as a large yellow face; eight options sit round it as small translucent circles holding grey faces. The chosen one is opaque, its face in colour, and joined to the disc by a neck, as two drops that touch, and the joined shape casts one soft shadow. A translucent orange ring at the lower edge of the chosen circle marks where the finger is.") { GooeyRadialPickerDemo() },
    Block(slug = "mood-character-dial", name = "Mood Character Dial", category = "Pickers", spec = "A mood picker in two halves. On top, a pastel panel with rounded corners holds one large flat character per mood (a sleeping yellow circle, a coral blob with a plus on its forehead, a pink shopping bag with a heart…), laid out as a carousel with the neighbours' edges peeking in. Below, on a near-black green panel, a two-line serif title, a row of 31 thin bars under a bell-shaped envelope with a gradient needle in the middle, and a row of outlined chips; the chip under the needle is filled with the mood's two-colour gradient.") { MoodCharacterDialDemo() },
    Block(slug = "moon-orbit-time-scrubber", name = "Moon Orbit Time Scrubber", category = "Pickers", spec = "A time scrubber over a small model of the sky, on a tall rounded card. A white pill showing the time rides the card's right edge from 00:00 at the top to 23:59 at the bottom, past a \"Now\" chip and two small moonrise and moonset marks. In the middle a thin ring, a dotted arc for the moon's path and a soft rounded pyramid turn together as one solid model, with a small grey moon travelling along the arc; the card's background is the sky at that hour, and a translucent bar at the bottom names the phase with a percentage that counts with the time.") { MoonOrbitTimeScrubberDemo() },
    Block(slug = "notch-radial-menu", name = "Notch Radial Menu", category = "Pickers", spec = "A black tab bar on a dark violet glow, with Home and Profile tabs and a notch in the middle of its top edge that cradles a round violet plus button. Tapping the button turns it black with a cross and fans three lilac action chips (call, message, voice note) out of it onto an arc above; tapping a chip picks it and folds the fan away.") { NotchRadialMenuDemo() },
    Block(slug = "scale-arc-weight-picker", name = "Scale Arc Weight Picker", category = "Pickers", spec = "A target-weight picker shaped like the window of a bathroom scale, on a card washed from lilac to aqua. Under the title and a kg / lbs switch, two white boxes hold today's weight and the target, the target outlined in green with the difference beside it (\"+10 kg\"). The bottom of the card is the top of a large white dial: a tick for every unit, a longer one and a number at every fifth, under a fixed green needle that a small triangle points down to. A translucent wash over the ticks spans from today's weight to the target, green for a gain and amber for a loss.") { ScaleArcWeightPickerDemo() },
    Block(slug = "segmented-ring-selector", name = "Segmented Ring Selector", category = "Pickers", spec = "A round control of two concentric wheels around a white disc, 340 pt across on a dark teal screen, with one fixed index at 12 o'clock. The inner, light grey ring carries nine items as slate glyphs (paint, wheels, steering, locks, charge…); the one under the index sits in a coloured wedge with its name in white and a small tab pointing outward. The outer ring is a thin band of translucent blocks, the options of that item, fading away towards the bottom: the block under the index stands twice as tall in its own colour, and the disc names the option in a light, wide type over a small bold line in the wedge's colour.") { SegmentedRingSelectorDemo() },
    Block(slug = "sleep-range-scale", name = "Sleep Range Scale", category = "Pickers", spec = "A frosted, faintly iridescent sheet that asks \"when did you sleep last night?\". Two large read-outs, Sleep time and Wake time, sit above a scale of 24 hourly ticks from 8 PM to 8 PM with two tall dark handles and a periwinkle-to-lilac band between them; dragging a handle or the band changes the times hour by hour, and the hours of sleep are counted under the read-outs. A chip switches between 12-hour and 24-hour times, next to a dark \"Update sleep\" button.") { SleepRangeScaleDemo() },
    Block(slug = "sunburst-timer-dial", name = "Sunburst Timer Dial", category = "Pickers", spec = "A timer dial drawn in black line work on warm off-white: 28 rays around a dark hub with a white dot, eight small dots outside them, a two-digit value above the hub and the word \"Timer\" below. The face counts 60 units, and rays turn from grey hairlines to bold black clockwise from 12 o'clock as the value grows: one at 00, eight at 15.") { SunburstTimerDialDemo() },
    Block(slug = "walk-radius-dial", name = "Walk Radius Dial", category = "Pickers", spec = "An onboarding question, \"How far are you willing to walk?\", answered on a round street map 300 pt across. A circle of full colour with a white edge sits on the washed-out map around a black badge showing the minutes; a dark capsule handle with two chevrons on the circle's right edge is pulled outward for more minutes (4 to 18) and pushed inward for fewer, and the map zooms so the circle always covers the ground those minutes reach. The map is an invented street grid drawn in code, and a black Next button sits under the dial.") { WalkRadiusDialDemo() },
    Block(slug = "weather-fan-dial", name = "Weather Fan Dial", category = "Pickers", spec = "A weather dial sunk into a dark charcoal surface: a fan of three segments opens upward from a raised round knob, each with a condition drawn in outline, under a mustard pointer whose line runs down to the knob. The fan is the part in sight of a wheel of eight conditions; the one under the pointer is lit cream in a warm glow and read out below, \"It's Clear & 24°\".") { WeatherFanDialDemo() },
    Block(slug = "canopy-beat-hop", name = "Canopy Beat Hop", category = "Playground", spec = "A forest rhythm-hop game with a little green courier bouncing across thick, glowing tiles toward a sunlit mountain horizon. Steer through single, double and wide tile rows, collect blue crystals as the scene changes from green day to blue night, violet and amber.") { CanopyBeatHopDemo() },
    Block(slug = "chrome-smile-crane", name = "Chrome Smile Crane", category = "Playground", spec = "A chrome claw machine stands in a cyan studio with a narrow SMILE marquee, reflected upper glass and a blue prize window filled with glossy yellow faces. Its three-prong claw catches a sunglasses ball and carries it to the delivery hatch in the flared silver base. Layered reflections, a twisted cable and small arcade controls recreate the reference with original code-drawn artwork.") { ChromeSmileCraneDemo() },
    Block(slug = "ferrofluid-blob", name = "Ferrofluid Blob", category = "Playground", spec = "A shallow porcelain dish of glossy black ferrofluid sits on a dark slate table under studio light, seen from above at an angle, with the softbox and a cool strip light reflected in the liquid. A finger is a magnet: the fluid heaps up under it and a crown of sharp spikes rises in a hexagonal pattern, tallest in the middle, leaning in toward the finger and trailing a fast drag; lift it and the spikes melt back with a wobble. A second finger raises a second crown, and a tap makes the spikes flinch up. \"Ferrofluid\" and \"Magnetic study in a porcelain dish\" sit above, \"Hold to raise · Two fingers, two crowns · Tap to pulse\" below.") { FerrofluidBlobDemo() },
    Block(slug = "glass-marbles-tray", name = "Glass Marbles Tray", category = "Playground", spec = "Thirteen glass marbles rest in the carved cups of a walnut tray on a dark table: twelve cat's-eyes in cobalt, amber, emerald, oxblood, milk, violet, aqua, smoke, honey, rose, lime and indigo, and one larger shooter striped red and yellow. Each marble is clear at its centre and thick with colour at its rim, its swirl of leaf-shaped vanes sits inside the glass, light gathers on its far side and a sharp highlight and a small window reflection catch the light; its shadow falls to the lower right, tinted by its glass, with a bright coloured caustic inside it. The tray has a mitred frame with bevelled edges and brass pins and a pale oak floor with a honeycomb of shallow cups. Small capitals read \"Parlour games · No. 4\" at the top left beside a live tilt readout (\"10.8°\"); \"Glass Marbles\" sits in a serif at the bottom over a line of copy and the hint \"Drag to tilt · Shake to scatter · Tap a marble\". Everything is drawn: no photos.") { GlassMarblesTrayDemo() },
    Block(slug = "kaleidoscope-twist", name = "Kaleidoscope Twist", category = "Playground", spec = "A kaleidoscope seen through a brass eyepiece: a fixed bezel and a knurled ring with an engraved index, around a round window. Inside, coloured glass beads (lit, with a caustic and a glint) and bevelled glass shards lie loose in a chamber over a frosted violet diffuser, and mirrors fold one wedge of it into a mandala of 6 to 12 segments, darkening towards the rim. Drag around the window to turn the chamber and the pieces tumble; pinch to change the number of mirror segments, shown in large figures under the eyepiece; tap to drop another bead where the finger is.") { KaleidoscopeTwistDemo() },
    Block(slug = "neon-sign-flicker", name = "Neon Sign Flicker", category = "Playground", spec = "A hand-bent neon sign hangs from one iron hook on two chains in front of a dark brick wall at night: \"open\" over \"late\" in rose and ice-blue script, beside an amber cocktail glass with a lime olive, the tubes mounted on a clear acrylic panel whose edges catch their light. A lit tube has a white-hot core, a glint along the glass and a soft layered halo; an unlit one shows its coated glass, and each word's ends are blacked out where the tube turns to its electrode. The bricks around the sign take the colour of whatever is lit, and the light moves across them as the sign swings. Tap a word to switch it on or off; drag the sign to swing it.") { NeonSignFlickerDemo() },
    Block(slug = "pendulum-wave", name = "Pendulum Wave", category = "Playground", spec = "Fifteen brass pendulums hang in a row from a walnut frame on a walnut table, each on a V of string, seen in perspective with soft shadows on the table and a thin warm light trail behind each bob. Their lengths are tuned so that, released together, they drift in and out of step: travelling waves, a snake, two and three interleaved rows, apparent chaos, and after thirty seconds the whole row comes back into one line. Drag sideways and a brass comb gathers the bobs and pulls them aside; let go to release them. A tap turns the camera to the next view (a three-quarter view that slowly sways, a view from above that shows the snake, and a view along the swing), morphing between them. \"Pendulum Wave\" and \"Fifteen bobs, one 30 s cycle\" sit above a hairline that fills over the cycle with the seconds since release; the views and \"Drag sideways to release · Tap to change view\" sit below.") { PendulumWaveDemo() },
    Block(slug = "tangram-snap", name = "Tangram Snap", category = "Playground", spec = "A tangram on a dark lacquered board: the seven classic pieces in exact proportion (two large triangles, a medium and two small ones, a square and a parallelogram) in vermilion, indigo, ochre, jade, plum, teal and cream lacquer over wood grain, with bevelled edges, a gloss across their upper left and soft shadows. The faint outline of a figure fills the top of the screen and the loose pieces wait in a felt-lined well below it. Small capitals read \"Tangram · No. 1 of 4\" over the figure's name in a serif (\"The Cat\") and the hint \"Drag · Tap to turn · Double-tap to flip\", with a live count (\"3 / 7\", \"In place\") at the top right; four small silhouettes along the bottom (a cat, a sailing boat, a runner, a swan) choose the figure, the current one in its own colour. When the last piece goes in, the figure becomes one solid shape in its colour and the line reads \"Seven pieces, one shape.\" Everything is drawn: no photos.") { TangramSnapDemo() },
    Block(slug = "bubble-wrap-pop", name = "Bubble Wrap Pop", category = "Playground", spec = "A sheet of bubble wrap over a soft pastel backdrop of peach, rose, lilac and sky that shows through the clear film. Each bubble is a glossy dome that magnifies the colours behind it, with a bright rim, a sharp window highlight and a small caustic beneath. Pressed, a bubble squashes and bulges, trembles, and pops into a crumpled flat film with a burst of tiny air rings; a slide pops a whole row, and the film's edge can be tugged. A rolling counter at the top shows how many are popped out of the total; when none are left a fresh sheet slides in. \"Press to pop · Slide across a row · Tug the edge\" sits below.") { BubbleWrapPopDemo() },
    Block(slug = "clay-press-blob", name = "Clay Press Blob", category = "Playground", spec = "A blob of satin modelling clay sits on a seamless paper sweep tinted with its own colour, like a tonal product shot: terracotta on peach paper, cobalt on pale blue. It is lit from the upper left, with a soft sheen that rides the shape, a darker rim toward the lower right, a fine grain, and contact shadows in the paper's deep tone. It is a soft body that keeps what you do to it for a while: a press sinks a dent with a fingerprint in it (pressed near the edge, it notches the rim), a drag pulls out a lump, a flick throws it against the side of the stage where it squashes into a rounded slab and wobbles back, and a pinch squeezes it. A tap recolours the clay, the new colour spreading from the finger while the paper and the ink turn with it. \"Clay Study\" and \"Nº 04\" sit above the clay's name in a large bold serif, and \"Press · Pull · Flick · Pinch · Tap to recolour\" below.") { ClayPressBlobDemo() },
    Block(slug = "cloth-flag-mesh", name = "Cloth Flag Mesh", category = "Playground", spec = "An oxblood banner flying from a brushed metal flagpole with a gold ball, over a still sea at dusk with a low headland on the horizon; the pole's foot fades into the dark water above the caption. The cloth is a plain weave of fine threads with an ivory hoist striped in oxblood, a gold border and an invented device — a gold sun of sixteen rays in a ring over three waves — and its folds catch a satin sheen from the upper left over a soft shade behind it. Below sit \"HOUSE BANNER · NO. 7\", the title \"Saltmarsh Regatta\" in a serif and a line of copy, with a wind readout in knots on the right that reads \"WIND\" or \"CALM\"; under them a hint (\"Drag the cloth · Swipe for a gust · Tap to still the wind\") and a Calm / Breeze / Gale switch whose pill slides to the chosen wind. Dragging grabs the cloth at the nearest point and pulls it, letting go lets it billow back out, a fast swipe past it gusts the wind, and a tap stills the wind or brings it back.") { ClothFlagMeshDemo() },
    Block(slug = "domino-chain", name = "Domino Chain", category = "Playground", spec = "A spiral of ivory dominoes stands on a green felt table seen from above at an angle, lit by a lamp so each tile has a lit face, darker sides, pips and a centre groove on its front and a soft shadow on the felt; a walnut rail closes the table at the top under \"Table No. 4\" and \"Domino Run\". Tapping the first tile, which glows faintly at its foot, or flicking any tile along the run topples it, and the fall runs down the spiral tile by tile with soft clicks until they lie in a leaning ribbon. Dragging across the felt traces a chalk line and lays a new run along it, the tiles popping up in turn while the old run sinks away; sweeping across a fallen run stands it back up, last tile first.") { DominoChainDemo() },
    Block(slug = "firefly-swarm", name = "Firefly Swarm", category = "Playground", spec = "A meadow at dusk: a deep blue sky fading to a warm amber glow behind a tree line of round crowns and a few pointed conifers, a thin crescent moon, faint twinkling stars, and three banks of grass silhouettes in front, their tips catching the last light. A hundred and fifty fireflies drift and flock over the meadow, each blinking with a green-gold glow that turns paler and warmer against the bright sky. Touching gathers them into a swirling orbit round the finger, which they follow; lifting lets them go; a fast flick scatters them; holding still calms them and pulls their blinking into waves of light that roll outward from the finger. The grass leans where the swarm passes low. A line of hints runs along the bottom: \"Touch to gather · Flick to scatter · Hold to sync\".") { FireflySwarmDemo() },
    Block(slug = "fractal-tree-bloom", name = "Fractal Tree Bloom", category = "Playground", spec = "A fractal tree on a small green mound under a soft pink sky with pale hills behind it, \"Seed No. 27\" and the season's name in the top corner. From a glossy seed the tree grows branch by branch, trunk first and twigs last, then opens into pink and white blossoms that sway in a light breeze. Each tap turns the season: summer greens the crown with leaves under a blue sky, autumn turns them gold, orange and crimson and lets them drift down, and winter leaves the branches bare against a slate sky, with snow falling, settling along the tops of the boughs and whitening the ground. Dragging across bends the wind, the trunk first and the twigs after; holding a finger down draws the tree back into its seed and grows the same tree again.") { FractalTreeBloomDemo() },
    Block(slug = "marbling-comb", name = "Marbling Comb", category = "Playground", spec = "Paper marbling on a dark lapis tray of size. Each tap drops paint that spreads into a disc and pushes every colour already floating outwards, so drops on drops become rings; holding a finger still keeps dripping rings in turn. Dragging a steel stylus, or a walnut comb whose tines span the tray, pulls the paint into feathered, combed patterns with a fine dark edge on every colour, under a soft sheen and grain. A row of seven paints (bone, madder, ochre, cobalt, sage, rose, ink), a Stylus/Comb switch and a Print button sit at the bottom; Print lays a cream sheet over the tray and peels it back from its corner to show the pattern taken up on its underside, leaving the size clean.") { MarblingCombDemo() },
    Block(slug = "pluck-string-harp", name = "Pluck String Harp", category = "Playground", spec = "A small harp drawn in warm varnished wood stands in a dark room: a carved column with gilt rings, a swan-necked neck and a tapering soundbox, with eight strings tuned to C major, the longest on the left. Dragging across the strings plucks them: each one catches on the finger, bends into a sharp V, then slips free and rings as a glowing standing wave, its vibration a faint golden blur that brightens the string and the room and fades as it dies, while the strings beside it shimmer in sympathy. The note's name rises from where it was plucked in an italic serif and fades, and the fingertip leaves a short trail of light, so a fast strum sweeps a wave of glow across the harp.") { PluckStringHarpDemo() },
    Block(slug = "pull-cord-light", name = "Pull Cord Light", category = "Playground", spec = "A dark bedroom at dusk, the photo graded to cool night blue, with a drawn pendant lamp hanging from the ceiling: a matte dome shade, a glass bulb and a pull cord with a wooden bead, simulated as a rope of links. Pulling the cord down stretches it; letting go past the click switches the lamp on: the bulb glows, a warm cone of light fades in under the shade and the same room comes up in lamplight with a soft flicker, brightest where the cone lands, while the cord bounces and swings. Pull again to switch it off. The lamp itself can be grabbed and swung, and the cone and the pool of light sweep the room with it. \"Lights off\" and \"Lights on\" crossfade at the bottom.") { PullCordLightDemo() },
    Block(slug = "spirograph-draw", name = "Spirograph Draw", category = "Playground", spec = "A spirograph on a pad of cream drawing paper lying on a dark desk: a clear plastic ring with 96 inward teeth, printed ticks and its size, and inside it a tinted translucent gear with five pen holes and a pen standing in one of them. Dragging round the ring rolls the gear and the pen draws a hypotrochoid in real ink that builds up into a rosette, while the rest of the closed pattern shows faintly in pencil; until anything is drawn a small arrow sweeps round the ring to show the way. A header reads \"Spirograph\" with the gear, hole and loop count (\"40-tooth gear · hole 3 · 12 loops\") and a Clear button; under the pad a hint and three rows of controls pick the gear (30, 40, 56 or 72 teeth), the pen hole (1–5) and the ink (ultramarine, vermilion, viridian or graphite). Inks overlap like real ink, a tap on the paper moves the pen to the next hole, and Clear tears the top sheet off the pad.") { SpirographDrawDemo() },
    Block(slug = "truchet-wave-tiles", name = "Truchet Wave Tiles", category = "Playground", spec = "A full-screen grid of Truchet tiles, eight across, forming continuous flowing lines in two colours: thick glazed ribbons of quarter-circle arcs in bone on deep ink. Tiles turn a quarter at a time, lifting off the grid as slabs with a soft shadow, in waves that ring out from a tap or follow the finger as it drags, so the line pattern keeps re-forming. A glass segmented control at the bottom morphs every tile between Arcs, Diagonals (a maze of straight lines) and Triangles (half-square tiles filled in), and a round swatch beside it grows the next palette (kiln orange, moss and ochre, cobalt on ivory) out across the screen as a circle. A fine print grain lies over everything.") { TruchetWaveTilesDemo() },
    Block(slug = "zen-sand-garden", name = "Zen Sand Garden", category = "Playground", spec = "A raked sand garden seen from above, in warm late light: pale, finely grained sand, three rounded stones (a large blue-grey one, a warm granite one and a small dark one) with patchy moss at their feet, and long soft shadows falling away from a low sun. Dragging a finger pulls a small wooden rake through the sand, leaving five parallel grooves with ridges between them that bend round the stones; tapping a stone sends rings of grooves out round it; a two-finger swipe pushes a soft bank of sand across the garden and leaves it level again, with faint broom streaks. The light drifts slowly between pale gold and a rosier tone, and a line of hints runs along the bottom: \"Drag to rake · Tap a stone · Two fingers to smooth\".") { ZenSandGardenDemo() },
    Block(slug = "health-age-dial", name = "Health Age Dial", category = "Progress", spec = "A longevity screen that measures health age against actual age on a gradient dial. The dot rewinds from the actual-age tick to the health age while the number rolls like an odometer, then the dial flies into the Health Age chip as the page scrolls to a history chart and the factors raising it. Drag the dot round the dial to try a what-if age.") { HealthAgeDialDemo() },
    Block(slug = "orbit-import", name = "Orbit Import", category = "Progress", spec = "A dark import sheet turns clipboard instructions into a cloud of luminous particles orbiting in depth. Invented subscriptions appear for selection, then their icons fly onto a calendar along a curved route. Tap to advance or drag to scrub the complete import story.") { OrbitImportDemo() },
    Block(slug = "geode-focus-reward", name = "Geode Focus Reward", category = "Progress", spec = "A quiet focus reward holds a rough charcoal stone above a crescent of light, with an amber-green mineral already enclosed inside. Hold or drag upward to extend luminous cracks and peel twelve thick shell pieces away, then keep the revealed Mosslight stone in a local collection. The dark reward card keeps its title, seven-session context and result controls anchored around the material.") { GeodeFocusRewardDemo() },
    Block(slug = "stitch-weave-preview", name = "Stitch Weave Preview", category = "Progress", spec = "A soft knit studio grows a cream swatch from 52 suspended yarns, forming interlocking courses and a charcoal Sprig motif as each new row is made. Drag the leading edge to knit or unknit, switch the pattern and yarn locally, and save the completed 48-row preview. A silver-grey full-screen composition keeps progress and controls below the material.") { StitchWeavePreviewDemo() },
    Block(slug = "sand-hourglass", name = "Sand Hourglass", category = "Progress", spec = "A focus timer with an hourglass for a clock, standing on a linen-coloured table in afternoon light: a frameless glass between two pale oak caps, its bulbs catching white streaks and the reflection of a window, holding 2,300 grains of terracotta sand, each a tiny lit bead. The glass throws a long, soft shadow across the table to the right, with a warm patch of light where the sun passes through an empty bulb. Below it sit a large timer and a line of text, and at the bottom a ruler of minutes under an orange needle. Slide the ruler to choose from 1 to 60 minutes, then turn the glass over by dragging around it, twisting it with two fingers or tapping it: the sand runs through the neck at the pace that empties the top bulb on time, the timer counts down what is left and says when the session ends, and when the last grain lands a band of light crosses the glass and the timer reads \"Well done\".") { SandHourglassDemo() },
    Block(slug = "horizon-upload", name = "Horizon Upload", category = "Progress", spec = "A file-upload card of liquid glass floating over a dawn seen from orbit. The card holds a glass file with a riveted badge, its name and size, a glass close button, and a recessed well with a status coin, a rolling percentage and a bar that is a tube of light. The planet's horizon behind the card is a second progress bar: light is born behind the pane and spreads along the limb as the upload advances, and every chunk that arrives sends a wave along it. At 100 % the card lifts off the horizon, the sun breaks out beneath it, a band of light sweeps up through the glass and the badge turns over from TXT to a check. The card can be dragged; the dawn stays still, so its light slides through the lens of the pane's edge.") { HorizonUploadDemo() },
    Block(slug = "activity-rings", name = "Activity Rings", category = "Progress", spec = "A black \"Today\" health widget on a grey screen, with rows for sleep time (7h 2m, up 12%) and average heart rate (56 bpm) beside a blue moon and a red heart icon. Three thick concentric rings in blue, green and red, cropped by the card's lower right corner, each end in a badge with its number (31, 84, 53) around a white disc that shows the score, 16 PAI.") { ActivityRingsDemo() },
    Block(slug = "barcode-progress", name = "Barcode Progress", category = "Progress", spec = "A black progress card on a light grey screen with a title, a one-line caption, a large percentage (66%) next to an outlined chip showing the change (30%, with an up-right arrow) and the words \"vs. the last period\". Below is a row of 33 vertical bars like a barcode, white for the completed share and dark grey for the rest, and a three-dot More button sits in the top corner.") { BarcodeProgressDemo() },
    Block(slug = "battery-capsules", name = "Battery Capsules", category = "Progress", spec = "An earbuds battery widget on a blue screen, in a light and a dark version: the device name (Alex's Buds Pro), the mode (Noise Cancellation) and an audio-output icon above three capsules for the left bud, the case and the right bud. Each capsule shows its percentage (80%, 20%, 10%) over a fill in green, yellow or red, with a round icon disc at its foot.") { BatteryCapsulesDemo() },
    Block(slug = "budget-bar", name = "Budget Bar", category = "Progress", spec = "A white monthly budget card on a near-white screen: a grey title and a dark month chip (SEP), the limit in large type (\$ 8,000), and a thin progress bar whose fill runs from aqua to near-black. The amounts spent (\$2,886) and remaining (\$5,114) sit under the two ends of the bar, above a dark pill button labelled View More.") { BudgetBarDemo() },
    Block(slug = "charge-pill-progress", name = "Charge Pill Progress", category = "Progress", spec = "A charging indicator made of two black pills on a light grey screen. The compact pill shows a green bolt and the charge level (76); the larger pill below holds a grey track whose green fill ends in a glowing green knob with a bolt and the level, with the estimated time left (~15m) at its right.") { ChargePillProgressDemo() },
    Block(slug = "charge-wave-circle", name = "Charge Wave Circle", category = "Progress", spec = "A dark green charging screen: a glowing \"Speed up charging\" chip with a yellow bolt, then a circular gauge with a bright green ring, a white bolt, the level in large digits (18%) and green liquid with a wavy surface filling it from the bottom. Below sit three mode icons (snowflake, plug, rocket) with the plug lit, and two read-outs: the time and date, and the time to a full charge (3 H 6 M).") { ChargeWaveCircleDemo() },
    Block(slug = "data-usage-ring", name = "Data Usage Ring", category = "Progress", spec = "A white data-plan summary card on a light grey screen. A thick green ring sits on a recessed grey dial with twelve tick dots, around a raised white hub that shows the share used (36%) and the amount (3.6GB / 10GB); a footer line gives the renewal date and an underlined Edit link.") { DataUsageRingDemo() },
    Block(slug = "delivery-steps-progress", name = "Delivery Steps Progress", category = "Progress", spec = "A deep blue order-tracking card on a white screen, with a headline for the current stage (Driver Heading to Laundry) and an ETA, five round steps with icons (parcel, garment, washer, van, home) joined by a line, and a driver row with an avatar tile, name, vehicle, plate, and call and message buttons. Reached steps are bright blue with white icons, the rest are dark, and the lit part of the line ends in a glowing head.") { DeliveryStepsProgressDemo() },
    Block(slug = "flight-progress", name = "Flight Progress", category = "Progress", spec = "A black flight-status card on a black screen, shown with a lime and an orange accent: the origin and destination airports (NPT Northport, BVW Bayview) with an arrow between them, and an ETA box with the time zone, a note and a round swap button. Below is a tall pill-shaped progress bar with a glossy coloured fill, a small white plane at its leading edge and the time left (-7H 01M) at the right, and fine dust dots are scattered along the top of the card.") { FlightProgressDemo() },
    Block(slug = "goal-score-bar", name = "Goal Score Bar", category = "Progress", spec = "A leaderboard live activity in black on a light grey screen: a compact pill with the score (8814), an orange trophy and the rank (2), and below it a rounded panel with the score in large digits against the goal (/ 10 000) and a trophy with the place (2nd). The panel also holds a thin orange progress line, three friends' avatars with orange progress rings and an All friends button.") { GoalScoreBarDemo() },
    Block(slug = "habit-ring", name = "Habit Ring", category = "Progress", spec = "A dark habit-tracker summary. A raised charcoal card holds a large orange ring with the constancy percentage (82%, labelled CONSTANCE) in its centre, flanked by two small orange rings for the week (90) and the day (53), over a two-line caption; three stat tiles below show check-ins (202), best streak (18 j) and perfect days (14).") { HabitRingDemo() },
    Block(slug = "milestone-stepper", name = "Milestone Stepper", category = "Progress", spec = "A light grey onboarding card titled \"You're almost there!\" with a white speech bubble (a funding-goal field with green check and cross badges) above a pill-shaped stepper of five milestones: Create Project, Add Media, Set Goals, Team and Launch. The fill runs from near-black through green to mint and stops just short of the next milestone; reached milestones carry a tick (the newest mint, the one before deep green, older ones white), the rest are grey, and a tip line sits at the bottom.") { MilestoneStepperDemo() },
    Block(slug = "mission-glow-progress", name = "Mission Glow Progress", category = "Progress", spec = "A dark glass card over an orange and blue glow on a near-black screen, with a round red mission badge, the message \"Good job! Just complete 3 more missions to advance to the next level.\" and a lime progress bar with a white-hot glowing head. Dots on the track mark the missions still to do, the next one lit lime, and captions under the bar count the missions completed (4) and remaining (3).") { MissionGlowProgressDemo() },
    Block(slug = "noise-level-meter", name = "Noise Level Meter", category = "Progress", spec = "A light square widget that reads the current noise level, shown twice on a grey-blue screen: at 40 dB in green and at 60 dB in yellow. It has a large dB figure, a three-bar signal icon, and a Low-to-High trough holding a diagonally striped block that fills to the level on a 120 dB scale, with a thin needle at its edge, the current 30 dB band printed inside it and 120 at the far end.") { NoiseLevelMeterDemo() },
    Block(slug = "playback-dial", name = "Playback Dial", category = "Progress", spec = "A dark call-notes card on a black screen (title, author, a recording row with a violet play button, a waveform and the length 32:42, and a summary) that fades out towards its foot, with a round violet glass dial floating over it as the playback indicator. The dial has a dark starry face with tick marks, a thin hand that reads the elapsed minutes on a 60-minute face, a comet-shaped violet wedge with a bright leading edge, and a white hub.") { PlaybackDialDemo() },
    Block(slug = "power-rate-segments", name = "Power Rate Segments", category = "Progress", spec = "The lower part of a dark glass settings menu on a near-black screen, lit by streaks of green light that fan out from its bottom right corner. Under a selected \"Power Usage\" row, a green-edged panel shows a chip icon, a \"24.31%\" counter, a \"-14.83%\" change chip with a pulsing cursor bar, the label \"GPU Actual Power Rate\" and a row of 25 small segments lit bright green in proportion to the rate; a \"Settings\" row sits below.") { PowerRateSegmentsDemo() },
    Block(slug = "profit-track-progress", name = "Profit Track Progress", category = "Progress", spec = "A two-layer asset card on an off-white screen. The white top row shows a car thumbnail, an \"Active\" badge, the name \"Vela GT 2025\", a price in blue, an estimated APY, a \"1 UNIT\" tag and a round blue chevron button; the dark panel below shows \"PROFIT PROGRESS\", a percentage (\"135%\"), a caption, an infinity sign and a track whose blue filled part ends in a round knob while the part still ahead warms from orange to yellow towards a flame badge at the far end.") { ProfitTrackProgressDemo() },
    Block(slug = "project-progress-card", name = "Project Progress Card", category = "Progress", spec = "A dark grey project card on a pale screen: a spinner glyph, the title \"Project Progress\" with an \"Onboarding prototype\" tag, a large \"65%\" and a pill-shaped bar whose lime-to-mint fill glows and whose track carries the due date (\"Due July 28\"). Below are a \"Collaborators 3\" label, three rounded-square avatars with initials and a \"More details\" pill button.") { ProjectProgressCardDemo() },
    Block(slug = "recruiter-steps", name = "Recruiter Steps", category = "Progress", spec = "A black rounded panel on a blue screen, styled as an agent's live activity. The title \"Recruiter\" sits opposite three overlapping round tool icons (mail, globe, document); below, five step circles are joined by short dashes, finished steps filled bright blue with a dark check and the others drawn as dim blue rings; a grey status line names the current task (\"Writing summary...\") beside a count (\"3 of 5\").") { RecruiterStepsDemo() },
    Block(slug = "rider-track-progress", name = "Rider Track Progress", category = "Progress", spec = "A black order-tracking panel on a dark screen, with a pale-to-blue glow behind it. The top row names the restaurant and the order (\"Food Hub\", \"Pizza Pepperoni\") opposite the price and \"COD\"; across the middle a courier on a blue scooter rides a road whose travelled part is lit blue to green under a teal glow; the bottom row shows the courier's initials and name, \"Will arrive in 5min\" and a round call button.") { RiderTrackProgressDemo() },
    Block(slug = "ruler-dial", name = "Ruler Dial", category = "Progress", spec = "A black rounded panel on a light grey screen showing a fan of ruler ticks under a fixed white needle, with the current whole number (0 to 100) in white above it. The ticks are tinted blue on the left, grey in the middle and gold on the right, and fade out at both edges.") { RulerDialDemo() },
    Block(slug = "signal-strength-bar", name = "Signal Strength Bar", category = "Progress", spec = "A square-cornered dark instrument panel with white corner brackets, set over blurred streaks of sky and foliage on a green screen. A header reads \"Threshold / Signal strength\" with the reading repeated in a yellow chip; below are two large figures, signal strength (\"56.2%\", with a green \"+32%\") and noise ratio (\"43.8%\"), a yellow bar on a 60-tick scale marked 0% to 100%, and four small channel icons next to a count of inputs.") { SignalStrengthBarDemo() },
    Block(slug = "spending-orbit", name = "Spending Orbit", category = "Progress", spec = "A dark glass \"TODAY SPENDING\" tile on a charcoal screen, wrapped by a thin circular track that carries two opposite white arcs. The tile shows the amount spent (\"\$192.45\"), its share of the daily budget (\"78%\"), a bar of 27 ticks coloured by category (orange, purple, blue, green) and a list of four categories with their amounts: Groceries, Entertainment, Transportation and Utilities.") { SpendingOrbitDemo() },
    Block(slug = "step-planner-progress", name = "Step Planner Progress", category = "Progress", spec = "A dark \"Progress & Planning\" card on a black screen. It has a three-tab segmented control (Setup, Timeline, Goals), a \"STEP 3 OF 5\" row with \"40% Complete\" in green, a five-segment bar (finished segments green, the current one outlined in green, the rest grey), a checklist panel that shows three of the five steps with ticked, current and upcoming markers, and a footer naming the current step beside a \"CURRENT\" badge.") { StepPlannerProgressDemo() },
    Block(slug = "story-progress-bars", name = "Story Progress Bars", category = "Progress", spec = "A dark onboarding card on a near-black screen with four thin story-style progress lines across the top and a round pause button below its bottom right corner. Each of the four stories (Workspaces, Integrations, Automations, Insights) shows four small app tiles floating over a glowing horizon with a few stars, a title, a two-line description and a pill-shaped call-to-action.") { StoryProgressBarsDemo() },
    Block(slug = "streak-steps-widget", name = "Streak Steps Widget", category = "Progress", spec = "A dark square widget with heavily rounded corners on a near-black screen. A red-orange flame with a white core sits beside \"STREAK 32 DAYS\" opposite a footprint icon; a row of seven discs for Mon to Sun shows three ticked in green, today as a green progress ring and the rest empty; at the bottom are \"STEPS\", the count (\"6825/10,000\"), a percentage (\"68%\") and a green bar with a soft glow.") { StreakStepsWidgetDemo() },
    Block(slug = "stress-arc-gauge", name = "Stress Arc Gauge", category = "Progress", spec = "A dark grey stress card on a white screen, crossed by a wide shallow arc with a round marker on it; the arc glows behind the marker and is faint ahead of it. A person icon and \"Stress\" sit top left with an arrow button top right, and the centre shows \"Your stress level\", a large percentage (\"85%\") and a chip naming the state (Low, Balanced or High). The line, the text, an ambient light and the card's edge glow are green at calm levels and turn through yellow to orange-red as the level rises.") { StressArcGaugeDemo() },
    Block(slug = "timer-border-progress", name = "Timer Border Progress", category = "Progress", spec = "A timer shown as a live activity on a light grey screen: a compact black pill with a small orange ring and the time left, above an expanded black panel whose border is a thick orange stroke that shrinks as the time runs out. Inside the panel are a bell with the alarm time (\"14:44\") in the gap of the border, the time left in large white digits (\"13:12\"), the label \"Timer\", a grey pause button on the left and a dark red cancel button on the right.") { TimerBorderProgressDemo() },
    Block(slug = "transit-route-progress", name = "Transit Route Progress", category = "Progress", spec = "A black live-activity card on a light grey screen for a train ride. A lime train icon and \"Circle Line\" sit opposite a yellow chip with the time to the next stop (\"2 min\", \"1 min\" or \"now\"); below, a lime route bar with three station dots is lit up to a ringed marker with a white centre, and the station names Harbor, Midtown and Parkway sit under it, bright once reached and dim before.") { TransitRouteProgressDemo() },
    Block(slug = "water-intake-fill", name = "Water Intake Fill", category = "Progress", spec = "A hydration tracker card on a light green screen: a deep blue tank that fills with rippling water as drinks are logged, with the outline of a tumbler ghosted behind it. The heading reads \"Water today: 650 of 2,000 ml\", a large thin percentage (\"33%\") stands at the waterline, and two quick-add chips (\"150 ml\", \"250 ml\") and a yellow \"Custom\" pill sit above a lavender \"Today\" panel listing the two latest drinks with their times.") { WaterIntakeFillDemo() },
    Block(slug = "saved-places-map", name = "Saved Places Map", category = "Sheets", spec = "A saved-places list: a real New York map with café markers and filter chips under a progressive blur, behind a bottom sheet holding the list cover, its counts and owner, four action tiles and the first place. Pulling the sheet up pitches the map into 3D: the cafés stand up as pins with light beams and long shadows, and the map's scattered saves and likes gather into a count bubble on each pin. Ticking a place marks it visited on the list and on the map.") { SavedPlacesMapDemo() },
    Block(slug = "event-pass-share", name = "Event Pass Share", category = "Sheets", spec = "A dark glass sharing sheet floats over a slow emerald aurora: the stage is a frosted window onto the light, and a smoked-glass event pass holds an editorial community poster. Tilt the pass with a finger or turn it over to a scannable QR containing the event details; close, copy and share are Liquid Glass controls that pick up the colour behind them; copy details or export the invitation through the native share sheet.") { EventPassShareDemo() },
    Block(slug = "prism-unseal-sheet", name = "Prism Unseal Sheet", category = "Sheets", spec = "A card-delivery sheet over a dark everyday wallet. A silver package hinges open to a rainbow interior, then a brushed silver card lifts out and the package disappears, leaving the card alone in the ready state. Drag the package to unseal it or use the primary action.") { PrismUnsealSheetDemo() },
    Block(slug = "cart-fly-stepper", name = "Flying Items Cart Stepper", category = "Sheets", spec = "A product sheet with a quantity stepper and a basket. Every tap on \"+\" launches a small tile with the dish on it from the button along an arc into the basket; in a burst several tiles are in the air at once, the basket kicks as each one lands, and both counts roll to their new numbers. \"-\" lowers the stepper only.") { CartFlyStepperDemo() },
    Block(slug = "detent-method-sheet", name = "Detent Method Sheet", category = "Sheets", spec = "A 'Select your source of fund' wallet page (balance, two linked bank accounts with monogram logos and a Primary badge, recent top-ups, an instant top-up note) with an Add money button that raises a sheet of transfer methods. The sheet rests at a middle and a large detent and follows a finger; the page behind scales and darkens with the sheet's position, and at the large detent the rows grow and a fifth one appears. Each method is a card with an icon well, a title, a speed line with a bolt for instant ones and a fee pill. Tapping a method fills its tick and drops the sheet back to the middle.") { DetentMethodSheetDemo() },
    Block(slug = "dock-expand-sheet", name = "Dock Expand Sheet", category = "Sheets", spec = "A dawn-sky screen (the sun on its arc, a glowing horizon, a ruler of hours and the day's sunrise, golden hour, noon and sunset times) with a dock of three glass controls and a tooltip tied to the sun button. Pressing the button merges the dock into one Modes pill that grows upward into a full-screen list of modes, each with a tinted icon well and a caption, with the sky behind it scaling back and fading; closing runs the motion in reverse. A second tooltip and a ruler whose ticks light up in turn follow.") { DockExpandSheetDemo() },
    Block(slug = "hold-stop-sheet", name = "Hold Stop Sheet", category = "Sheets", spec = "A focus-timer screen with a large 05:00 over a dense, overlapping pile of cartoon tomatoes (shaded red and yellow ones with leafy tops, blushing faces and a few oranges) that fills the bottom of the screen around a dark 'Start Focus' pill. Start Focus drops the pile off the screen and turns the page peach while a five-minute countdown begins. Holding the footer fills a line; completing it resets the timer, rains the tomatoes back in from above behind a dimmed screen and raises a warning card with a Got it button.") { HoldStopSheetDemo() },
    Block(slug = "icon-morph-sheet", name = "Icon Morph Sheet", category = "Sheets", spec = "A payment app's tips sheet, for an invented wallet called \"noku\": a dark confirmation page (\"To Mina Park, \$24.00, send it now?\") with a tall bottom sheet in four steps. Each step has a centred title and one or two lines of copy, four pager dots, a full-width yellow pill button, and in the middle a 3D clay icon: a grey zero with gold coins, a white coin that flips into a red siren with a shield, a blue envelope that opens on a note and two emoji, a yellow bank passbook with a green check. The icon is not four pictures: it is one object drawn by a ray-marching shader, and a step change turns it into the next one in front of you.") { IconMorphSheetDemo() },
    Block(slug = "jelly-sheet", name = "Jelly Sheet", category = "Sheets", spec = "A hotel page: a tall photo of palms over a pool, with frosted back, share and heart buttons on top and a warm paper booking sheet over its lower part. The sheet's top edge is a soft membrane: dragged, the edge under the finger leads while the rest trails behind in a gentle tilt, and when the sheet comes to rest the edge swells and settles in a few soft, damped wobbles, the grabber riding, tilting and stretching with it; a tap on the head sends a small ripple out from under the finger. It rests at three heights: a peek with the hotel's name, rating and place, half with the stay (check-in, check-out, guests) and the rooms, and full with what is included and a line about the place, while a footer with the nightly price and a terracotta Reserve button stays put. Fully open, the photo behind blurs, darkens and sinks back with rounded corners.") { JellySheetDemo() },
    Block(slug = "key-reveal-sheet", name = "Key Reveal Sheet", category = "Sheets", spec = "A wallet page (a glossy amber wallet card with a heart badge, Copy Address and Customize, grouped wallet settings with tinted icon tiles, and recent activity) with a floating sheet that warns about the private key. Reveal scans a face, swaps the warning for the twelve numbered words of the key, which unblur from left to right behind a glowing cyan edge while a light runs once around their box; tapping the key copies it and shows a Copied chip. Cancel or the X dismisses the sheet.") { KeyRevealSheetDemo() },
    Block(slug = "morphing-mode-sheet", name = "Morphing Mode Sheet", category = "Sheets", spec = "An assistant's home screen (avatar, a wordmark with a PRO tag, a prompt card with a caret, suggestion chips and a drawn light keyboard) with a floating sheet over it. The sheet opens as a short list of modes and, when the model at the right of the first row is touched, grows upward in one continuous morph into a tall list of models; a pick shrinks it back. The keyboard drops as the sheet rises and comes back when it closes, the page behind blurs and dims while the sheet is up, a selected row takes a teal fill, and an incognito switch slides its knob.") { MorphingModeSheetDemo() },
    Block(slug = "orbit-picks-sheet", name = "Orbit Picks Sheet", category = "Sheets", spec = "A Discover page (an avatar and a 30-point title, a lavender Today's Top Picks banner with a count, two rows of interest chips, an empty Chats card with a Find New People button and a tab bar) with a full-height sheet over it, stacked on a second sheet edge. Tapping the banner raises the sheet while the page recedes; a badge pops in on a lavender halo, a ring draws round it and a dozen icon discs spiral in and orbit it, then are pulled into the badge, which rises and shrinks to head a card of people: a portrait in a gradient ring, name and rating, a compatibility well, interest chips and a Chat button. The card swipes sideways between profiles with page dots that stretch.") { OrbitPicksSheetDemo() },
    Block(slug = "placeholder-reveal-sheet", name = "Placeholder Reveal Sheet", category = "Sheets", spec = "A dark page of scheduled automations (titles, descriptions, times and a RUNNING or PAUSED status) with a 'Generate cards' button. The sheet that rises floats inside the screen's corners, sky blue with a darker lip, and holds a dashed placeholder card that wobbles while something is made under a large 'Preparing' heading; then a white glow swells inside it, the sheet turns white and three teal gradient cards fan out of the placeholder (the front one with a title, a subtitle and three bullets) above a Done button.") { PlaceholderRevealSheetDemo() },
    Block(slug = "sheet-card-handoff", name = "Sheet Card Handoff", category = "Sheets", spec = "A Today task list (four coloured task cards with times, progress dashes and status chips, a dashed New Task well and a floating tab bar) with a bottom sheet over it. The sheet shows an ALL SET title, a caption, a fan of three printed cards and a Done button; pressing Done drops the sheet, and the front card flies out of it into the first slot of the list, growing from a small card into a full-width task while the rest of the list makes room. A task counter, a NEW badge and the sheet's drag-down dismissal complete the screen.") { SheetCardHandoffDemo() },
    Block(slug = "stage-card-sheet", name = "Stage Card Sheet", category = "Sheets", spec = "A project page presented as a sheet over a dark screen, with the page it came from peeking out behind. Its artwork is a large glowing gradient card above a black 'Enable link sharing' pill. Pressing the pill turns it into a spinner, then the artwork shrinks into a small cover while rays of light and glints sweep across it and a sharing panel rises from behind it: copy and share buttons, reset link, 'Make project private', and permission rows with icon tiles and switches. 'Make project private' asks in an alert, and Continue folds the page back.") { StageCardSheetDemo() },
    Block(slug = "widget-guide-sheet", name = "Widget Guide Sheet", category = "Sheets", spec = "A guide in a sheet over a dimmed countdown app (an Up next title and six coloured event rows with days to go). A miniature home screen, a textured blue wallpaper with labelled app icons, a Search pill and a dock, shows five slides on how to add a widget: an empty dashed slot, a plus button, a picker of countdown tiles that rises inside the picture, widgets that drop in with a Done pill, and a blurred page with an Edit Widget menu. The caption cross-fades, the current page dot stretches, and chevrons, dots and a swipe move between slides.") { WidgetGuideSheetDemo() },
    Block(slug = "fabric-paywall-sheet", name = "Fabric Paywall Sheet", category = "Sheets", spec = "A subscription paywall in a bottom sheet. A Purchase button opens a sheet with the headline \"One price. One plan\", a Yearly/Monthly switch with a \"Save 25%\" badge, a card of waving fabric with the price on it, five benefits and a Start free trial button.") { FabricPaywallSheetDemo() },
    Block(slug = "liquid-folder-year", name = "Liquid Folder Year", category = "Splash", spec = "A yearbook welcome for the invented Vela app on near-black. A violet folder gains a luminous edge, liquefies into a glossy turquoise-and-purple mass and reforms as rounded tubular 2026 numerals. A signed-distance surface morph and moving specular highlights make the transition continuous.") { LiquidFolderYearDemo() },
    Block(slug = "farli-dot-splash", name = "Farli Dot Splash", category = "Splash", spec = "A vermilion splash for the invented travel app Farli. A white route mark unfolds into a wordmark, condenses to a dot, drops and launches upward to open a circular window onto a travel feed with bundled destination photography. Drag to scrub the same sequence or tap to launch it.") { FarliDotSplashDemo() },
    Block(slug = "cosmic-drift-splash", name = "Cosmic Drift Splash", category = "Splash", spec = "The launch of Orrery, an invented calm web browser: the camera flies forward through a field of big glossy planets in ember, cream, teal and dusty blue, with soft key light, specular highlights, coloured rim light, depth-of-field blur and sparkling dust streaks, until the field spirals away into a twinkling starfield. A white dot swells into a blob that morphs into the Orrery mark (a planet, two orbits that draw themselves and a moon), the backdrop lifts to graphite, the lowercase wordmark blurs into focus over a tagline, and a teal Get started pill fades in. Drag to fly through the planets; tap to skip to the end card.") { CosmicDriftSplashDemo() },
    Block(slug = "glow-search-splash", name = "Glow Search Splash", category = "Splash", spec = "A black launch screen for an invented visual-search app: a white tag mark squeezes into a blinking caret, which blooms with a pink-to-violet streak and a prismatic glow into a search line, just the typed placeholder and its caret on black. Vivid code-drawn art cards (glossy blobs, flowers, landscapes, big-type posters, 3D rings and pills) bloom out of it and drift upward in two loose, staggered columns, some bleeding off the edges, while the placeholder cycles through anything, illustration, typography and 3D shapes, each with its own set of cards; then everything folds back into the mark.") { GlowSearchSplashDemo() },
    Block(slug = "mist-glass-splash", name = "Mist Glass Splash", category = "Splash", spec = "A full-screen lavender mist splash for the invented wellbeing app Velune. A white ribbon draws itself inside a translucent glass tile, which rises and shrinks to make room for a quiet welcome and a white pill action. Dragging scrubs the drawing, glass movement and welcome together.") { MistGlassSplashDemo() },
    Block(slug = "particle-fold-splash", name = "Particle Fold Splash", category = "Splash", spec = "A plane of luminous points folds into a rotating perspective cube for the invented creative app Forme. Depth-sensitive brightness and size reveal the front faces and edges while a calm welcome stays readable. Drag to fold, turn and unfold the particle structure.") { ParticleFoldSplashDemo() },
    Block(slug = "petal-burst-splash", name = "Petal Burst Splash", category = "Splash", spec = "A warm white splash with a small coral flower for the invented connection app Flori. Six rounded petals turn and expand into a full-screen peach-to-pink field, revealing a white wordmark, a short welcome and a pill action. Dragging across the screen scrubs the same bloom and aperture.") { PetalBurstSplashDemo() },
    Block(slug = "sketch-coffee-splash", name = "Sketch Coffee Splash", category = "Splash", spec = "A launch screen for an invented coffee shop, Inkpot Coffee Co., drawn entirely as white hand-inked line art on ultramarine. The welcome reads \"Welcome to our coffee haven!\" with \"haven!\" in a handwritten marker, a small address and handwritten opening hours, a round arrow button, and a big tilted paper cup with coffee splashing out of it in a curling sheet and flying drops; every line is an uneven, tapered ink stroke that boils gently. In between, the screen clears to a top-view cup where a sketched hand and arm stir with a spoon while a handwritten percentage counts to 100, then the welcome and its splash bounce back in.") { SketchCoffeeSplashDemo() },
    Block(slug = "foil-monogram-splash", name = "Foil Monogram Splash", category = "Splash", spec = "A splash for an invented bakery, Loaven, on a warm espresso screen. Its mark, a knot of two long gold-foil loops crossed like a braided loaf, draws itself on stroke by stroke and weaves over and under at its four crossings, while the name rises letter by letter out of its own baseline in bold serif capitals with a line of small tracked type beneath. A band of light sweeps across the foil, and a finger dragged over the splash moves that light. Then the letters drop away, the knot flies up into the corner of the app's header and an arched doorway opens from the middle onto the app: today's bake, a large photo of country sourdough, two loaves from the shelf and a dark Reserve for pickup button. Tapping the knot in the header plays the splash again.") { FoilMonogramSplashDemo() },
    Block(slug = "kinetic-type-splash", name = "Kinetic Type Splash", category = "Splash", spec = "Kinetic type for a nightlife app's splash on a near-black screen. Huge condensed capitals in cream rise line by line out of their own baselines, letter after letter: \"FIND\", \"YOUR\", then a hot pink word with a soft neon halo that rolls like a slot machine, letter column after letter column, from \"CROWD\" to \"SCENE\" to \"GLOW\". The first two lines leave upwards, \"GLOW\" fills with a photo of a pink neon sign, and the word grows from its first letter until the photo is the whole screen. A welcome settles over it: \"NIGHTJAR\", \"The city after dark, one tap away.\", a line of copy and a cream \"Get started\" button; the button lifts a dark panel over everything and the type starts again.") { KineticTypeSplashDemo() },
    Block(slug = "pill-rise-splash", name = "Pill Rise Splash", category = "Splash", spec = "A flat lime splash with a dark green mark in the middle: two slanted bars passing each other. A dark capsule peeks up from the bottom edge holding a round lime button with an arrow, rises as a tall pill filled with an iridescent swirl, then widens into the whole screen and pushes the mark up and away. The swirl darkens into an onboarding board: a thin three-step progress bar, three glazed jars painted in red, yellow and marbled blue floating at different tilts, gold coins spinning above them and dropping into their mouths, the headline \"90 COUNTRIES, 30 CURRENCIES. ONE WALLET\" in a heavy condensed face, a lime \"See our rates\" link and a full-width lime \"Get started\" button. Pressing the button grows it into a full lime screen and the mark fades back in.") { PillRiseSplashDemo() },
    Block(slug = "accordion-letters", name = "Accordion Letters", category = "Text", spec = "A type-specimen poster on a full-bleed colour: four rows of one repeated capital in a heavy grotesque (Anybody Black), five letters to a row and every row the full width, the letters squeezed to slivers at one end and stretched into wide slabs at the other. A monospaced \"WIDTH AXIS\" bar sits at the top; a heavy two-line title, an A B C indicator and a monospaced hint sit at the bottom. The letter and its palette (blue with pale grey, black with yellow, orange-red with black) cut hard on every beat.") { AccordionLettersDemo() },
    Block(slug = "blur-edge-type-in", name = "Blur Edge Type In", category = "Text", spec = "A writing app's welcome screen on near-black: a four-line headline in tall condensed capitals, a thin progress bar under it, a short grey message, a white pill button and a hint. The headline is typed in letter by letter behind a soft leading edge: the newest letters arrive blurred, faint and spread apart, then sharpen and close up, while an orange caret rides the front and the bar fills.") { BlurEdgeTypeInDemo() },
    Block(slug = "dot-cloud-digits", name = "Dot Cloud Digits", category = "Text", spec = "A month-in-numbers screen on near-black: a big figure such as 29 is outlined by 150 small capitals that spell its own name (TWENTYNINE…) along the glyph's contours, among faint letters of the same name scattered like stars. A tracked header and a page counter sit at the top, a caption and the spelled-out number under the figure, and three page dashes at the bottom; every figure is drawn from the outline of Poppins SemiBold at one shared scale.") { DotCloudDigitsDemo() },
    Block(slug = "falling-word-stickers", name = "Falling Word Stickers", category = "Text", spec = "A light landing screen for a small studio: a black \"Open for new briefs\" badge, a four-line headline in Inter Tight Medium sized to the width, a short line of copy and a black \"Start a project\" pill. Its call to action, \"your next big project starts here\", is six pastel word stickers (coral, orange, sky blue, violet, aqua and mint, \"big\" larger) with small rounded corners and soft shadows, piled at the bottom of the screen, tilted and overlapping. The stickers can be picked up, dragged and thrown.") { FallingWordStickersDemo() },
    Block(slug = "gleam-line-intro", name = "Gleam Line Intro", category = "Text", spec = "The opening screens of a journaling app, told in short lines of Newsreader on pure black: \"Some days are loud. Most of them go unwritten.\", then three stacked lines, then \"Keep them here, one line a day.\" with italic emphasis. Each word arrives with a soft gleam, so a highlight seems to sweep along the line, then settles to a warm grey. Three hairline progress segments run across the top, a quiet \"Tap to continue\" sits at the bottom, and the last beat ends on a white \"Begin writing\" pill.") { GleamLineIntroDemo() },
    Block(slug = "karaoke-lyrics-highlight", name = "Karaoke Lyrics Highlight", category = "Text", spec = "A \"now playing\" lyrics screen for an invented song, \"Paper Satellites\" by Lumen Fair, on a drifting magenta-to-violet field. Big left-aligned lines in Poppins Bold fill the screen and the chorus is sung word by word: each word fills with white behind a soft glowing edge, the line being sung sits in focus, sung lines above dim and blur, and the lines below fade and soften with distance. A header with album art, title, artist and a small live waveform sits at the top, and a slim scrubber with elapsed and remaining time at the bottom.") { KaraokeLyricsHighlightDemo() },
    Block(slug = "kinetic-stats-story", name = "Kinetic Stats Story", category = "Text", spec = "A full-screen year-in-review story for a running app: three cards on a mesh gradient of five soft blobs that drifts from deep teal on the cover to orange, yellow and green on the stats, with story bars, a header with a close button and round pause and share buttons. The cover sets \"Rewind '26\" as large as the width allows; the first card puts a two-line caption over the number 1,284 set at 70% of the screen width, so it is about twice as wide as the screen; the second card runs \"And 212 / sunrise / runs.\" as three lines bigger than the screen. All type is Inter Tight Bold, white, left aligned.") { KineticStatsStoryDemo() },
    Block(slug = "liquid-fill-word", name = "Liquid Fill Word", category = "Text", spec = "A sage-green poster screen built around one huge word, \"Liquid\" in a heavy rounded sans (Paytone One), filled with three flat liquids: pale lime at the bottom, deep green above it and salmon on top, each with its own wavy surface, plus green blobs with salmon cores swirling through the lime near the top. The letter edges wobble like a meniscus, and empty letters stay faintly visible as a darker glass. A small header, a caption, a big level percentage in the same face and a thin meter complete the screen.") { LiquidFillWordDemo() },
    Block(slug = "morphing-title-menu", name = "Morphing Title Menu", category = "Text", spec = "A podcast list whose page title is a menu: a huge condensed ultra-bold heading (Anton, 46 pt) with a small grey up-and-down chevron, a soft Search pill on the right, and below it a date or episode count, three episode rows (cover chip, show, age, a two-line title, progress bar, Pause/Play chip, archive and more buttons) and a floating mini player. Tapping the heading springs a small white popover out from under it with the lists Queue and Favorites, the current one on a grey pill with a black check; picking the other list morphs the heading letter by letter into the new word and cross-fades the list.") { MorphingTitleMenuDemo() },
    Block(slug = "neon-signature-write", name = "Neon Signature Write", category = "Text", spec = "A full-screen neon sign: a handwritten script word (Hurricane), tilted 8° up to the right, burns on a near-black wall in its own two-colour gradient with a soft halo and a pool of light thrown on the wall behind it. A monospaced \"OPEN LATE\" caption with a status dot sits at the top, the sign's number at the right, and the three words of the sign as pills at the bottom, the shown one outlined in its colour.") { NeonSignatureWriteDemo() },
    Block(slug = "revolving-text-ring", name = "Revolving Text Ring", category = "Text", spec = "An open-air festival poster: the festival's name in heavy Archivo Black capitals, \"OPEN AIR •\", wraps a 3D ring seen from slightly above, with a smaller tracked band of dates and place under it, and the far side of the ring shows through the open top, mirrored and faded. A tracked header, a title and subtitle and a full-width pill button complete the screen, and the whole poster inverts between paper-white and near-black.") { RevolvingTextRingDemo() },
    Block(slug = "rgb-glitch-headline", name = "RGB Glitch Headline", category = "Text", spec = "A late-night broadcast teaser: a three-line headline (\"NOTHING IS STATIC\") in a light geometric sans (Jost Light), wide-tracked and centred on a near-black screen with faint scan lines, under a monospaced \"CH 07 NIGHT BROADCAST\" bar with a pulsing red LIVE dot. A line of copy, an outlined \"Remind me\" pill and a monospaced hint sit below. Every so often the headline is hit by signal interference: horizontal slices jump sideways and split into red and cyan copies.") { RgbGlitchHeadlineDemo() },
    Block(slug = "rolling-countdown-digits", name = "Rolling Countdown Digits", category = "Text", spec = "A workout interval timer on near-black: a round label with a breathing lime dot, a lime \"PLANK HOLD\" caption, a huge \"01:02\" in a heavy condensed face, a lime bar with the next exercise under it, and Pause and Skip pill buttons. Each digit that changes rolls in its own clipped window, the old one sliding up and out as the new one rises from below, and the time can be dragged up or down like a counter.") { RollingCountdownDigitsDemo() },
    Block(slug = "rope-text-trail", name = "Rope Text Trail", category = "Text", spec = "An editorial screen on grained off-white paper where a sentence, \"words follow you wherever you go —\", lies along a wave across the middle like a rope of letters, in Instrument Serif with \"you\" in orange italics. The rope's head is a small orange dot just past the closing dash, and the rope follows wherever that head goes. A tracked mono label and issue number over a hairline sit at the top, and a hint with an orange dot at the bottom.") { RopeTextTrailDemo() },
    Block(slug = "scramble-decode-headline", name = "Scramble Decode Headline", category = "Text", spec = "A release-notes hero on near-black (#101114): a four-line headline, \"Always / shipping / something / new.\", set large in Space Grotesk Medium and sized to fit the widest line, under a small outlined badge with a violet dot, with a grey subtitle below and a full-width white pill button at the bottom. Runs of letters keep scrambling into flickering violet glyphs and decoding back into the headline, and a soft violet glow behind it brightens while they do.") { ScrambleDecodeHeadlineDemo() },
    Block(slug = "shred-blur-number", name = "Shred Blur Number", category = "Text", spec = "A festival poster on hot pink with a huge black number in a heavy grotesque, a monospaced header with a rule, and below it a two-line headline, dates, venue and a black pill button. The number shreds into a comb of 36 vertical strips, each showing a squeezed, stretched and shifted slice of the glyphs, melts into a soft grainy blob, comes back out through the strips and settles sharp again strip by strip.") { ShredBlurNumberDemo() },
    Block(slug = "split-flap-board", name = "Split-Flap Board", category = "Text", spec = "A departures board on a charcoal screen: under a small spaced-out \"Departures\" label and a \"Platform 2\" heading, a dark rounded panel holds 4 rows of 7 split-flap cells, each a black card split by a seam line with small hinge blocks between the cells, its magenta letter (Barlow SemiBold) cut in two by the seam. The board spells short messages line by line (\"GATE 4 / OPENS / AT / 09:41\"), with page dots and a hint below.") { SplitFlapBoardDemo() },
    Block(slug = "swipe-flip-word", name = "Swipe Flip Word", category = "Text", spec = "A gesture lesson on a flat violet screen (#430090) whose subject is one huge hot-pink word, \"swipe\", set in Archivo Expanded Black across 80 % of the width. The word sits on a square prism lying along it and rolls over like a twisted ribbon: one end turns away and shrinks while a fresh copy rises from underneath. A tracked lesson label, a two-line lilac caption, page dots and a full-width pink Continue button frame it.") { SwipeFlipWordDemo() },
    Block(slug = "thinking-word-shimmer", name = "Thinking Word Shimmer", category = "Text", spec = "An assistant's working screen on a near-black backdrop lit by soft teal and warm glows: a small \"Assistant\" label and the request in large type at the top, a black rounded card in the middle with one status word at a time (\"Thinking...\", \"Processing...\", \"Analyzing...\", \"Computing...\", \"Almost...\") in Inter SemiBold, five step bars under it marking the current word, and a hint at the bottom.") { ThinkingWordShimmerDemo() },
    Block(slug = "weight-breathing-glyph", name = "Weight Breathing Glyph", category = "Text", spec = "A type specimen screen on light grey paper: one giant capital S, as wide as the screen allows, breathing between hairline and black along a weight axis, with its skeleton drawn over it like a font editor: the control polygon, dots on the on-curve points and rings on the off-curve ones, light where they cross the letter and dark on the paper. The black weight's outline stays behind it as a hairline ghost, guides mark the cap height and the baseline, and below sit the weight in large monospaced figures, its style name (Thin to Black) and an axis from 100 to 900 with a black knob. The outline is Inter Tight's S, kept as the points of its three masters and blended in code, so no font file is needed.") { WeightBreathingGlyphDemo() },
    Block(slug = "weight-wave-wall", name = "Weight Wave Wall", category = "Text", spec = "A focus-sound screen whose background is a wall of the word \"waves\", two words to a row from edge to edge, set in the variable font Epilogue with every letter on its own weight between hairline and black; the heavy letters are bright white and the hairlines dim, so bands of black letters read as surf rolling through the wall. The status bar sits on a fade to black, and the bottom fades into a monospaced kicker, a large title, a line of copy and a white \"Play waves\" pill.") { WeightWaveWallDemo() },
    Block(slug = "bakery-flap-board", name = "Bakery Flap Board", category = "Text", spec = "A split-flap menu board in a small bakery: a walnut-grain case with a brass rim and brass screws, under the bakery's name and a slowly drifting strip of bakery photos. Sixteen charcoal flaps per line, each split across the middle with two brass hinge pins, spell the time in words on two lines and four menu lines below, the names in cream and the prices in amber. When a line changes, every flap falls through the alphabet to its new letter with the real two-half flip, the columns setting off one after another and each landing with a small bounce; now and then the time gives way to a notice such as \"Second bake at half nine\". Tapping a menu line flips it to the next item and grows the line into a cream card with the item's photo, name, a line about it, its price and when it came out of the oven.") { BakeryFlapBoardDemo() },
    Block(slug = "particle-word-morph", name = "Particle Word Morph", category = "Text", spec = "Thousands of small glowing particles spell a single bold word across a deep navy night that is lifted in the middle and darkens towards the corners. Every few seconds the word dissolves into a drifting cloud and the particles flow sideways into the next word, SPARK to DRIFT to BLOOM to ORBIT to GLOW, each particle setting off a moment after its neighbour to the left and swinging along a curved path, while the colours shift across the word from one pair of hues to the next. A finger dragged through the word pushes the particles aside like sand and they spring back behind it; a tap forms the next word. At the bottom the five words sit in a row of small tracked capitals: the one on screen is lit and underlined by a hairline that glides to the next word as it forms, and tapping a word forms it.") { ParticleWordMorphDemo() },
    Block(slug = "spring-letters", name = "Spring Letters", category = "Text", spec = "The word BOUNCE in big candy-coloured letters stands on a peach floor in front of a lilac wall, each letter a glossy extruded block casting a soft shadow on the floor. Every letter is a rigid body on springs, chained to its neighbours: drag one and it follows the finger with a lag and swings from where it was held while the letters beside it are tugged up like a necklace; let go and it is thrown, lands, bounces and rocks back into its slot. A flick up from the floor makes every letter jump in a wave, and a double tap swaps the word: the letters shrink and turn away as the next word (SPRING, WOBBLE, JIGGLE) drops in letter by letter and bounces into place.") { SpringLettersDemo() },
)
